s."},"is_public":false,"appearance":{"build":["Tall","Muscular","Broad-shouldered"],"nails":["Natural"],"eyeHex":["#8A6036"],"height":"TBD","makeup":"","weight":"TBD","hairHex":["#11100F"],"skinHex":["#70472F"],"eyeColor":["Earthy amber-brown"],"grooming":"Well-kept with a rugged natural appearance","skinTone":["Deep warm brown"],"wardrobe":"Layered robes\nLoose trousers\nDraped mantle\nLeather sandals\nOrnamental belts","hairColor":["Black"],"hairStyle":"Long layered hair worn loose and partially pulled back","accessories":"Ornate earrings\nLayered necklaces\nStone rings\nMetal bracers\nDecorative belt\nGemstone ornaments","faceDetails":["Strong angular jaw","Defined cheekbones","Heavy brows","Straight nose"],"hairTexture":["Thick","Wavy"],"colorPalette":"Earth brown #70472F\nObsidian #171512\nForest green #263B2A\nAntique gold #A77A36\nStone gray #716B60","dominantHand":"TBD","outfitColors":"Forest green\nBlack\nEarth brown\nAntique gold\nStone gray","alternateForm":["Mountain-sized Earth Dragon"],"clothingStyle":"Ancient Indian-inspired fantasy clothing suited to the Umbra World''s 500–1300 AD-inspired aesthetic. His clothing should feel ancient, earthy, regal, practical, and connected to stone rather than resembling modern fashion.","appearanceNotes":"Terrance is Terrax''s humanoid form and should retain the same Indian appearance, long black hair, warm brown skin, earthy palette, gold accents, and ancient grounded presence established in his visual references. His design should communicate immense strength without making him look excessively armored.","outfitMaterials":["Woven cloth","Leather","Metal","Stone","Gemstone"],"postureMovement":["Grounded stance","Heavy deliberate movement","Relaxed posture"],"signatureOutfit":"Layered Indian-inspired fantasy robes with dark green draping, black and earth-brown fabrics, antique-gold embroidery, loose trousers, leather sandals, belts, jewelry, and stone-set ornaments.","distinguishingFeatures":["Golden earth markings","Forehead sigil","Long black hair","Ornate earrings","Earth-toned jewelry"]},"created_at":"2026-09-25T06:43:53.695036+00:00","updated_at":"2026-09-25T06:46:41.174643+00:00","is_complete":false,"origin_lore":{"fears":["TBD"],"goals":["Maintain the Telluric Verity","Protect Terrax","Preserve the physical world"],"beliefs":["Everything has weight","The earth remembers","Permanence has value","Resilience comes through endurance"],"culture":["Primordial","Indian-inspired"],"lineage":"Primordial embodiment of Earth","storyArc":"TBD","backstory":"Terrax is an ancient Primordial who embodies Earth itself rather than merely ruling the earth element. His existence is tied to the Telluric Verity, the cosmic truth of permanence, resilience, gravity, weight, and physical memory. He personally rules the land called Terrax while allowing unrelated human and nonhuman civilizations elsewhere to govern themselves.","childhood":"TBD","lifestyle":["Retreats to the Stone Mountains","Spends time with his children","Smokes to relax","Enjoys quiet natural spaces"],"storyRole":"Terrax serves as the Primordial embodiment of Earth and father of Ruchicka, Gaius, and Shailara. His existence establishes the metaphysical foundation of earth, stone, gravity, permanence, and physical memory within the Umbra World.","birthplace":"TBD","psychology":["Extremely patient","Values permanence","Difficult to provoke","Comfortable with silence"],"motivations":["Preserve the earth","Protect his children","Maintain natural stability"],"personality":["Calm","Grounded","Patient","Relaxed","Stoic","Independent"],"voiceSpeech":["Deep voice","Measured speech","Few unnecessary words","Heavy relaxed tone"],"likesDislikes":["Likes smoking","Likes mountains","Likes peace and quiet","Likes relaxing","Dislikes unnecessary disturbance"],"majorLifeEvents":"Became the living embodiment of Earth\nFathered Ruchicka with Shuǐmǔ Lánhuá\nFathered Gaius with Aetheros\nFathered Shailara with a Sylvani elf"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png","relationships":{"allies":"","rivals":"Ignis","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Ruchicka — Oldest child and Bone Dragon\nGaius — Sand Dragon\nShailara — Youngest child and half-Sylvani Stone Dragon","siblings":"","worldConnections":"Shuǐmǔ Lánhuá — Mother of Ruchicka\nAetheros — Mother of Gaius\nEldoria — Homeland of Shailara''s Sylvani family\nStone Mountains — Personal sanctuary\nHeavy Grumble — Devoted human followers\nIronspire Hold — Independent Duroc homeland","relationshipNotes":"Ruchicka is Terrax''s oldest child with Shuǐmǔ Lánhuá and lives primarily with Terrax while maintaining ties to his mother''s water domain. Gaius is Terrax''s child with Aetheros and lives with his father while maintaining ties to his mother''s air domain. Shailara is Terrax''s youngest child, born to a Sylvani elf; she lives with Terrax while remaining connected to her mother''s people in Eldoria."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}','2026-09-25T06:46:45.392218+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('92c8e495-22d4-4228-86f4-81be2c19f24c','studio_characters','b2d998c0-1754-4a6a-af91-281d65ded816','Shuǐmǔ Lánhuá','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b2d998c0-1754-4a6a-af91-281d65ded816","name":"Shuǐmǔ Lánhuá","media":{"tbdFields":"Birth date\nBirthplace\nApparent age\nHeight\nWeight\nDominant hand\nNationality\nExact weaknesses\nExact power limitations\nFormal signature techniques\nPartner status\nFull story arc\nExact sovereignty structure of her children","canonLocks":"Name: Shuǐmǔ Lánhuá\nHuman title: Lady Lánhuá\nDivine title: Shuǐmǔ Tiān Hòu\nFemale\nAsian heritage\nPrimordial\nLiving embodiment of Water\nRules the Sunken Domain\nSunken Domain encompasses the world''s waters\nSunken Domain is not within Aethelgard\nMother of Rahim\nMother of Ife\nMother of Ruchika\nIgnis is father of Rahim and Ife\nTerrax is father of Ruchika\nIfe is the Steam Dragon\nRuchika is the Bone Dragon\nRahim is the Blood Dragon\nRahim is currently lost\nIfe lives with her father\nRuchika lives with his father\nIfe and Ruchika visit their mother\nTrue form is an Eastern-style aquatic leviathan","galleryUrl":"","mediaNotes":"Maintain exact visual continuity between her established portrait, human-form production sheet, dragon form, and dragon production sheet. Future artwork should preserve her face, black hair, ocean-blue eyes, imperial aquatic aesthetic, signature palette, and Eastern-style leviathan design.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nDragon Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Use the established production sheet as the primary visual reference for Lánhuá. Her human design should remain elegant, ancient, and imperial with long black hair, ocean-blue eyes, ornate aquatic hairpieces, and layered blue ceremonial robes. Her dragon form must remain a colossal Eastern-style aquatic leviathan with an elongated serpentine body, iridescent blue-teal scales, luminous aquatic mane, and water-and-mist manifestations.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Unknown","era":"Ancient","name":"Shuǐmǔ Lánhuá","race":"Primordial","alias":"Lady Lánhuá","gender":"Female","titles":"Shuǐmǔ Tiān Hòu\nHeavenly Empress, Mother of All Waters\nThe Splendid Orchid\nMother of All Waters","subrace":"Living Embodiment of Water","summary":"Shuǐmǔ Lánhuá is the ancient Primordial and living embodiment of Water itself. She does not merely command water; oceans, seas, ice, rain, mist, currents, and other natural forms of water are expressions of her primordial existence. Known among mortals as Lady Lánhuá, she rules the Sunken Domain, which encompasses the world''s waters rather than existing within Aethelgard. She is the mother of Rahim, Ife, and Ruchika.","heritage":"Asian","homeland":"Sunken Domain","pronouns":"She/Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign of Water","affiliation":"Sunken Domain","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"The Splendid Orchid, Mother of Waters","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Sunken Domain","elementalHeritage":"Primordial Water"},"abilities":{"weapons":"","strengths":"Elemental fluidity\nExtreme water pressure\nEnvironmental control\nAquatic dominion\nAncient primordial power","weaknesses":"TBD","combatStyle":["Fluid","Defensive","Environmental","Pressure-based","Large-scale elemental control"],"limitations":["TBD"],"powerSource":["Primordial Water","Living embodiment of Water"],"abilityNotes":"Her authority over water comes from being its primordial embodiment, not from conventional learned water magic. Exact limits and interactions with other Primordials remain TBD.\n\nDo not classify Lánhuá as a Dragon Primal who merely rules water. She is a Primordial and the living embodiment of Water itself.","combatProfile":"Lánhuá fights as an elemental force rather than a conventional warrior. She changes water between liquid, ice, mist, and highly compressed states while manipulating currents, pressure, and surrounding moisture. Her movements remain controlled and graceful until extreme anger causes her power to become devastatingly violent.","weaponDetails":"","transformations":"Human Form\nAbyssal Leviathan Form","primaryAbilities":"Absolute water manipulation\nPhase manipulation\nHydrostatic pressure manipulation\nIce manipulation\nMist manipulation\nRain manipulation\nCurrent manipulation\nAbyssal command","secondaryAbilities":"Water compression\nTemperature manipulation\nAquatic telepathy\nSea-life command\nAtmospheric moisture manipulation","signatureTechniques":"TBD","transformationDetails":"Lánhuá can manifest as a colossal Eastern-style aquatic dragon or sea serpent. Her elongated body carries iridescent midnight-blue, teal, and seafoam scales with a flowing bioluminescent mane. Rather than conventional leathery wings, her established dragon design can manifest immense wings formed from compressed water, mist, and atmospheric moisture."},"is_public":false,"appearance":{"build":["Slender","Graceful","Regal"],"nails":["TBD"],"eyeHex":["TBD"],"height":"TBD","makeup":["Subtle","Elegant"],"weight":"TBD","hairHex":["#090D18"],"skinHex":["TBD"],"eyeColor":["Ocean blue"],"grooming":"Immaculate and imperial.","skinTone":["Fair"],"wardrobe":"Layered ceremonial robes\nImperial water-themed gowns\nFlowing silk garments","hairColor":["Black"],"hairStyle":"Very long black hair styled with ornate water-themed hairpieces.","accessories":"Ice orchid hair ornaments\nOrnate hairpins\nWater-drop earrings\nDragon-scale necklace\nWater orb pendant\nJade ornaments","faceDetails":["Elegant features","Regal expression","Refined facial structure"],"hairTexture":["Straight","Silky"],"colorPalette":"Midnight blue #071A33\nDeep teal #07566B\nSeafoam #67C8C2\nTurquoise #46CFE0\nSilver #C8D5DF\nPearl white #EEF3F4","dominantHand":"TBD","outfitColors":"Midnight blue\nDeep teal\nTurquoise\nSilver\nPearl white","alternateForm":["Abyssal Leviathan","Eastern-style sea dragon"],"clothingStyle":"Regal 500–1300 AD-inspired Asian fantasy clothing with flowing silhouettes, layered silks, wave motifs, and refined ornamentation.","appearanceNotes":"Her human design should feel ancient, serene, elegant, and unmistakably connected to the ocean. Her clothing and hair should appear to move with subtle underwater fluidity even on land. Maintain the established midnight-blue, teal, turquoise, silver, and pearl palette across all artwork.","outfitMaterials":["Silk","Translucent silk","Fine embroidery"],"postureMovement":["Poised","Fluid","Controlled"],"signatureOutfit":"Flowing multi-layered imperial robes inspired by 500–1300 AD Asian dress, combining midnight blue, deep teal, silver, and translucent water-like layers. Fine wave and orchid motifs decorate the fabric.","distinguishingFeatures":["Ocean-blue eyes","Very long black hair","Water-themed hair ornaments","Regal presence"]},"created_at":"2026-09-25T06:48:09.359491+00:00","updated_at":"2026-09-25T06:48:09.359491+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Protect the Sunken Domain","Preserve aquatic life","Safeguard her family"],"beliefs":["Water sustains life","Water must remain balanced"],"culture":["Ancient aquatic court","Asian-inspired imperial aesthetic"],"lineage":"Primordial embodiment of Water.","storyArc":"Her larger story arc remains TBD. Rahim''s disappearance creates an unresolved thread within her family, while Ife and Ruchika maintain connections to her domain despite residing with their fathers.","backstory":"Lánhuá is one of the ancient Primordials and the living embodiment of Water. Her sovereignty is not limited to a single ocean or continent; the Sunken Domain encompasses the waters of the world. Her unions with Ignis produced Rahim and Ife, while her union with Terrax produced Ruchika. Although Ife and Ruchika reside with their fathers, they remain connected to their mother''s domain and visit her. Rahim is currently lost, and his absence remains unresolved.","childhood":"TBD","lifestyle":["Rules the Sunken Domain","Oversees the waters of the world","Receives visits from her children"],"storyRole":"Lánhuá serves as the primordial embodiment of Water and sovereign of the Sunken Domain. Her existence connects the oceans, aquatic civilizations, and several elemental bloodlines through her children Rahim, Ife, and Ruchika.","birthplace":"TBD","psychology":["Emotionally restrained","Deeply maternal","Patient observer","Terrifying when enraged"],"motivations":["Protect her children","Preserve the waters","Maintain natural balance"],"personality":["Patient","Calm","Soft-spoken","Graceful","Observant","Maternal","Protective","Formidable"],"voiceSpeech":["Soft-spoken","Measured","Regal","Controlled"],"likesDislikes":["TBD"],"majorLifeEvents":"Union with Ignis\nBirth of Rahim\nBirth of Ife\nUnion with Terrax\nBirth of Ruchika\nRahim disappeared\nIfe resides with Ignis\nRuchika resides with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"TBD","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Rahim — Son; Blood Dragon; child with Ignis; currently lost\nIfe — Daughter; Steam Dragon; child with Ignis; resides with her father and visits Lánhuá\nRuchika — Son; Bone Dragon; child with Terrax; resides with his father and visits Lánhuá","siblings":"","worldConnections":"Ignis — Father of Rahim and Ife\nTerrax — Father of Ruchika\nSunken Domain — Her primordial realm\nWorld waters — Her elemental existence","relationshipNotes":"Lánhuá is the mother of Rahim, Ife, and Ruchika. Rahim and Ife are her children with Ignis, while Ruchika is her child with Terrax. Ife and Ruchika live with their fathers but retain a connection and form of sovereignty within their mother''s waters and continue to visit her. Rahim remains lost; his established disappearance and story should not be overwritten."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"065f06b5-4812-4543-9430-02830d72ae0b","workflow_status":"draft","family_record_id":"3e083a30-190f-4d2e-a61c-605c24c21769","faction_record_id":"9eabcca3-b901-4fdb-92da-03d6ab2a98c5"}','2026-09-25T07:01:11.895221+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('0c8abeff-7d99-4628-b320-ee3efd24fbd1','studio_characters','c48e35c9-e98d-414c-afb7-ae85f99eb649','Atherous','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"c48e35c9-e98d-414c-afb7-ae85f99eb649","name":"Atherous","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nExact age\nApparent age\nExact height\nExact weight\nDominant hand\nNationality\nBirthplace\nChildhood\nStory arc\nSpecific fears\nAbility weaknesses\nAbility limitations","canonLocks":"Atherous is female\nAtherous is Caucasian\nAtherous is a Primordial\nAtherous is the living embodiment of Air\nAtherous is not merely an Air Dragon ruler\nAtherous has silver hair\nAtherous is mother of Ezra\nIgnis is Ezra''s father\nAtherous is mother of Gaius\nTerrax is Gaius''s father\nEzra is the Lightning Dragon\nGaius is the Sand Dragon\nEzra lives primarily with Atherous\nGaius lives primarily with Terrax\nVeritas Volans is Atherous''s primordial truth\nThe Veiled Whisper governs vibration and frequency\nVoid Sky — The Eternal Horizon is an Atherous power\nEchoing Truth is Atherous''s Sonic Blade","galleryUrl":"","mediaNotes":"Existing visual references establish Atherous''s human form, Primordial Air Dragon form, production sheet, and Echoing Truth Sonic Blade. These designs should be treated as the visual continuity reference for future artwork.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Atherous''s established anime/fantasy appearance across every future asset. Her human form uses long silver-white hair, fair porcelain skin, silver-blue eyes, an elegant slender build, flowing white-and-silver clothing, and frost-blue atmospheric effects. Her dragon form remains silver-white and luminous. Echoing Truth must retain its established silver-white sonic and atmospheric design.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Primordial","era":"Primordial Era","name":"Atherous","race":"Primordial","alias":"The Veiled Whisper","gender":"Female","titles":"The Veiled Whisper\nThe Eternal Horizon\nLiving Embodiment of Air","subrace":"God-Prime","summary":"Atherous is the primordial living embodiment of air. She does not simply rule wind or possess air magic; air itself is her elemental existence. Her authority encompasses wind, atmosphere, sound, vibration, frequency, vacuum, storms, flight, motion, and the unseen pathways connecting the world. Her primordial truth is Veritas Volans, the Law of Eternal Change.","heritage":"Caucasian","homeland":"Veylora","pronouns":"She / Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign","affiliation":"Veylora","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Veylora","elementalHeritage":"Primordial Air"},"abilities":{"weapons":"Echoing Truth — Sonic Blade","strengths":"Extreme speed\nAtmospheric control\nLong-range attacks\nSound manipulation\nFrequency control\nAerial mobility\nVacuum creation","weaknesses":"TBD","combatStyle":["Extreme-speed combat","Sonic swordsmanship","Aerial combat","Precision strikes","Battlefield control"],"limitations":["TBD"],"powerSource":["Primordial Air","Veritas Volans","Veiled Whisper"],"abilityNotes":"The Veiled Whisper governs vibration and frequency rather than simple wind manipulation. Atherous can weaponize sound, create vacuums, alter atmospheric pressure, transmit whispers through air, and form sonic cutting forces. Her magic may sound like sharp whistles, cracking whips, or countless distant voices.\n\nAtherous must not be described as merely an Air Dragon who rules air. Her dragon form is a manifestation of her primordial nature; she is the living embodiment of Air itself.","combatProfile":"Atherous specializes in overwhelming speed, aerial mobility, atmospheric control, and precision attacks. Void Sky — The Eternal Horizon allows her movement to resemble teleportation as she slides through the horizon, while residual currents can remain behind as damaging after-images. Horizon Slice allows her to pass an opponent before the displaced air produces the actual cut.","weaponDetails":"Echoing Truth is Atherous''s signature Sonic Blade. It channels her authority over sound, vibration, frequency, and air into a sword capable of producing devastating frequency-based cuts. Its design uses silver-white and frost-blue atmospheric energy consistent with Atherous''s established visual identity.","transformations":"Primordial Air Dragon Form","primaryAbilities":"Atmospheric Command\nWind Manipulation\nStorm Manipulation\nSound Manipulation\nFrequency Manipulation\nVibration Manipulation\nVacuum Creation\nAtmospheric Pressure Control","secondaryAbilities":"Flight\nSonic Blades\nSound-Sight\nLong-Distance Whispering\nAir Removal\nExtreme-Speed Movement","signatureTechniques":"Void Sky — The Eternal Horizon\nThe Severing Current\nHorizon Slice\nThe Echoing Truth\nVacuum — The Absence of Breath","transformationDetails":"Atherous can manifest as a colossal silver-white air dragon with immense wings, an elongated draconic silhouette, luminous pale eyes, and atmospheric energy flowing around her body. The form should retain the same silver, white, and frost-blue palette as her human appearance."},"is_public":false,"appearance":{"build":["Tall","Elegant","Slender"],"nails":["Pale silver"],"eyeHex":["#BFD8EA"],"height":"TBD","makeup":["Subtle cool-toned makeup"],"weight":"TBD","hairHex":["#E8EAF0","#F4F5F7"],"skinHex":["#F2E8E5"],"eyeColor":["Silver-blue"],"grooming":"Immaculate and ethereal","skinTone":["Fair porcelain"],"wardrobe":"Flowing ceremonial gowns\nAir-themed divine garments","hairColor":["Silver-white"],"hairStyle":"Extremely long flowing silver-white hair","accessories":"Silver headpiece\nCrystal ornaments\nSilver jewelry","faceDetails":["Elegant facial structure","High cheekbones","Delicate features"],"hairTexture":["Silky","Flowing"],"colorPalette":"Cloud white #F4F5F7\nSilver #C7CCD6\nFrost blue #BFD8EA\nSky blue #AFCDE3\nMoonlight pearl #E7E5ED","dominantHand":"TBD","outfitColors":"White\nSilver\nFrost blue","alternateForm":["Primordial Air Dragon"],"clothingStyle":"Ethereal fantasy regalia built around flowing layers, silver ornamentation, and lightweight materials that constantly react to surrounding air currents.","appearanceNotes":"Atherous should always appear exceptionally beautiful, ethereal, and nearly weightless. Her hair and clothing should appear affected by invisible currents even while she stands still. Her established visual identity is white, silver, frost blue, and luminous atmospheric effects.","outfitMaterials":["Flowing fabric","Translucent fabric","Silver ornamentation","Crystal accents"],"postureMovement":["Graceful","Weightless","Fluid"],"signatureOutfit":"A flowing white-and-silver fantasy gown with crystalline detailing, layered translucent fabrics, and long wind-swept elements. The silhouette remains elegant and otherworldly while fitting the fantasy identity of the Umbra World.","distinguishingFeatures":["Silver-white hair","Silver-blue eyes","Ethereal beauty","Wind-swept silhouette","White atmospheric aura"]},"created_at":"2026-09-25T06:47:38.069587+00:00","updated_at":"2026-09-25T06:47:38.069587+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Uphold Veritas Volans"],"beliefs":["Nothing should be bound","Change is necessary","Air carries truth"],"culture":["Veyloran"],"lineage":"Primordial embodiment of Air","storyArc":"TBD","backstory":"Atherous is one of the primordial elemental beings of the Umbra World and embodies air itself rather than merely governing it. Her existence encompasses the atmosphere and its movement, allowing her presence to extend wherever air exists. Her primordial truth, Veritas Volans, represents freedom, motion, transition, and eternal change.","childhood":"TBD","lifestyle":["Exists throughout her atmospheric domain","Moves freely through Veylora"],"storyRole":"Atherous serves as the primordial embodiment of Air and sovereign presence of Veylora. Through her, the Umbra World''s wind, atmosphere, sound, vibration, vacuum, and atmospheric motion are connected to a single primordial source.","birthplace":"TBD","psychology":["Values freedom","Rejects stagnation","Embraces change"],"motivations":["Preserve freedom","Maintain atmospheric balance"],"personality":["Elusive","Free-spirited","Graceful","Calm","Independent"],"voiceSpeech":["Soft-spoken","Ethereal","Controlled"],"likesDislikes":["Values freedom","Values movement","Dislikes confinement"],"majorLifeEvents":"Became mother of Ezra with Ignis\nBecame mother of Gaius with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Ignis — Father of Ezra\nTerrax — Father of Gaius","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Ezra — Son with Ignis; Lightning Dragon\nGaius — Son with Terrax; Sand Dragon","siblings":"","worldConnections":"Veylora — Primordial domain\nIgnis — Ezra''s father\nTerrax — Gaius''s father\nEzra — Lightning Dragon son\nGaius — Sand Dragon son","relationshipNotes":"Ezra is the son of Atherous and Ignis and lives primarily with Atherous while retaining a sovereign connection to his father''s domain. Gaius is the son of Atherous and Terrax and lives primarily with Terrax while retaining a sovereign connection to his mother''s domain."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"fd4462c1-d940-4eb8-8105-5ff2b323bc99","workflow_status":"draft","family_record_id":"b32427ed-0baf-457b-8c84-b0266dd31c76","faction_record_id":"efcdcdc6-0a8e-4713-8e49-fce93c606887"}','2026-09-25T07:02:59.565462+00:00');
