INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('8f63db81-43ef-4660-a444-5edbe7261800','studio_characters','b4f84058-548a-4ea6-ac43-f83d7cc7275e','Kusa-No-Shin Durasurya','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b4f84058-548a-4ea6-ac43-f83d7cc7275e","name":"Kusa-No-Shin Durasurya","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nNationality\nCurrent residence\nBirthplace\nParents\nSiblings\nPartner\nWeight\nDominant hand\nChildhood\nDetailed story arc\nSpecific fears\nAbility limitations","canonLocks":"Name: Kusa-No-Shin Durasurya\nAge: 28\nMale\nHe/Him\nDurskari and Sunspear heritage\nHeight: 6''2\"\nDeep bronze-ebony skin\nBlack textured locks\nMint and amethyst eyes\nAdaptive Flux\nEmerald Mirage Style\nVerdant Eclipse\nGrandmother Zu\nKaelen’s crew\nHealer role\nNine-Cloud Nirvana\nEmerald and plum color identity","galleryUrl":"","mediaNotes":"Character portrait and refined visual reference have been created. All future artwork should preserve established facial features, complexion, hair texture and style, lean build, emerald-and-plum clothing palette, dual-state eyes, Grandmother Zu, and Verdant Eclipse.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Needed\nOutfit Breakdown — Needed\nWeapon Reference — Done\nExpression Sheet — Needed\nCombat Reference — Needed\nNine-Cloud Nirvana Reference — Needed\nGrandmother Zu Reference — Done","productionNotes":"Use the refined Kusa-No-Shin artwork as the primary visual direction. Maintain his deep bronze-ebony complexion, textured black locks with braided sides, lean athletic build, emerald-and-plum asymmetrical clothing, dual-colored eyes, Grandmother Zu, and Verdant Eclipse. Future production sheets should preserve the same facial structure and period-inspired fantasy design.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"28","era":"500–1300 AD-inspired fantasy","name":"Kusa-No-Shin Durasurya","race":"Human","alias":"The Flickering Phantom","gender":"Male","titles":"The Flickering Phantom\nThe Emerald Vagabond\nThe Laughing Healer\nThe Keeper of Nine Clouds\nKaelen’s Greatest Headache","subrace":"Durskari-Sunspear","summary":"Kusa-No-Shin Durasurya is a mixed Durskari and Sunspear healer, smoke mage, and swordsman known as the Flickering Phantom. His Adaptive Flux shifts between energetic Sativa Flow, heavy Indica Stasis, and a balanced Hybrid state. Relaxed, compassionate, spiritual, and deceptively formidable, Kusa restores physical and emotional balance while serving as one of Kaelen’s most trusted companions.","heritage":"Durskari and Sunspear","homeland":"Umbral Empire","pronouns":"He/Him","birthDate":"TBD","nicknames":"Kusa","occupation":"Healer, smoke mage, swordsman","affiliation":"Kaelen’s crew","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"TBD","elementalHeritage":"Adaptive Flux"},"abilities":{"weapons":"Verdant Eclipse — Chronic Katana\nGrandmother Zu — Zucca Gourd","strengths":"Battlefield control\nHealing support\nAdaptive combat\nSwordsmanship\nUnpredictable movement\nEmotional awareness\nPain management","weaknesses":"Easily distracted\nUnconventional focus","combatStyle":["Emerald Mirage Style","Durskari rhythm footwork","Sunspear sword forms","Adaptive smoke manipulation"],"limitations":["TBD"],"powerSource":["Adaptive Flux","Smoke magic","Spiritual energy"],"abilityNotes":"Emerald Reprieve suppresses pain and exhaustion temporarily rather than simply closing wounds. Soul Mulch converts negative emotional energy into restorative life force. Gentle Monsoon calms panic and helps restore clarity. His Adaptive Flux is also capable of helping suppress the effects of Kaelen’s Demon Blot.\n\nPreserve the contrast between Kusa’s goofy behavior and genuine spiritual wisdom. His relaxed personality should never erase his competence as a healer and swordsman.","combatProfile":"Kusa fights through constant shifts in tempo. Sativa Flow emphasizes speed and mental overstimulation, while Indica Stasis emphasizes heaviness and battlefield suppression. Hybrid Flux combines both states with deceptive movement, smoke clones, and sensory disruption. His healing techniques allow him to stabilize allies while remaining an active combatant.","weaponDetails":"Verdant Eclipse is an early curved tachi forged from Emerald Steel. Its hollow Dragon-Resin hilt functions as a pipe, while microscopic channels carry magical smoke through the blade. The sword becomes thin and green during Sativa Flow, heavier and violet during Indica Stasis, and semi-transparent with coiling smoke during Hybrid Flux. Grandmother Zu is an ancestral ceremonial gourd decorated with cowrie shells, sandalwood beads, emerald gemstones, and brass Sunspear etchings.","transformations":"Sativa Flow State\nIndica Stasis State\nBalanced Hybrid State\nNine-Cloud Nirvana — Garden of the Emerald Scale","primaryAbilities":"Sativa Flow\nIndica Stasis\nHybrid Flux\nSmoke manipulation\nRestorative balance\nTemporal anaesthesia","secondaryAbilities":"Pain suppression\nEmotional stabilization\nSmoke clones\nSensory disruption\nGravity-like suppression\nCerebral overstimulation","signatureTechniques":"Flux-Flicker Dash\nCouch-Lock Cloud\nGiggling Mist\nEmerald Reprieve\nSoul Mulch\nGentle Monsoon\nBreath of Flux\nNine-Cloud Nirvana","transformationDetails":"Sativa Flow turns both eyes luminous mint with vine-like pupils and emphasizes speed and cerebral energy. Indica Stasis turns both eyes deep violet while emphasizing heaviness and suppression. Balanced Hybrid State preserves one green and one purple eye. Nine-Cloud Nirvana transforms the battlefield into nine floating cloud platforms inhabited by Strain Spirits and manifests the Zenith Dragon."},"is_public":false,"appearance":{"build":["Lean","Athletic"],"nails":["Natural"],"eyeHex":["#86E8B5","#9B72CF"],"height":"6''2\"","makeup":"","weight":"TBD","hairHex":["#171312"],"skinHex":["#6B3F2A","#A66A3F"],"eyeColor":["Mint green","Soft amethyst"],"grooming":"Neatly maintained braids and locks.","skinTone":["Deep bronze-ebony","Golden undertones"],"wardrobe":"Asymmetrical hitare-inspired robe\nLayered trousers\nBraided rope belt\nPeriod sandals","hairColor":["Black"],"hairStyle":"Braided sides with shoulder-length textured locks.","accessories":"Wooden hair beads\nCopper hair rings\nEmerald charms\nCowrie shells\nBeaded necklaces\nGrandmother Zu gourd","faceDetails":["Defined jawline","Relaxed expression","Half-lidded gaze","Lopsided grin"],"hairTexture":["Thick 4C coils","Springy textured locks"],"colorPalette":"Emerald green #2F6B4F\nMint #86E8B5\nDeep plum #4A235A\nAmethyst #9B72CF\nAntique gold #B58A45\nEbony #171312","dominantHand":"TBD","outfitColors":"Emerald green\nDeep plum\nBlack\nAntique gold\nNatural brown","alternateForm":["Sativa Flow State","Indica Stasis State","Balanced Hybrid State","Nine-Cloud Nirvana"],"clothingStyle":"Loose early-period fantasy garments blending Durskari and Sunspear influences. His clothing favors unrestricted movement, natural materials, asymmetry, and an emerald-and-plum visual split representing Adaptive Flux.","appearanceNotes":"His visual identity centers on duality. Emerald represents Sativa Flow and amethyst represents Indica Stasis. In Balanced State, one eye remains mint green and the other amethyst. His design should remain relaxed and approachable even when displaying dangerous magical power.","outfitMaterials":["Woven cloth","Braided rope","Leather","Wood","Copper","Brass"],"postureMovement":["Relaxed posture","Fluid movement","Unpredictable footwork"],"signatureOutfit":"An asymmetrical early-period hitare-inspired robe divided between emerald green and deep plum. A thick braided rope belt secures the layered garments, while Grandmother Zu hangs at his side. Sandals, beads, copper rings, emerald charms, and period-inspired accessories complete the wandering swordsman silhouette.","distinguishingFeatures":["Mint-green left eye","Amethyst right eye","Beaded textured locks","Green smoke wisps","Relaxed grin"]},"created_at":"2026-09-25T06:50:40.496518+00:00","updated_at":"2026-09-25T06:50:40.496518+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Protect Kaelen’s crew","Maintain spiritual balance","Master Adaptive Flux"],"beliefs":["Strength requires peace","Peace requires strength","Balance requires both","Burden should be shared"],"culture":["Durskari","Sunspear"],"lineage":"Mixed Durskari and Sunspear ancestry.","storyArc":"TBD","backstory":"Kusa became known as the Flickering Phantom through his unusual mastery of Adaptive Flux, healing arts, smoke manipulation, and swordsmanship. His connection to the ancestral Zucca Gourd known as Grandmother Zu and his friendship with Kaelen are established parts of his identity. Further details of his early life remain TBD.","childhood":"TBD","lifestyle":["Talks to butterflies","Names rocks","Collects stray spirits","Meditates","Carries herbal supplies"],"storyRole":"Kusa serves as the healer and Adaptive Flux specialist of Kaelen’s crew. His seemingly unserious personality contrasts with his importance to the group, especially when Kaelen’s Demon Blot becomes unstable. He provides physical recovery, emotional grounding, battlefield control, and unpredictable tactical support.","birthplace":"TBD","psychology":["Values emotional balance","Highly empathetic","Observant beneath humor","Comfortable with silence"],"motivations":["Protect his companions","Restore balance","Ease suffering","Keep Kaelen grounded"],"personality":["Compassionate","Emotionally intelligent","Spiritual","Distractible","Goofy","Relaxed","Wise","Unpredictable","Supportive"],"voiceSpeech":["Relaxed speech","Playful observations","Spiritual metaphors","Casual humor","Calls others friend"],"likesDislikes":["Likes peaceful environments","Likes butterflies","Likes nature","Likes good vibes","Dislikes unnecessary tension"],"majorLifeEvents":"Inherited Grandmother Zu\nMastered Adaptive Flux\nJoined Kaelen’s crew\nBecame Kaelen’s trusted healer"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Kaelen — Trusted companion and crew leader","rivals":"","enemies":"","mentors":"","parents":"TBD","partner":"TBD","children":"","siblings":"TBD","worldConnections":"Umbral Empire\nDurskari heritage\nSunspear heritage\nKaelen’s crew","relationshipNotes":"Kusa is one of the people Kaelen trusts completely. Although his relaxed behavior frequently clashes with Kaelen’s structured tactical planning, Kusa understands him deeply. His Adaptive Flux helps prevent the Demon Blot affecting Kaelen’s arm from overwhelming him, and Kusa supports him without fear or judgment."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":"81dcaa1f-296e-4e34-98c5-c69907431fc7","workflow_status":"draft","family_record_id":"c5625a0b-727b-4792-8128-f8aceb92186a","faction_record_id":"f5492e8b-d617-44b1-bce7-517c90d1da55"}','2026-09-25T07:04:54.683934+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('c3592d2e-5c7f-4c8b-8935-c270e83a2588','studio_characters','b6617db7-3178-4a31-bbc6-420bd1e8c605','Xolani','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b6617db7-3178-4a31-bbc6-420bd1e8c605","name":"Xolani","media":{"tbdFields":"Birth date\nExact age\nWeight\nDominant hand\nParents\nSiblings\nPartner\nExact current residence\nFormer mentor name","canonLocks":"Human male\n6''2\" height\nMahogany-charcoal brown skin\nLong black beaded locs\nBrown right eye\nMilky-white left Dead Eye\nCharcoal-grey veins around Dead Eye\nBorn in Kwaye-Zulu\nOriginates from Stone Mountains\nMvula bound to Dead Eye\nUses Asalato in combat\nCreated Dead Eye through forbidden binding\nBlack Rain occurred during Great Drought\nXolani lives as an exile\nMvula was forcibly bound","galleryUrl":"","mediaNotes":"Use the established Xolani production artwork as the primary visual continuity reference. Future portraits, combat artwork, album covers, and production assets should preserve his face, complexion, Dead Eye placement, locs, clothing silhouette, jewelry, and Asalato design.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nCombat Reference — Done","productionNotes":"Maintain Xolani''s established dark anime-fantasy design across all future artwork. His mahogany-charcoal complexion, long beaded locs, lean 6''2\" silhouette, Dead Eye, charcoal veins, layered dark clothing, ritual jewelry, and Asalato are defining visual anchors. Mvula''s manifestations should appear as charcoal shadow, smoke, and ash rather than replacing Xolani''s own silhouette.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Xolani","race":"Human","alias":"","gender":"Male","titles":"The Vessel of Mvula\nThe Reluctant Vessel\nChronicler of Souls","subrace":"","summary":"Xolani is a spirit-bound mystic from Kwaye-Zulu in the Stone Mountains. After using a forbidden Binding Cadence to enslave the restless spirit Mvula during the Great Drought, he was cursed with the Dead Eye and forced to perceive the living and spirit worlds simultaneously. Now an exile, he uses his sacred Asalato and Crossroads magic to protect others while carrying the spiritual debt created by his mistake.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Spirit-bound mystic","affiliation":"Kwaye-Zulu","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"Peace","nationality":"","spoilerLevel":"TBD","pronunciation":"sho-LAH-nee","currentResidence":"Wandering exile","elementalHeritage":""},"abilities":{"weapons":"Sacred Asalato","strengths":"Exceptional rhythm\nSpirit perception\nMental discipline\nPrecise coordination\nBattlefield control\nSpiritual resistance\nClose-range weapon skill","weaknesses":"Silence magic\nBroken rhythm\nSpiritual debt\nConsecrated ground\nSacred salt\nFlorida Water","combatStyle":["Rhythmic combat","Asalato striking","Spiritual disruption","Kinetic control","Short-range teleportation","Psychological warfare"],"limitations":["Magic depends on vibration","Missed rhythms cause backlash","Spirit invocation drains vitality","Mvula can sabotage movement","Cannot harm the truly innocent","13th Gate damages his senses"],"powerSource":["Crossroads spirit magic","Asalato rhythm","Mvula''s spiritual influence","Dead Eye"],"abilityNotes":"The swish of the Asalato sustains flow-based effects while the clack acts as a spiritual trigger. Xolani''s strongest techniques depend on uninterrupted timing. His Dead Eye allows direct perception of spirits and can expose others to the Grey Space through Eye-Lock.","combatProfile":"Xolani fights through rhythm rather than brute force. Continuous Asalato patterns control movement, summon spiritual interference, distort kinetic energy, and create openings for precise physical strikes. Mvula can either disrupt Xolani''s coordination or protect him from lethal attacks, making every battle a simultaneous struggle against the enemy and the spirit within him.","weaponDetails":"Xolani fights with paired Asalato, also known as Kashaka or shaker balls. Their swish sustains rhythmic magic while their clack releases or locks spiritual force. His combat set is reinforced for physical strikes and spiritually linked to Mvula.","transformations":"The 13th Gate state","primaryAbilities":"Rattling Call\nSoul-Clack\nPapa Legba''s Gate\nEye-Lock","secondaryAbilities":"Syncopated Stasis\nSpirit perception\nKinetic distortion\nSpectral summoning\nSpiritual binding","signatureTechniques":"Crossroads Cadence\nPolyrhythmic Paradox\nLateral Click — X-Snap\nThe Stillness\nThe 13th Gate","transformationDetails":"During The 13th Gate, Xolani breaks open his Asalato and spills their spirit dirt around himself, temporarily becoming a manifestation of the Crossroads. For roughly sixty seconds, his spiritual perception and temporal attacks become extreme. The technique leaves him temporarily blind and deaf afterward."},"is_public":false,"appearance":{"build":["Wiry","Sinewy","Lean"],"nails":["Natural dark nails"],"eyeHex":["#4A2D1C","#E5E1D8"],"height":"6''2\" (188 cm)","makeup":"","weight":"TBD","hairHex":["#0B0908"],"skinHex":["#593A2D","#3E2A23"],"eyeColor":["Right eye — deep brown","Left eye — milky white"],"grooming":"Weathered but deliberate","skinTone":["Mahogany-charcoal brown"],"wardrobe":"Tattered cloak\nLayered wraps\nLoose trousers\nLeather footwear\nWeathered work clothing","hairColor":["Black"],"hairStyle":"Long voluminous locs with beads","accessories":"Beaded necklaces\nRitual charms\nBone tokens\nMetal rings\nTobacco pouch\nSmall rum flask","faceDetails":["High sharp cheekbones","Straight nose","Strong elegant jawline"],"hairTexture":["Locs"],"colorPalette":"Charcoal black\nEarth brown\nAsh grey\nAntique bronze\nBone white","dominantHand":"TBD","outfitColors":"#0D0C0B\n#211B18\n#4A382B\n#8A6743\n#B9B0A2","alternateForm":"","clothingStyle":"Practical Stone Mountains attire with dark layered fabrics, weathered materials, beadwork, ritual accessories, and an understated mystical silhouette suited to a wandering spirit practitioner.","appearanceNotes":"Xolani should appear striking and regal despite his exhausted, haunted presence. His right eye remains naturally brown while the left Dead Eye is completely milky-white and pupil-less. Fine charcoal-grey veins radiate from the left socket and become more pronounced when Mvula is active.","outfitMaterials":["Worn cloth","Leather","Canvas","Wood","Bone","Metal"],"postureMovement":["Predatory grace","Controlled movements","Rhythmic hand movement"],"signatureOutfit":"Layered dark ritual clothing with a weathered cloak, practical wraps, loose trousers, leather footwear, beadwork, necklaces, and subtle spiritual symbols. His clothing is worn and functional rather than ceremonial.","distinguishingFeatures":["Milky-white Dead Eye","Charcoal-grey eye veins","Scarred hands","Calloused palms","Ash-stained fingertips","Cold left hand","Long beaded locs"]},"created_at":"2026-09-25T06:50:56.828975+00:00","updated_at":"2026-09-25T06:50:56.828975+00:00","is_complete":true,"origin_lore":{"fears":["Losing control to Mvula","Repeating his original mistake","Being pulled into the spirit realm","Mvula being forgotten","Breaking his rhythm in combat"],"goals":["Find spiritual peace","Atone for binding Mvula","Protect others from restless spirits","Keep Mvula from being forgotten"],"beliefs":["Every soul deserves remembrance","Spirits are not servants","Power creates responsibility","The dead deserve dignity","Peace requires accountability"],"culture":["Kwaye-Zulu","High Crossroads keepers","Rhythm-based spiritual tradition"],"lineage":"Kwaye-Zulu spiritual tradition","storyArc":"Xolani begins as a guilt-ridden exile enduring Mvula''s hatred as punishment for his past. Through remembrance, shared rituals, and stubborn compassion, their parasitic bond gradually develops into reluctant mutual recognition. His journey centers on accountability, remembrance, and discovering whether peace can exist without erasing what happened.","backstory":"During the Great Drought, Xolani became desperate to save his starving village. Against his master''s warnings, he climbed to the Altar of the Unburied and used a forbidden Binding Cadence to imprison the restless spirit Mvula within his Asalato. The ritual produced Black Rain and saved the village, but Mvula retaliated by spiritually overwriting Xolani''s left eye, creating the Dead Eye. Marked by the curse and ashamed of what he had done, Xolani left Kwaye-Zulu and became a wandering protector who works to repay his debt to the spirit world.","childhood":"Xolani grew up in Kwaye-Zulu, where rhythm was woven into birth, mourning, spiritual practice, and everyday life. He showed unusual sensitivity to spirits and became a talented apprentice in the village''s spiritual traditions.","lifestyle":["Wanders between settlements","Handles dangerous spirit problems","Practices rhythmic meditation","Carries ritual offerings","Keeps his Asalato nearby"],"storyRole":"Xolani serves as a bridge between the living and the forgotten dead. His abilities make him exceptionally dangerous against spiritual threats, while his relationship with Mvula forces him to confront the consequences of treating a suffering soul as a source of power.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Burdened by guilt","Spiritually exhausted","Highly self-controlled","Protective of forgotten souls","Resists Mvula''s influence"],"motivations":["Repay his spiritual debt","Protect the living","Remember forgotten souls","Preserve Mvula''s memory","Prevent similar mistakes"],"personality":["Stoic","Weary","Reserved","Compassionate","Remorseful","Protective","Disciplined","Observant","Stubborn"],"voiceSpeech":["Deep soulful baritone","Quiet delivery","Measured speech","Few words","Emotionally restrained"],"likesDislikes":["Likes rainfall","Likes natural beauty","Values quiet","Values remembrance","Dislikes spiritual exploitation","Dislikes arrogant magic"],"majorLifeEvents":"Born in Kwaye-Zulu\nTrained in spiritual rhythms\nGreat Drought strikes Kwaye-Zulu\nClimbs the Altar of the Unburied\nBinds Mvula against his will\nSummons the Black Rain\nReceives the Dead Eye curse\nLeaves Kwaye-Zulu in exile\nBecomes a wandering spirit protector\nDevelops The Stillness"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Mvula — Bound spirit and reluctant guardian\nSekani — Ally and musical counterpart","rivals":"","enemies":"","mentors":"Kwaye-Zulu village elder — Former spiritual mentor","parents":"","partner":"TBD","children":"","siblings":"","worldConnections":"Stone Mountains\nKwaye-Zulu\nAltar of the Unburied\nHigh Crossroads\nGrey Space","relationshipNotes":"Xolani and Mvula began as jailer and captive after Xolani forcibly bound the spirit during the Great Drought. Mvula initially tormented and sabotaged him, but Xolani''s refusal to forget Mvula''s human life gradually changes their relationship. They remain spiritually fused, contentious, and emotionally complicated, with Mvula increasingly protecting the only living person who continues to remember him."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":"c6c8934d-b274-44f7-a1a6-a6f8f959654b","workflow_status":"draft","family_record_id":"2ff89f94-94cb-4de0-a6a8-8b4e3925f455","faction_record_id":"cb4c27cc-2adb-4d75-92b0-a1cabfa13127"}','2026-09-25T07:07:07.236705+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('94c157ac-6d6f-4b2b-9547-81abfe07c51d','studio_characters','c48e35c9-e98d-414c-afb7-ae85f99eb649','Atherous','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"c48e35c9-e98d-414c-afb7-ae85f99eb649","name":"Atherous","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nExact age\nApparent age\nExact height\nExact weight\nDominant hand\nNationality\nBirthplace\nChildhood\nStory arc\nSpecific fears\nAbility weaknesses\nAbility limitations","canonLocks":"Atherous is female\nAtherous is Caucasian\nAtherous is a Primordial\nAtherous is the living embodiment of Air\nAtherous is not merely an Air Dragon ruler\nAtherous has silver hair\nAtherous is mother of Ezra\nIgnis is Ezra''s father\nAtherous is mother of Gaius\nTerrax is Gaius''s father\nEzra is the Lightning Dragon\nGaius is the Sand Dragon\nEzra lives primarily with Atherous\nGaius lives primarily with Terrax\nVeritas Volans is Atherous''s primordial truth\nThe Veiled Whisper governs vibration and frequency\nVoid Sky — The Eternal Horizon is an Atherous power\nEchoing Truth is Atherous''s Sonic Blade","galleryUrl":"","mediaNotes":"Existing visual references establish Atherous''s human form, Primordial Air Dragon form, production sheet, and Echoing Truth Sonic Blade. These designs should be treated as the visual continuity reference for future artwork.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Atherous''s established anime/fantasy appearance across every future asset. Her human form uses long silver-white hair, fair porcelain skin, silver-blue eyes, an elegant slender build, flowing white-and-silver clothing, and frost-blue atmospheric effects. Her dragon form remains silver-white and luminous. Echoing Truth must retain its established silver-white sonic and atmospheric design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/reference/1790319737660-aetheros-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/alternate/1790319744447-aetheros-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Primordial","era":"Primordial Era","name":"Atherous","race":"Primordial","alias":"The Veiled Whisper","gender":"Female","titles":"The Veiled Whisper\nThe Eternal Horizon\nLiving Embodiment of Air","subrace":"God-Prime","summary":"Atherous is the primordial living embodiment of air. She does not simply rule wind or possess air magic; air itself is her elemental existence. Her authority encompasses wind, atmosphere, sound, vibration, frequency, vacuum, storms, flight, motion, and the unseen pathways connecting the world. Her primordial truth is Veritas Volans, the Law of Eternal Change.","heritage":"Caucasian","homeland":"Veylora","pronouns":"She / Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign","affiliation":"Veylora","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Veylora","elementalHeritage":"Primordial Air"},"abilities":{"weapons":"Echoing Truth — Sonic Blade","strengths":"Extreme speed\nAtmospheric control\nLong-range attacks\nSound manipulation\nFrequency control\nAerial mobility\nVacuum creation","weaknesses":"TBD","combatStyle":["Extreme-speed combat","Sonic swordsmanship","Aerial combat","Precision strikes","Battlefield control"],"limitations":["TBD"],"powerSource":["Primordial Air","Veritas Volans","Veiled Whisper"],"abilityNotes":"The Veiled Whisper governs vibration and frequency rather than simple wind manipulation. Atherous can weaponize sound, create vacuums, alter atmospheric pressure, transmit whispers through air, and form sonic cutting forces. Her magic may sound like sharp whistles, cracking whips, or countless distant voices.\n\nAtherous must not be described as merely an Air Dragon who rules air. Her dragon form is a manifestation of her primordial nature; she is the living embodiment of Air itself.","combatProfile":"Atherous specializes in overwhelming speed, aerial mobility, atmospheric control, and precision attacks. Void Sky — The Eternal Horizon allows her movement to resemble teleportation as she slides through the horizon, while residual currents can remain behind as damaging after-images. Horizon Slice allows her to pass an opponent before the displaced air produces the actual cut.","weaponDetails":"Echoing Truth is Atherous''s signature Sonic Blade. It channels her authority over sound, vibration, frequency, and air into a sword capable of producing devastating frequency-based cuts. Its design uses silver-white and frost-blue atmospheric energy consistent with Atherous''s established visual identity.","transformations":"Primordial Air Dragon Form","primaryAbilities":"Atmospheric Command\nWind Manipulation\nStorm Manipulation\nSound Manipulation\nFrequency Manipulation\nVibration Manipulation\nVacuum Creation\nAtmospheric Pressure Control","secondaryAbilities":"Flight\nSonic Blades\nSound-Sight\nLong-Distance Whispering\nAir Removal\nExtreme-Speed Movement","signatureTechniques":"Void Sky — The Eternal Horizon\nThe Severing Current\nHorizon Slice\nThe Echoing Truth\nVacuum — The Absence of Breath","transformationDetails":"Atherous can manifest as a colossal silver-white air dragon with immense wings, an elongated draconic silhouette, luminous pale eyes, and atmospheric energy flowing around her body. The form should retain the same silver, white, and frost-blue palette as her human appearance."},"is_public":false,"appearance":{"build":["Tall","Elegant","Slender"],"nails":["Pale silver"],"eyeHex":["#BFD8EA"],"height":"TBD","makeup":["Subtle cool-toned makeup"],"weight":"TBD","hairHex":["#E8EAF0","#F4F5F7"],"skinHex":["#F2E8E5"],"eyeColor":["Silver-blue"],"grooming":"Immaculate and ethereal","skinTone":["Fair porcelain"],"wardrobe":"Flowing ceremonial gowns\nAir-themed divine garments","hairColor":["Silver-white"],"hairStyle":"Extremely long flowing silver-white hair","accessories":"Silver headpiece\nCrystal ornaments\nSilver jewelry","faceDetails":["Elegant facial structure","High cheekbones","Delicate features"],"hairTexture":["Silky","Flowing"],"colorPalette":"Cloud white #F4F5F7\nSilver #C7CCD6\nFrost blue #BFD8EA\nSky blue #AFCDE3\nMoonlight pearl #E7E5ED","dominantHand":"TBD","outfitColors":"White\nSilver\nFrost blue","alternateForm":["Primordial Air Dragon"],"clothingStyle":"Ethereal fantasy regalia built around flowing layers, silver ornamentation, and lightweight materials that constantly react to surrounding air currents.","appearanceNotes":"Atherous should always appear exceptionally beautiful, ethereal, and nearly weightless. Her hair and clothing should appear affected by invisible currents even while she stands still. Her established visual identity is white, silver, frost blue, and luminous atmospheric effects.","outfitMaterials":["Flowing fabric","Translucent fabric","Silver ornamentation","Crystal accents"],"postureMovement":["Graceful","Weightless","Fluid"],"signatureOutfit":"A flowing white-and-silver fantasy gown with crystalline detailing, layered translucent fabrics, and long wind-swept elements. The silhouette remains elegant and otherworldly while fitting the fantasy identity of the Umbra World.","distinguishingFeatures":["Silver-white hair","Silver-blue eyes","Ethereal beauty","Wind-swept silhouette","White atmospheric aura"]},"created_at":"2026-09-25T06:47:38.069587+00:00","updated_at":"2026-09-25T07:03:05.25324+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Uphold Veritas Volans"],"beliefs":["Nothing should be bound","Change is necessary","Air carries truth"],"culture":["Veyloran"],"lineage":"Primordial embodiment of Air","storyArc":"TBD","backstory":"Atherous is one of the primordial elemental beings of the Umbra World and embodies air itself rather than merely governing it. Her existence encompasses the atmosphere and its movement, allowing her presence to extend wherever air exists. Her primordial truth, Veritas Volans, represents freedom, motion, transition, and eternal change.","childhood":"TBD","lifestyle":["Exists throughout her atmospheric domain","Moves freely through Veylora"],"storyRole":"Atherous serves as the primordial embodiment of Air and sovereign presence of Veylora. Through her, the Umbra World''s wind, atmosphere, sound, vibration, vacuum, and atmospheric motion are connected to a single primordial source.","birthplace":"TBD","psychology":["Values freedom","Rejects stagnation","Embraces change"],"motivations":["Preserve freedom","Maintain atmospheric balance"],"personality":["Elusive","Free-spirited","Graceful","Calm","Independent"],"voiceSpeech":["Soft-spoken","Ethereal","Controlled"],"likesDislikes":["Values freedom","Values movement","Dislikes confinement"],"majorLifeEvents":"Became mother of Ezra with Ignis\nBecame mother of Gaius with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png","relationships":{"allies":"Ignis — Father of Ezra\nTerrax — Father of Gaius","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Ezra — Son with Ignis; Lightning Dragon\nGaius — Son with Terrax; Sand Dragon","siblings":"","worldConnections":"Veylora — Primordial domain\nIgnis — Ezra''s father\nTerrax — Gaius''s father\nEzra — Lightning Dragon son\nGaius — Sand Dragon son","relationshipNotes":"Ezra is the son of Atherous and Ignis and lives primarily with Atherous while retaining a sovereign connection to his father''s domain. Gaius is the son of Atherous and Terrax and lives primarily with Terrax while retaining a sovereign connection to his mother''s domain."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"fd4462c1-d940-4eb8-8105-5ff2b323bc99","workflow_status":"draft","family_record_id":"b32427ed-0baf-457b-8c84-b0266dd31c76","faction_record_id":"efcdcdc6-0a8e-4713-8e49-fce93c606887"}','2026-09-25T07:08:38.778584+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('0f2561d1-5a05-4269-af2a-e1f5124fdfb2','studio_characters','b4f84058-548a-4ea6-ac43-f83d7cc7275e','Kusa-No-Shin Durasurya','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b4f84058-548a-4ea6-ac43-f83d7cc7275e","name":"Kusa-No-Shin Durasurya","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nNationality\nCurrent residence\nBirthplace\nParents\nSiblings\nPartner\nWeight\nDominant hand\nChildhood\nDetailed story arc\nSpecific fears\nAbility limitations","canonLocks":"Name: Kusa-No-Shin Durasurya\nAge: 28\nMale\nHe/Him\nDurskari and Sunspear heritage\nHeight: 6''2\"\nDeep bronze-ebony skin\nBlack textured locks\nMint and amethyst eyes\nAdaptive Flux\nEmerald Mirage Style\nVerdant Eclipse\nGrandmother Zu\nKaelen’s crew\nHealer role\nNine-Cloud Nirvana\nEmerald and plum color identity","galleryUrl":"","mediaNotes":"Character portrait and refined visual reference have been created. All future artwork should preserve established facial features, complexion, hair texture and style, lean build, emerald-and-plum clothing palette, dual-state eyes, Grandmother Zu, and Verdant Eclipse.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/portrait/1790319871004-kusa-no-shin-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Needed\nOutfit Breakdown — Needed\nWeapon Reference — Done\nExpression Sheet — Needed\nCombat Reference — Needed\nNine-Cloud Nirvana Reference — Needed\nGrandmother Zu Reference — Done","productionNotes":"Use the refined Kusa-No-Shin artwork as the primary visual direction. Maintain his deep bronze-ebony complexion, textured black locks with braided sides, lean athletic build, emerald-and-plum asymmetrical clothing, dual-colored eyes, Grandmother Zu, and Verdant Eclipse. Future production sheets should preserve the same facial structure and period-inspired fantasy design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/reference/1790319878935-kus-no-shin-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/alternate/1790319885670-kusa-no-shin-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"28","era":"500–1300 AD-inspired fantasy","name":"Kusa-No-Shin Durasurya","race":"Human","alias":"The Flickering Phantom","gender":"Male","titles":"The Flickering Phantom\nThe Emerald Vagabond\nThe Laughing Healer\nThe Keeper of Nine Clouds\nKaelen’s Greatest Headache","subrace":"Durskari-Sunspear","summary":"Kusa-No-Shin Durasurya is a mixed Durskari and Sunspear healer, smoke mage, and swordsman known as the Flickering Phantom. His Adaptive Flux shifts between energetic Sativa Flow, heavy Indica Stasis, and a balanced Hybrid state. Relaxed, compassionate, spiritual, and deceptively formidable, Kusa restores physical and emotional balance while serving as one of Kaelen’s most trusted companions.","heritage":"Durskari and Sunspear","homeland":"Umbral Empire","pronouns":"He/Him","birthDate":"TBD","nicknames":"Kusa","occupation":"Healer, smoke mage, swordsman","affiliation":"Kaelen’s crew","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"TBD","elementalHeritage":"Adaptive Flux"},"abilities":{"weapons":"Verdant Eclipse — Chronic Katana\nGrandmother Zu — Zucca Gourd","strengths":"Battlefield control\nHealing support\nAdaptive combat\nSwordsmanship\nUnpredictable movement\nEmotional awareness\nPain management","weaknesses":"Easily distracted\nUnconventional focus","combatStyle":["Emerald Mirage Style","Durskari rhythm footwork","Sunspear sword forms","Adaptive smoke manipulation"],"limitations":["TBD"],"powerSource":["Adaptive Flux","Smoke magic","Spiritual energy"],"abilityNotes":"Emerald Reprieve suppresses pain and exhaustion temporarily rather than simply closing wounds. Soul Mulch converts negative emotional energy into restorative life force. Gentle Monsoon calms panic and helps restore clarity. His Adaptive Flux is also capable of helping suppress the effects of Kaelen’s Demon Blot.\n\nPreserve the contrast between Kusa’s goofy behavior and genuine spiritual wisdom. His relaxed personality should never erase his competence as a healer and swordsman.","combatProfile":"Kusa fights through constant shifts in tempo. Sativa Flow emphasizes speed and mental overstimulation, while Indica Stasis emphasizes heaviness and battlefield suppression. Hybrid Flux combines both states with deceptive movement, smoke clones, and sensory disruption. His healing techniques allow him to stabilize allies while remaining an active combatant.","weaponDetails":"Verdant Eclipse is an early curved tachi forged from Emerald Steel. Its hollow Dragon-Resin hilt functions as a pipe, while microscopic channels carry magical smoke through the blade. The sword becomes thin and green during Sativa Flow, heavier and violet during Indica Stasis, and semi-transparent with coiling smoke during Hybrid Flux. Grandmother Zu is an ancestral ceremonial gourd decorated with cowrie shells, sandalwood beads, emerald gemstones, and brass Sunspear etchings.","transformations":"Sativa Flow State\nIndica Stasis State\nBalanced Hybrid State\nNine-Cloud Nirvana — Garden of the Emerald Scale","primaryAbilities":"Sativa Flow\nIndica Stasis\nHybrid Flux\nSmoke manipulation\nRestorative balance\nTemporal anaesthesia","secondaryAbilities":"Pain suppression\nEmotional stabilization\nSmoke clones\nSensory disruption\nGravity-like suppression\nCerebral overstimulation","signatureTechniques":"Flux-Flicker Dash\nCouch-Lock Cloud\nGiggling Mist\nEmerald Reprieve\nSoul Mulch\nGentle Monsoon\nBreath of Flux\nNine-Cloud Nirvana","transformationDetails":"Sativa Flow turns both eyes luminous mint with vine-like pupils and emphasizes speed and cerebral energy. Indica Stasis turns both eyes deep violet while emphasizing heaviness and suppression. Balanced Hybrid State preserves one green and one purple eye. Nine-Cloud Nirvana transforms the battlefield into nine floating cloud platforms inhabited by Strain Spirits and manifests the Zenith Dragon."},"is_public":false,"appearance":{"build":["Lean","Athletic"],"nails":["Natural"],"eyeHex":["#86E8B5","#9B72CF"],"height":"6''2\"","makeup":"","weight":"TBD","hairHex":["#171312"],"skinHex":["#6B3F2A","#A66A3F"],"eyeColor":["Mint green","Soft amethyst"],"grooming":"Neatly maintained braids and locks.","skinTone":["Deep bronze-ebony","Golden undertones"],"wardrobe":"Asymmetrical hitare-inspired robe\nLayered trousers\nBraided rope belt\nPeriod sandals","hairColor":["Black"],"hairStyle":"Braided sides with shoulder-length textured locks.","accessories":"Wooden hair beads\nCopper hair rings\nEmerald charms\nCowrie shells\nBeaded necklaces\nGrandmother Zu gourd","faceDetails":["Defined jawline","Relaxed expression","Half-lidded gaze","Lopsided grin"],"hairTexture":["Thick 4C coils","Springy textured locks"],"colorPalette":"Emerald green #2F6B4F\nMint #86E8B5\nDeep plum #4A235A\nAmethyst #9B72CF\nAntique gold #B58A45\nEbony #171312","dominantHand":"TBD","outfitColors":"Emerald green\nDeep plum\nBlack\nAntique gold\nNatural brown","alternateForm":["Sativa Flow State","Indica Stasis State","Balanced Hybrid State","Nine-Cloud Nirvana"],"clothingStyle":"Loose early-period fantasy garments blending Durskari and Sunspear influences. His clothing favors unrestricted movement, natural materials, asymmetry, and an emerald-and-plum visual split representing Adaptive Flux.","appearanceNotes":"His visual identity centers on duality. Emerald represents Sativa Flow and amethyst represents Indica Stasis. In Balanced State, one eye remains mint green and the other amethyst. His design should remain relaxed and approachable even when displaying dangerous magical power.","outfitMaterials":["Woven cloth","Braided rope","Leather","Wood","Copper","Brass"],"postureMovement":["Relaxed posture","Fluid movement","Unpredictable footwork"],"signatureOutfit":"An asymmetrical early-period hitare-inspired robe divided between emerald green and deep plum. A thick braided rope belt secures the layered garments, while Grandmother Zu hangs at his side. Sandals, beads, copper rings, emerald charms, and period-inspired accessories complete the wandering swordsman silhouette.","distinguishingFeatures":["Mint-green left eye","Amethyst right eye","Beaded textured locks","Green smoke wisps","Relaxed grin"]},"created_at":"2026-09-25T06:50:40.496518+00:00","updated_at":"2026-09-25T07:04:54.683934+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Protect Kaelen’s crew","Maintain spiritual balance","Master Adaptive Flux"],"beliefs":["Strength requires peace","Peace requires strength","Balance requires both","Burden should be shared"],"culture":["Durskari","Sunspear"],"lineage":"Mixed Durskari and Sunspear ancestry.","storyArc":"TBD","backstory":"Kusa became known as the Flickering Phantom through his unusual mastery of Adaptive Flux, healing arts, smoke manipulation, and swordsmanship. His connection to the ancestral Zucca Gourd known as Grandmother Zu and his friendship with Kaelen are established parts of his identity. Further details of his early life remain TBD.","childhood":"TBD","lifestyle":["Talks to butterflies","Names rocks","Collects stray spirits","Meditates","Carries herbal supplies"],"storyRole":"Kusa serves as the healer and Adaptive Flux specialist of Kaelen’s crew. His seemingly unserious personality contrasts with his importance to the group, especially when Kaelen’s Demon Blot becomes unstable. He provides physical recovery, emotional grounding, battlefield control, and unpredictable tactical support.","birthplace":"TBD","psychology":["Values emotional balance","Highly empathetic","Observant beneath humor","Comfortable with silence"],"motivations":["Protect his companions","Restore balance","Ease suffering","Keep Kaelen grounded"],"personality":["Compassionate","Emotionally intelligent","Spiritual","Distractible","Goofy","Relaxed","Wise","Unpredictable","Supportive"],"voiceSpeech":["Relaxed speech","Playful observations","Spiritual metaphors","Casual humor","Calls others friend"],"likesDislikes":["Likes peaceful environments","Likes butterflies","Likes nature","Likes good vibes","Dislikes unnecessary tension"],"majorLifeEvents":"Inherited Grandmother Zu\nMastered Adaptive Flux\nJoined Kaelen’s crew\nBecame Kaelen’s trusted healer"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/portrait/1790319871004-kusa-no-shin-character-portrait.png","relationships":{"allies":"Kaelen — Trusted companion and crew leader","rivals":"","enemies":"","mentors":"","parents":"TBD","partner":"TBD","children":"","siblings":"TBD","worldConnections":"Umbral Empire\nDurskari heritage\nSunspear heritage\nKaelen’s crew","relationshipNotes":"Kusa is one of the people Kaelen trusts completely. Although his relaxed behavior frequently clashes with Kaelen’s structured tactical planning, Kusa understands him deeply. His Adaptive Flux helps prevent the Demon Blot affecting Kaelen’s arm from overwhelming him, and Kusa supports him without fear or judgment."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":"81dcaa1f-296e-4e34-98c5-c69907431fc7","workflow_status":"draft","family_record_id":"c5625a0b-727b-4792-8128-f8aceb92186a","faction_record_id":"f5492e8b-d617-44b1-bce7-517c90d1da55"}','2026-09-25T07:08:43.146966+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('a5101c9c-def3-4b5e-940f-38c7a8294f36','studio_characters','b6617db7-3178-4a31-bbc6-420bd1e8c605','Xolani','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b6617db7-3178-4a31-bbc6-420bd1e8c605","name":"Xolani","media":{"tbdFields":"Birth date\nExact age\nWeight\nDominant hand\nParents\nSiblings\nPartner\nExact current residence\nFormer mentor name","canonLocks":"Human male\n6''2\" height\nMahogany-charcoal brown skin\nLong black beaded locs\nBrown right eye\nMilky-white left Dead Eye\nCharcoal-grey veins around Dead Eye\nBorn in Kwaye-Zulu\nOriginates from Stone Mountains\nMvula bound to Dead Eye\nUses Asalato in combat\nCreated Dead Eye through forbidden binding\nBlack Rain occurred during Great Drought\nXolani lives as an exile\nMvula was forcibly bound","galleryUrl":"","mediaNotes":"Use the established Xolani production artwork as the primary visual continuity reference. Future portraits, combat artwork, album covers, and production assets should preserve his face, complexion, Dead Eye placement, locs, clothing silhouette, jewelry, and Asalato design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/portrait/1790320005150-xolani-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nCombat Reference — Done","productionNotes":"Maintain Xolani''s established dark anime-fantasy design across all future artwork. His mahogany-charcoal complexion, long beaded locs, lean 6''2\" silhouette, Dead Eye, charcoal veins, layered dark clothing, ritual jewelry, and Asalato are defining visual anchors. Mvula''s manifestations should appear as charcoal shadow, smoke, and ash rather than replacing Xolani''s own silhouette.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/reference/1790320018088-xolani-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/alternate/1790320022686-xolani-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Xolani","race":"Human","alias":"","gender":"Male","titles":"The Vessel of Mvula\nThe Reluctant Vessel\nChronicler of Souls","subrace":"","summary":"Xolani is a spirit-bound mystic from Kwaye-Zulu in the Stone Mountains. After using a forbidden Binding Cadence to enslave the restless spirit Mvula during the Great Drought, he was cursed with the Dead Eye and forced to perceive the living and spirit worlds simultaneously. Now an exile, he uses his sacred Asalato and Crossroads magic to protect others while carrying the spiritual debt created by his mistake.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Spirit-bound mystic","affiliation":"Kwaye-Zulu","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"Peace","nationality":"","spoilerLevel":"TBD","pronunciation":"sho-LAH-nee","currentResidence":"Wandering exile","elementalHeritage":""},"abilities":{"weapons":"Sacred Asalato","strengths":"Exceptional rhythm\nSpirit perception\nMental discipline\nPrecise coordination\nBattlefield control\nSpiritual resistance\nClose-range weapon skill","weaknesses":"Silence magic\nBroken rhythm\nSpiritual debt\nConsecrated ground\nSacred salt\nFlorida Water","combatStyle":["Rhythmic combat","Asalato striking","Spiritual disruption","Kinetic control","Short-range teleportation","Psychological warfare"],"limitations":["Magic depends on vibration","Missed rhythms cause backlash","Spirit invocation drains vitality","Mvula can sabotage movement","Cannot harm the truly innocent","13th Gate damages his senses"],"powerSource":["Crossroads spirit magic","Asalato rhythm","Mvula''s spiritual influence","Dead Eye"],"abilityNotes":"The swish of the Asalato sustains flow-based effects while the clack acts as a spiritual trigger. Xolani''s strongest techniques depend on uninterrupted timing. His Dead Eye allows direct perception of spirits and can expose others to the Grey Space through Eye-Lock.","combatProfile":"Xolani fights through rhythm rather than brute force. Continuous Asalato patterns control movement, summon spiritual interference, distort kinetic energy, and create openings for precise physical strikes. Mvula can either disrupt Xolani''s coordination or protect him from lethal attacks, making every battle a simultaneous struggle against the enemy and the spirit within him.","weaponDetails":"Xolani fights with paired Asalato, also known as Kashaka or shaker balls. Their swish sustains rhythmic magic while their clack releases or locks spiritual force. His combat set is reinforced for physical strikes and spiritually linked to Mvula.","transformations":"The 13th Gate state","primaryAbilities":"Rattling Call\nSoul-Clack\nPapa Legba''s Gate\nEye-Lock","secondaryAbilities":"Syncopated Stasis\nSpirit perception\nKinetic distortion\nSpectral summoning\nSpiritual binding","signatureTechniques":"Crossroads Cadence\nPolyrhythmic Paradox\nLateral Click — X-Snap\nThe Stillness\nThe 13th Gate","transformationDetails":"During The 13th Gate, Xolani breaks open his Asalato and spills their spirit dirt around himself, temporarily becoming a manifestation of the Crossroads. For roughly sixty seconds, his spiritual perception and temporal attacks become extreme. The technique leaves him temporarily blind and deaf afterward."},"is_public":false,"appearance":{"build":["Wiry","Sinewy","Lean"],"nails":["Natural dark nails"],"eyeHex":["#4A2D1C","#E5E1D8"],"height":"6''2\" (188 cm)","makeup":"","weight":"TBD","hairHex":["#0B0908"],"skinHex":["#593A2D","#3E2A23"],"eyeColor":["Right eye — deep brown","Left eye — milky white"],"grooming":"Weathered but deliberate","skinTone":["Mahogany-charcoal brown"],"wardrobe":"Tattered cloak\nLayered wraps\nLoose trousers\nLeather footwear\nWeathered work clothing","hairColor":["Black"],"hairStyle":"Long voluminous locs with beads","accessories":"Beaded necklaces\nRitual charms\nBone tokens\nMetal rings\nTobacco pouch\nSmall rum flask","faceDetails":["High sharp cheekbones","Straight nose","Strong elegant jawline"],"hairTexture":["Locs"],"colorPalette":"Charcoal black\nEarth brown\nAsh grey\nAntique bronze\nBone white","dominantHand":"TBD","outfitColors":"#0D0C0B\n#211B18\n#4A382B\n#8A6743\n#B9B0A2","alternateForm":"","clothingStyle":"Practical Stone Mountains attire with dark layered fabrics, weathered materials, beadwork, ritual accessories, and an understated mystical silhouette suited to a wandering spirit practitioner.","appearanceNotes":"Xolani should appear striking and regal despite his exhausted, haunted presence. His right eye remains naturally brown while the left Dead Eye is completely milky-white and pupil-less. Fine charcoal-grey veins radiate from the left socket and become more pronounced when Mvula is active.","outfitMaterials":["Worn cloth","Leather","Canvas","Wood","Bone","Metal"],"postureMovement":["Predatory grace","Controlled movements","Rhythmic hand movement"],"signatureOutfit":"Layered dark ritual clothing with a weathered cloak, practical wraps, loose trousers, leather footwear, beadwork, necklaces, and subtle spiritual symbols. His clothing is worn and functional rather than ceremonial.","distinguishingFeatures":["Milky-white Dead Eye","Charcoal-grey eye veins","Scarred hands","Calloused palms","Ash-stained fingertips","Cold left hand","Long beaded locs"]},"created_at":"2026-09-25T06:50:56.828975+00:00","updated_at":"2026-09-25T07:07:07.236705+00:00","is_complete":true,"origin_lore":{"fears":["Losing control to Mvula","Repeating his original mistake","Being pulled into the spirit realm","Mvula being forgotten","Breaking his rhythm in combat"],"goals":["Find spiritual peace","Atone for binding Mvula","Protect others from restless spirits","Keep Mvula from being forgotten"],"beliefs":["Every soul deserves remembrance","Spirits are not servants","Power creates responsibility","The dead deserve dignity","Peace requires accountability"],"culture":["Kwaye-Zulu","High Crossroads keepers","Rhythm-based spiritual tradition"],"lineage":"Kwaye-Zulu spiritual tradition","storyArc":"Xolani begins as a guilt-ridden exile enduring Mvula''s hatred as punishment for his past. Through remembrance, shared rituals, and stubborn compassion, their parasitic bond gradually develops into reluctant mutual recognition. His journey centers on accountability, remembrance, and discovering whether peace can exist without erasing what happened.","backstory":"During the Great Drought, Xolani became desperate to save his starving village. Against his master''s warnings, he climbed to the Altar of the Unburied and used a forbidden Binding Cadence to imprison the restless spirit Mvula within his Asalato. The ritual produced Black Rain and saved the village, but Mvula retaliated by spiritually overwriting Xolani''s left eye, creating the Dead Eye. Marked by the curse and ashamed of what he had done, Xolani left Kwaye-Zulu and became a wandering protector who works to repay his debt to the spirit world.","childhood":"Xolani grew up in Kwaye-Zulu, where rhythm was woven into birth, mourning, spiritual practice, and everyday life. He showed unusual sensitivity to spirits and became a talented apprentice in the village''s spiritual traditions.","lifestyle":["Wanders between settlements","Handles dangerous spirit problems","Practices rhythmic meditation","Carries ritual offerings","Keeps his Asalato nearby"],"storyRole":"Xolani serves as a bridge between the living and the forgotten dead. His abilities make him exceptionally dangerous against spiritual threats, while his relationship with Mvula forces him to confront the consequences of treating a suffering soul as a source of power.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Burdened by guilt","Spiritually exhausted","Highly self-controlled","Protective of forgotten souls","Resists Mvula''s influence"],"motivations":["Repay his spiritual debt","Protect the living","Remember forgotten souls","Preserve Mvula''s memory","Prevent similar mistakes"],"personality":["Stoic","Weary","Reserved","Compassionate","Remorseful","Protective","Disciplined","Observant","Stubborn"],"voiceSpeech":["Deep soulful baritone","Quiet delivery","Measured speech","Few words","Emotionally restrained"],"likesDislikes":["Likes rainfall","Likes natural beauty","Values quiet","Values remembrance","Dislikes spiritual exploitation","Dislikes arrogant magic"],"majorLifeEvents":"Born in Kwaye-Zulu\nTrained in spiritual rhythms\nGreat Drought strikes Kwaye-Zulu\nClimbs the Altar of the Unburied\nBinds Mvula against his will\nSummons the Black Rain\nReceives the Dead Eye curse\nLeaves Kwaye-Zulu in exile\nBecomes a wandering spirit protector\nDevelops The Stillness"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/portrait/1790320005150-xolani-character-portrait.png","relationships":{"allies":"Mvula — Bound spirit and reluctant guardian\nSekani — Ally and musical counterpart","rivals":"","enemies":"","mentors":"Kwaye-Zulu village elder — Former spiritual mentor","parents":"","partner":"TBD","children":"","siblings":"","worldConnections":"Stone Mountains\nKwaye-Zulu\nAltar of the Unburied\nHigh Crossroads\nGrey Space","relationshipNotes":"Xolani and Mvula began as jailer and captive after Xolani forcibly bound the spirit during the Great Drought. Mvula initially tormented and sabotaged him, but Xolani''s refusal to forget Mvula''s human life gradually changes their relationship. They remain spiritually fused, contentious, and emotionally complicated, with Mvula increasingly protecting the only living person who continues to remember him."},"spoiler_level":"private","race_record_id":"c68d60d1-883a-4683-8000-a9cd9d0d4d2a","realm_record_id":"c6c8934d-b274-44f7-a1a6-a6f8f959654b","workflow_status":"draft","family_record_id":"2ff89f94-94cb-4de0-a6a8-8b4e3925f455","faction_record_id":"cb4c27cc-2adb-4d75-92b0-a1cabfa13127"}','2026-09-25T07:08:45.164033+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('f1eba6f0-a62c-492d-b484-3767c8b42a5a','studio_characters','b2d998c0-1754-4a6a-af91-281d65ded816','Shuǐmǔ Lánhuá','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b2d998c0-1754-4a6a-af91-281d65ded816","name":"Shuǐmǔ Lánhuá","media":{"tbdFields":"Birth date\nBirthplace\nApparent age\nHeight\nWeight\nDominant hand\nNationality\nExact weaknesses\nExact power limitations\nFormal signature techniques\nPartner status\nFull story arc\nExact sovereignty structure of her children","canonLocks":"Name: Shuǐmǔ Lánhuá\nHuman title: Lady Lánhuá\nDivine title: Shuǐmǔ Tiān Hòu\nFemale\nAsian heritage\nPrimordial\nLiving embodiment of Water\nRules the Sunken Domain\nSunken Domain encompasses the world''s waters\nSunken Domain is not within Aethelgard\nMother of Rahim\nMother of Ife\nMother of Ruchika\nIgnis is father of Rahim and Ife\nTerrax is father of Ruchika\nIfe is the Steam Dragon\nRuchika is the Bone Dragon\nRahim is the Blood Dragon\nRahim is currently lost\nIfe lives with her father\nRuchika lives with his father\nIfe and Ruchika visit their mother\nTrue form is an Eastern-style aquatic leviathan","galleryUrl":"","mediaNotes":"Maintain exact visual continuity between her established portrait, human-form production sheet, dragon form, and dragon production sheet. Future artwork should preserve her face, black hair, ocean-blue eyes, imperial aquatic aesthetic, signature palette, and Eastern-style leviathan design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nDragon Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Use the established production sheet as the primary visual reference for Lánhuá. Her human design should remain elegant, ancient, and imperial with long black hair, ocean-blue eyes, ornate aquatic hairpieces, and layered blue ceremonial robes. Her dragon form must remain a colossal Eastern-style aquatic leviathan with an elongated serpentine body, iridescent blue-teal scales, luminous aquatic mane, and water-and-mist manifestations.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/reference/1790319612245-shu-m-l-nhu-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/alternate/1790319622886-shu-m-l-nhu-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Unknown","era":"Ancient","name":"Shuǐmǔ Lánhuá","race":"Primordial","alias":"Lady Lánhuá","gender":"Female","titles":"Shuǐmǔ Tiān Hòu\nHeavenly Empress, Mother of All Waters\nThe Splendid Orchid\nMother of All Waters","subrace":"Living Embodiment of Water","summary":"Shuǐmǔ Lánhuá is the ancient Primordial and living embodiment of Water itself. She does not merely command water; oceans, seas, ice, rain, mist, currents, and other natural forms of water are expressions of her primordial existence. Known among mortals as Lady Lánhuá, she rules the Sunken Domain, which encompasses the world''s waters rather than existing within Aethelgard. She is the mother of Rahim, Ife, and Ruchika.","heritage":"Asian","homeland":"Sunken Domain","pronouns":"She/Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign of Water","affiliation":"Sunken Domain","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"The Splendid Orchid, Mother of Waters","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Sunken Domain","elementalHeritage":"Primordial Water"},"abilities":{"weapons":"","strengths":"Elemental fluidity\nExtreme water pressure\nEnvironmental control\nAquatic dominion\nAncient primordial power","weaknesses":"TBD","combatStyle":["Fluid","Defensive","Environmental","Pressure-based","Large-scale elemental control"],"limitations":["TBD"],"powerSource":["Primordial Water","Living embodiment of Water"],"abilityNotes":"Her authority over water comes from being its primordial embodiment, not from conventional learned water magic. Exact limits and interactions with other Primordials remain TBD.\n\nDo not classify Lánhuá as a Dragon Primal who merely rules water. She is a Primordial and the living embodiment of Water itself.","combatProfile":"Lánhuá fights as an elemental force rather than a conventional warrior. She changes water between liquid, ice, mist, and highly compressed states while manipulating currents, pressure, and surrounding moisture. Her movements remain controlled and graceful until extreme anger causes her power to become devastatingly violent.","weaponDetails":"","transformations":"Human Form\nAbyssal Leviathan Form","primaryAbilities":"Absolute water manipulation\nPhase manipulation\nHydrostatic pressure manipulation\nIce manipulation\nMist manipulation\nRain manipulation\nCurrent manipulation\nAbyssal command","secondaryAbilities":"Water compression\nTemperature manipulation\nAquatic telepathy\nSea-life command\nAtmospheric moisture manipulation","signatureTechniques":"TBD","transformationDetails":"Lánhuá can manifest as a colossal Eastern-style aquatic dragon or sea serpent. Her elongated body carries iridescent midnight-blue, teal, and seafoam scales with a flowing bioluminescent mane. Rather than conventional leathery wings, her established dragon design can manifest immense wings formed from compressed water, mist, and atmospheric moisture."},"is_public":false,"appearance":{"build":["Slender","Graceful","Regal"],"nails":["TBD"],"eyeHex":["TBD"],"height":"TBD","makeup":["Subtle","Elegant"],"weight":"TBD","hairHex":["#090D18"],"skinHex":["TBD"],"eyeColor":["Ocean blue"],"grooming":"Immaculate and imperial.","skinTone":["Fair"],"wardrobe":"Layered ceremonial robes\nImperial water-themed gowns\nFlowing silk garments","hairColor":["Black"],"hairStyle":"Very long black hair styled with ornate water-themed hairpieces.","accessories":"Ice orchid hair ornaments\nOrnate hairpins\nWater-drop earrings\nDragon-scale necklace\nWater orb pendant\nJade ornaments","faceDetails":["Elegant features","Regal expression","Refined facial structure"],"hairTexture":["Straight","Silky"],"colorPalette":"Midnight blue #071A33\nDeep teal #07566B\nSeafoam #67C8C2\nTurquoise #46CFE0\nSilver #C8D5DF\nPearl white #EEF3F4","dominantHand":"TBD","outfitColors":"Midnight blue\nDeep teal\nTurquoise\nSilver\nPearl white","alternateForm":["Abyssal Leviathan","Eastern-style sea dragon"],"clothingStyle":"Regal 500–1300 AD-inspired Asian fantasy clothing with flowing silhouettes, layered silks, wave motifs, and refined ornamentation.","appearanceNotes":"Her human design should feel ancient, serene, elegant, and unmistakably connected to the ocean. Her clothing and hair should appear to move with subtle underwater fluidity even on land. Maintain the established midnight-blue, teal, turquoise, silver, and pearl palette across all artwork.","outfitMaterials":["Silk","Translucent silk","Fine embroidery"],"postureMovement":["Poised","Fluid","Controlled"],"signatureOutfit":"Flowing multi-layered imperial robes inspired by 500–1300 AD Asian dress, combining midnight blue, deep teal, silver, and translucent water-like layers. Fine wave and orchid motifs decorate the fabric.","distinguishingFeatures":["Ocean-blue eyes","Very long black hair","Water-themed hair ornaments","Regal presence"]},"created_at":"2026-09-25T06:48:09.359491+00:00","updated_at":"2026-09-25T07:01:11.895221+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Protect the Sunken Domain","Preserve aquatic life","Safeguard her family"],"beliefs":["Water sustains life","Water must remain balanced"],"culture":["Ancient aquatic court","Asian-inspired imperial aesthetic"],"lineage":"Primordial embodiment of Water.","storyArc":"Her larger story arc remains TBD. Rahim''s disappearance creates an unresolved thread within her family, while Ife and Ruchika maintain connections to her domain despite residing with their fathers.","backstory":"Lánhuá is one of the ancient Primordials and the living embodiment of Water. Her sovereignty is not limited to a single ocean or continent; the Sunken Domain encompasses the waters of the world. Her unions with Ignis produced Rahim and Ife, while her union with Terrax produced Ruchika. Although Ife and Ruchika reside with their fathers, they remain connected to their mother''s domain and visit her. Rahim is currently lost, and his absence remains unresolved.","childhood":"TBD","lifestyle":["Rules the Sunken Domain","Oversees the waters of the world","Receives visits from her children"],"storyRole":"Lánhuá serves as the primordial embodiment of Water and sovereign of the Sunken Domain. Her existence connects the oceans, aquatic civilizations, and several elemental bloodlines through her children Rahim, Ife, and Ruchika.","birthplace":"TBD","psychology":["Emotionally restrained","Deeply maternal","Patient observer","Terrifying when enraged"],"motivations":["Protect her children","Preserve the waters","Maintain natural balance"],"personality":["Patient","Calm","Soft-spoken","Graceful","Observant","Maternal","Protective","Formidable"],"voiceSpeech":["Soft-spoken","Measured","Regal","Controlled"],"likesDislikes":["TBD"],"majorLifeEvents":"Union with Ignis\nBirth of Rahim\nBirth of Ife\nUnion with Terrax\nBirth of Ruchika\nRahim disappeared\nIfe resides with Ignis\nRuchika resides with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","relationships":{"allies":"TBD","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Rahim — Son; Blood Dragon; child with Ignis; currently lost\nIfe — Daughter; Steam Dragon; child with Ignis; resides with her father and visits Lánhuá\nRuchika — Son; Bone Dragon; child with Terrax; resides with his father and visits Lánhuá","siblings":"","worldConnections":"Ignis — Father of Rahim and Ife\nTerrax — Father of Ruchika\nSunken Domain — Her primordial realm\nWorld waters — Her elemental existence","relationshipNotes":"Lánhuá is the mother of Rahim, Ife, and Ruchika. Rahim and Ife are her children with Ignis, while Ruchika is her child with Terrax. Ife and Ruchika live with their fathers but retain a connection and form of sovereignty within their mother''s waters and continue to visit her. Rahim remains lost; his established disappearance and story should not be overwritten."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"065f06b5-4812-4543-9430-02830d72ae0b","workflow_status":"draft","family_record_id":"3e083a30-190f-4d2e-a61c-605c24c21769","faction_record_id":"9eabcca3-b901-4fdb-92da-03d6ab2a98c5"}','2026-09-25T07:08:51.270325+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('e2f16073-b582-4944-abc7-93b47b631707','studio_characters','302f42c7-2c06-47de-a5ef-6d2940d026bf','Terrax','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"302f42c7-2c06-47de-a5ef-6d2940d026bf","name":"Terrax","media":{"tbdFields":"Birth date\nExact age\nExact height\nExact weight\nDominant hand\nBirthplace\nName meaning\nNationality\nFormal partner status\nNamed allies\nNamed rivals\nNamed enemies\nNamed mentors\nSpecific weaknesses\nSpecific power limitations\nStory arc","canonLocks":"Terrax is male\nTerrax is Indian\nTerrax is the Primordial embodiment of Earth\nTerrax is not merely a Dragon Primal\nHis primordial truth is the Telluric Verity\nHis humanoid form is called Terrance\nRuchicka is his oldest child\nGaius is his Sand Dragon child\nShailara is his youngest child\nShailara is half Sylvani elf\nTerrax directly rules the land called Terrax\nStone Mountains is Terrax''s sanctuary\nTerrax is a stoner\nThe Heavy Grumble are devoted human followers\nIronspire Hold is independently governed\nEldoria is within Aethelgarud\nEldoria is the Sylvani homeland","galleryUrl":"","mediaNotes":"Existing artwork establishes both Terrance''s human appearance and Terrax''s colossal Earth Dragon form. The completed visual production sheet should be treated as the main design reference for future artwork.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Done\nFace Reference — Done\nEye Reference — Needed\nHair Reference — Needed\nOutfit Breakdown — Done\nExpression Sheet — Done\nCombat Reference — Needed","productionNotes":"Use the established production sheet as Terrax''s primary visual canon. Future human artwork should preserve his Indian features, warm brown skin, long black hair, powerful build, earth markings, dark green and earth-toned clothing, antique-gold detailing, jewelry, and ancient fantasy aesthetic. His dragon form must remain colossal, rocky, mountain-like, winged, and visibly connected to the Telluric Verity.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/reference/1790318701593-terrax-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/alternate/1790318762884-terrax-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Ancient","era":"Primordial","name":"Terrax","race":"Primordial","alias":"Terrance","gender":"Male","titles":"The Earth Primordial\nThe Earth Dragon\nThe First Stone\nThe Mountain Father\nThe One Who Remembers","subrace":"Earth Primordial","summary":"Terrax is the primordial embodiment of Earth and the living foundation of the physical world. His primordial truth, the Telluric Verity, embodies permanence, resilience, gravity, weight, and the memory held within the earth. He rules his own land called Terrax and considers the Stone Mountains a personal sanctuary where he can relax away from his responsibilities.","heritage":"Indian","homeland":"Terrax","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Primordial embodiment of Earth","affiliation":"Terrax","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TERR-aks","currentResidence":"Terrax","elementalHeritage":"Primordial Earth"},"abilities":{"weapons":"","strengths":"Immense physical strength\nExtreme durability\nPrimordial resilience\nGravity control\nEarth control\nMassive scale","weaknesses":"TBD","combatStyle":["Heavy","Grounded","Overwhelming force","Defensive","Terrain control"],"limitations":["TBD"],"powerSource":["Telluric Verity","Primordial Earth"],"abilityNotes":"The Telluric Verity is not ordinary earth magic. It is Terrax''s primordial truth governing permanence, resilience, gravity, physical weight, and the memory of the earth. Terrax is the living embodiment of Earth rather than a Dragon Primal who merely controls it.\n\nTerrax should not be treated as the political ruler of every civilization located on land. Ironspire Hold and Eldoria are independent of his rule. His direct territory is Terrax, while the Stone Mountains function primarily as his sanctuary.","combatProfile":"Terrax fights with the overwhelming weight and stability of the earth itself. His combat style favors immense force, resilience, gravity, terrain manipulation, and attacks capable of reshaping the battlefield. His movements may appear slow or deliberate compared with faster Primordials, but each action carries enormous physical weight.","weaponDetails":"No established signature weapon.","transformations":"Earth Dragon Form\nHuman Form","primaryAbilities":"Earth manipulation\nStone manipulation\nGravity manipulation\nTectonic manipulation\nTelluric Verity","secondaryAbilities":"Extreme resilience\nEarth sensing\nGeological awareness\nMountain-scale transformation","signatureTechniques":"Telluric Verity","transformationDetails":"Terrax can manifest as Terrance, his humanoid form, or reveal his true Earth Dragon form. His dragon form is mountain-sized, with colossal rocky scales resembling cliffs and mountain formations. His body should appear ancient enough that vegetation, moss, stone, and geological features can naturally form across portions of his scales."},"is_public":false,"appearance":{"build":["Tall","Muscular","Broad-shouldered"],"nails":["Natural"],"eyeHex":["#8A6036"],"height":"TBD","makeup":"","weight":"TBD","hairHex":["#11100F"],"skinHex":["#70472F"],"eyeColor":["Earthy amber-brown"],"grooming":"Well-kept with a rugged natural appearance","skinTone":["Deep warm brown"],"wardrobe":"Layered robes\nLoose trousers\nDraped mantle\nLeather sandals\nOrnamental belts","hairColor":["Black"],"hairStyle":"Long layered hair worn loose and partially pulled back","accessories":"Ornate earrings\nLayered necklaces\nStone rings\nMetal bracers\nDecorative belt\nGemstone ornaments","faceDetails":["Strong angular jaw","Defined cheekbones","Heavy brows","Straight nose"],"hairTexture":["Thick","Wavy"],"colorPalette":"Earth brown #70472F\nObsidian #171512\nForest green #263B2A\nAntique gold #A77A36\nStone gray #716B60","dominantHand":"TBD","outfitColors":"Forest green\nBlack\nEarth brown\nAntique gold\nStone gray","alternateForm":["Mountain-sized Earth Dragon"],"clothingStyle":"Ancient Indian-inspired fantasy clothing suited to the Umbra World''s 500–1300 AD-inspired aesthetic. His clothing should feel ancient, earthy, regal, practical, and connected to stone rather than resembling modern fashion.","appearanceNotes":"Terrance is Terrax''s humanoid form and should retain the same Indian appearance, long black hair, warm brown skin, earthy palette, gold accents, and ancient grounded presence established in his visual references. His design should communicate immense strength without making him look excessively armored.","outfitMaterials":["Woven cloth","Leather","Metal","Stone","Gemstone"],"postureMovement":["Grounded stance","Heavy deliberate movement","Relaxed posture"],"signatureOutfit":"Layered Indian-inspired fantasy robes with dark green draping, black and earth-brown fabrics, antique-gold embroidery, loose trousers, leather sandals, belts, jewelry, and stone-set ornaments.","distinguishingFeatures":["Golden earth markings","Forehead sigil","Long black hair","Ornate earrings","Earth-toned jewelry"]},"created_at":"2026-09-25T06:43:53.695036+00:00","updated_at":"2026-09-25T06:46:45.392218+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Maintain the Telluric Verity","Protect Terrax","Preserve the physical world"],"beliefs":["Everything has weight","The earth remembers","Permanence has value","Resilience comes through endurance"],"culture":["Primordial","Indian-inspired"],"lineage":"Primordial embodiment of Earth","storyArc":"TBD","backstory":"Terrax is an ancient Primordial who embodies Earth itself rather than merely ruling the earth element. His existence is tied to the Telluric Verity, the cosmic truth of permanence, resilience, gravity, weight, and physical memory. He personally rules the land called Terrax while allowing unrelated human and nonhuman civilizations elsewhere to govern themselves.","childhood":"TBD","lifestyle":["Retreats to the Stone Mountains","Spends time with his children","Smokes to relax","Enjoys quiet natural spaces"],"storyRole":"Terrax serves as the Primordial embodiment of Earth and father of Ruchicka, Gaius, and Shailara. His existence establishes the metaphysical foundation of earth, stone, gravity, permanence, and physical memory within the Umbra World.","birthplace":"TBD","psychology":["Extremely patient","Values permanence","Difficult to provoke","Comfortable with silence"],"motivations":["Preserve the earth","Protect his children","Maintain natural stability"],"personality":["Calm","Grounded","Patient","Relaxed","Stoic","Independent"],"voiceSpeech":["Deep voice","Measured speech","Few unnecessary words","Heavy relaxed tone"],"likesDislikes":["Likes smoking","Likes mountains","Likes peace and quiet","Likes relaxing","Dislikes unnecessary disturbance"],"majorLifeEvents":"Became the living embodiment of Earth\nFathered Ruchicka with Shuǐmǔ Lánhuá\nFathered Gaius with Aetheros\nFathered Shailara with a Sylvani elf"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png","relationships":{"allies":"","rivals":"Ignis","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Ruchicka — Oldest child and Bone Dragon\nGaius — Sand Dragon\nShailara — Youngest child and half-Sylvani Stone Dragon","siblings":"","worldConnections":"Shuǐmǔ Lánhuá — Mother of Ruchicka\nAetheros — Mother of Gaius\nEldoria — Homeland of Shailara''s Sylvani family\nStone Mountains — Personal sanctuary\nHeavy Grumble — Devoted human followers\nIronspire Hold — Independent Duroc homeland","relationshipNotes":"Ruchicka is Terrax''s oldest child with Shuǐmǔ Lánhuá and lives primarily with Terrax while maintaining ties to his mother''s water domain. Gaius is Terrax''s child with Aetheros and lives with his father while maintaining ties to his mother''s air domain. Shailara is Terrax''s youngest child, born to a Sylvani elf; she lives with Terrax while remaining connected to her mother''s people in Eldoria."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"53d924ac-f33c-491b-a246-240d886c2de5","workflow_status":"draft","family_record_id":"cc24abab-518b-4ef0-8cbe-dbea119ee873","faction_record_id":"0ba48458-c018-47e8-bfc0-bcfcd31aa531"}','2026-09-25T07:08:52.464526+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('79b882ca-0183-4238-a1c0-90eb0d893ed4','studio_characters','b2d998c0-1754-4a6a-af91-281d65ded816','Shuǐmǔ Lánhuá','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b2d998c0-1754-4a6a-af91-281d65ded816","name":"Shuǐmǔ Lánhuá","media":{"tbdFields":"Birth date\nBirthplace\nApparent age\nHeight\nWeight\nDominant hand\nNationality\nExact weaknesses\nExact power limitations\nFormal signature techniques\nPartner status\nFull story arc\nExact sovereignty structure of her children","canonLocks":"Name: Shuǐmǔ Lánhuá\nHuman title: Lady Lánhuá\nDivine title: Shuǐmǔ Tiān Hòu\nFemale\nAsian heritage\nPrimordial\nLiving embodiment of Water\nRules the Sunken Domain\nSunken Domain encompasses the world''s waters\nSunken Domain is not within Aethelgard\nMother of Rahim\nMother of Ife\nMother of Ruchika\nIgnis is father of Rahim and Ife\nTerrax is father of Ruchika\nIfe is the Steam Dragon\nRuchika is the Bone Dragon\nRahim is the Blood Dragon\nRahim is currently lost\nIfe lives with her father\nRuchika lives with his father\nIfe and Ruchika visit their mother\nTrue form is an Eastern-style aquatic leviathan","galleryUrl":"","mediaNotes":"Maintain exact visual continuity between her established portrait, human-form production sheet, dragon form, and dragon production sheet. Future artwork should preserve her face, black hair, ocean-blue eyes, imperial aquatic aesthetic, signature palette, and Eastern-style leviathan design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nDragon Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Use the established production sheet as the primary visual reference for Lánhuá. Her human design should remain elegant, ancient, and imperial with long black hair, ocean-blue eyes, ornate aquatic hairpieces, and layered blue ceremonial robes. Her dragon form must remain a colossal Eastern-style aquatic leviathan with an elongated serpentine body, iridescent blue-teal scales, luminous aquatic mane, and water-and-mist manifestations.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/reference/1790319612245-shu-m-l-nhu-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/alternate/1790319622886-shu-m-l-nhu-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Unknown","era":"Ancient","name":"Shuǐmǔ Lánhuá","race":"Primordial","alias":"Lady Lánhuá","gender":"Female","titles":"Shuǐmǔ Tiān Hòu\nHeavenly Empress, Mother of All Waters\nThe Splendid Orchid\nMother of All Waters","subrace":"Living Embodiment of Water","summary":"Shuǐmǔ Lánhuá is the ancient Primordial and living embodiment of Water itself. She does not merely command water; oceans, seas, ice, rain, mist, currents, and other natural forms of water are expressions of her primordial existence. Known among mortals as Lady Lánhuá, she rules the Sunken Domain, which encompasses the world''s waters rather than existing within Aethelgard. She is the mother of Rahim, Ife, and Ruchika.","heritage":"Asian","homeland":"Sunken Domain","pronouns":"She/Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign of Water","affiliation":"Sunken Domain","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"The Splendid Orchid, Mother of Waters","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Sunken Domain","elementalHeritage":"Primordial Water"},"abilities":{"weapons":"","strengths":"Elemental fluidity\nExtreme water pressure\nEnvironmental control\nAquatic dominion\nAncient primordial power","weaknesses":"TBD","combatStyle":["Fluid","Defensive","Environmental","Pressure-based","Large-scale elemental control"],"limitations":["TBD"],"powerSource":["Primordial Water","Living embodiment of Water"],"abilityNotes":"Her authority over water comes from being its primordial embodiment, not from conventional learned water magic. Exact limits and interactions with other Primordials remain TBD.\n\nDo not classify Lánhuá as a Dragon Primal who merely rules water. She is a Primordial and the living embodiment of Water itself.","combatProfile":"Lánhuá fights as an elemental force rather than a conventional warrior. She changes water between liquid, ice, mist, and highly compressed states while manipulating currents, pressure, and surrounding moisture. Her movements remain controlled and graceful until extreme anger causes her power to become devastatingly violent.","weaponDetails":"","transformations":"Human Form\nAbyssal Leviathan Form","primaryAbilities":"Absolute water manipulation\nPhase manipulation\nHydrostatic pressure manipulation\nIce manipulation\nMist manipulation\nRain manipulation\nCurrent manipulation\nAbyssal command","secondaryAbilities":"Water compression\nTemperature manipulation\nAquatic telepathy\nSea-life command\nAtmospheric moisture manipulation","signatureTechniques":"TBD","transformationDetails":"Lánhuá can manifest as a colossal Eastern-style aquatic dragon or sea serpent. Her elongated body carries iridescent midnight-blue, teal, and seafoam scales with a flowing bioluminescent mane. Rather than conventional leathery wings, her established dragon design can manifest immense wings formed from compressed water, mist, and atmospheric moisture."},"is_public":true,"appearance":{"build":["Slender","Graceful","Regal"],"nails":["TBD"],"eyeHex":["TBD"],"height":"TBD","makeup":["Subtle","Elegant"],"weight":"TBD","hairHex":["#090D18"],"skinHex":["TBD"],"eyeColor":["Ocean blue"],"grooming":"Immaculate and imperial.","skinTone":["Fair"],"wardrobe":"Layered ceremonial robes\nImperial water-themed gowns\nFlowing silk garments","hairColor":["Black"],"hairStyle":"Very long black hair styled with ornate water-themed hairpieces.","accessories":"Ice orchid hair ornaments\nOrnate hairpins\nWater-drop earrings\nDragon-scale necklace\nWater orb pendant\nJade ornaments","faceDetails":["Elegant features","Regal expression","Refined facial structure"],"hairTexture":["Straight","Silky"],"colorPalette":"Midnight blue #071A33\nDeep teal #07566B\nSeafoam #67C8C2\nTurquoise #46CFE0\nSilver #C8D5DF\nPearl white #EEF3F4","dominantHand":"TBD","outfitColors":"Midnight blue\nDeep teal\nTurquoise\nSilver\nPearl white","alternateForm":["Abyssal Leviathan","Eastern-style sea dragon"],"clothingStyle":"Regal 500–1300 AD-inspired Asian fantasy clothing with flowing silhouettes, layered silks, wave motifs, and refined ornamentation.","appearanceNotes":"Her human design should feel ancient, serene, elegant, and unmistakably connected to the ocean. Her clothing and hair should appear to move with subtle underwater fluidity even on land. Maintain the established midnight-blue, teal, turquoise, silver, and pearl palette across all artwork.","outfitMaterials":["Silk","Translucent silk","Fine embroidery"],"postureMovement":["Poised","Fluid","Controlled"],"signatureOutfit":"Flowing multi-layered imperial robes inspired by 500–1300 AD Asian dress, combining midnight blue, deep teal, silver, and translucent water-like layers. Fine wave and orchid motifs decorate the fabric.","distinguishingFeatures":["Ocean-blue eyes","Very long black hair","Water-themed hair ornaments","Regal presence"]},"created_at":"2026-09-25T06:48:09.359491+00:00","updated_at":"2026-09-25T07:08:51.270325+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Protect the Sunken Domain","Preserve aquatic life","Safeguard her family"],"beliefs":["Water sustains life","Water must remain balanced"],"culture":["Ancient aquatic court","Asian-inspired imperial aesthetic"],"lineage":"Primordial embodiment of Water.","storyArc":"Her larger story arc remains TBD. Rahim''s disappearance creates an unresolved thread within her family, while Ife and Ruchika maintain connections to her domain despite residing with their fathers.","backstory":"Lánhuá is one of the ancient Primordials and the living embodiment of Water. Her sovereignty is not limited to a single ocean or continent; the Sunken Domain encompasses the waters of the world. Her unions with Ignis produced Rahim and Ife, while her union with Terrax produced Ruchika. Although Ife and Ruchika reside with their fathers, they remain connected to their mother''s domain and visit her. Rahim is currently lost, and his absence remains unresolved.","childhood":"TBD","lifestyle":["Rules the Sunken Domain","Oversees the waters of the world","Receives visits from her children"],"storyRole":"Lánhuá serves as the primordial embodiment of Water and sovereign of the Sunken Domain. Her existence connects the oceans, aquatic civilizations, and several elemental bloodlines through her children Rahim, Ife, and Ruchika.","birthplace":"TBD","psychology":["Emotionally restrained","Deeply maternal","Patient observer","Terrifying when enraged"],"motivations":["Protect her children","Preserve the waters","Maintain natural balance"],"personality":["Patient","Calm","Soft-spoken","Graceful","Observant","Maternal","Protective","Formidable"],"voiceSpeech":["Soft-spoken","Measured","Regal","Controlled"],"likesDislikes":["TBD"],"majorLifeEvents":"Union with Ignis\nBirth of Rahim\nBirth of Ife\nUnion with Terrax\nBirth of Ruchika\nRahim disappeared\nIfe resides with Ignis\nRuchika resides with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","relationships":{"allies":"TBD","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Rahim — Son; Blood Dragon; child with Ignis; currently lost\nIfe — Daughter; Steam Dragon; child with Ignis; resides with her father and visits Lánhuá\nRuchika — Son; Bone Dragon; child with Terrax; resides with his father and visits Lánhuá","siblings":"","worldConnections":"Ignis — Father of Rahim and Ife\nTerrax — Father of Ruchika\nSunken Domain — Her primordial realm\nWorld waters — Her elemental existence","relationshipNotes":"Lánhuá is the mother of Rahim, Ife, and Ruchika. Rahim and Ife are her children with Ignis, while Ruchika is her child with Terrax. Ife and Ruchika live with their fathers but retain a connection and form of sovereignty within their mother''s waters and continue to visit her. Rahim remains lost; his established disappearance and story should not be overwritten."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"065f06b5-4812-4543-9430-02830d72ae0b","workflow_status":"draft","family_record_id":"3e083a30-190f-4d2e-a61c-605c24c21769","faction_record_id":"9eabcca3-b901-4fdb-92da-03d6ab2a98c5"}','2026-09-25T07:09:49.555672+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('53de3f11-e8f5-4f42-9116-ec29b427786d','studio_characters','c48e35c9-e98d-414c-afb7-ae85f99eb649','Atherous','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"c48e35c9-e98d-414c-afb7-ae85f99eb649","name":"Atherous","media":{"tbdFields":"Pronunciation\nName meaning\nBirth date\nExact age\nApparent age\nExact height\nExact weight\nDominant hand\nNationality\nBirthplace\nChildhood\nStory arc\nSpecific fears\nAbility weaknesses\nAbility limitations","canonLocks":"Atherous is female\nAtherous is Caucasian\nAtherous is a Primordial\nAtherous is the living embodiment of Air\nAtherous is not merely an Air Dragon ruler\nAtherous has silver hair\nAtherous is mother of Ezra\nIgnis is Ezra''s father\nAtherous is mother of Gaius\nTerrax is Gaius''s father\nEzra is the Lightning Dragon\nGaius is the Sand Dragon\nEzra lives primarily with Atherous\nGaius lives primarily with Terrax\nVeritas Volans is Atherous''s primordial truth\nThe Veiled Whisper governs vibration and frequency\nVoid Sky — The Eternal Horizon is an Atherous power\nEchoing Truth is Atherous''s Sonic Blade","galleryUrl":"","mediaNotes":"Existing visual references establish Atherous''s human form, Primordial Air Dragon form, production sheet, and Echoing Truth Sonic Blade. These designs should be treated as the visual continuity reference for future artwork.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nExpression Sheet — Done\nCombat Reference — Done","productionNotes":"Maintain Atherous''s established anime/fantasy appearance across every future asset. Her human form uses long silver-white hair, fair porcelain skin, silver-blue eyes, an elegant slender build, flowing white-and-silver clothing, and frost-blue atmospheric effects. Her dragon form remains silver-white and luminous. Echoing Truth must retain its established silver-white sonic and atmospheric design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/reference/1790319737660-aetheros-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/alternate/1790319744447-aetheros-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Primordial","era":"Primordial Era","name":"Atherous","race":"Primordial","alias":"The Veiled Whisper","gender":"Female","titles":"The Veiled Whisper\nThe Eternal Horizon\nLiving Embodiment of Air","subrace":"God-Prime","summary":"Atherous is the primordial living embodiment of air. She does not simply rule wind or possess air magic; air itself is her elemental existence. Her authority encompasses wind, atmosphere, sound, vibration, frequency, vacuum, storms, flight, motion, and the unseen pathways connecting the world. Her primordial truth is Veritas Volans, the Law of Eternal Change.","heritage":"Caucasian","homeland":"Veylora","pronouns":"She / Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign","affiliation":"Veylora","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Veylora","elementalHeritage":"Primordial Air"},"abilities":{"weapons":"Echoing Truth — Sonic Blade","strengths":"Extreme speed\nAtmospheric control\nLong-range attacks\nSound manipulation\nFrequency control\nAerial mobility\nVacuum creation","weaknesses":"TBD","combatStyle":["Extreme-speed combat","Sonic swordsmanship","Aerial combat","Precision strikes","Battlefield control"],"limitations":["TBD"],"powerSource":["Primordial Air","Veritas Volans","Veiled Whisper"],"abilityNotes":"The Veiled Whisper governs vibration and frequency rather than simple wind manipulation. Atherous can weaponize sound, create vacuums, alter atmospheric pressure, transmit whispers through air, and form sonic cutting forces. Her magic may sound like sharp whistles, cracking whips, or countless distant voices.\n\nAtherous must not be described as merely an Air Dragon who rules air. Her dragon form is a manifestation of her primordial nature; she is the living embodiment of Air itself.","combatProfile":"Atherous specializes in overwhelming speed, aerial mobility, atmospheric control, and precision attacks. Void Sky — The Eternal Horizon allows her movement to resemble teleportation as she slides through the horizon, while residual currents can remain behind as damaging after-images. Horizon Slice allows her to pass an opponent before the displaced air produces the actual cut.","weaponDetails":"Echoing Truth is Atherous''s signature Sonic Blade. It channels her authority over sound, vibration, frequency, and air into a sword capable of producing devastating frequency-based cuts. Its design uses silver-white and frost-blue atmospheric energy consistent with Atherous''s established visual identity.","transformations":"Primordial Air Dragon Form","primaryAbilities":"Atmospheric Command\nWind Manipulation\nStorm Manipulation\nSound Manipulation\nFrequency Manipulation\nVibration Manipulation\nVacuum Creation\nAtmospheric Pressure Control","secondaryAbilities":"Flight\nSonic Blades\nSound-Sight\nLong-Distance Whispering\nAir Removal\nExtreme-Speed Movement","signatureTechniques":"Void Sky — The Eternal Horizon\nThe Severing Current\nHorizon Slice\nThe Echoing Truth\nVacuum — The Absence of Breath","transformationDetails":"Atherous can manifest as a colossal silver-white air dragon with immense wings, an elongated draconic silhouette, luminous pale eyes, and atmospheric energy flowing around her body. The form should retain the same silver, white, and frost-blue palette as her human appearance."},"is_public":true,"appearance":{"build":["Tall","Elegant","Slender"],"nails":["Pale silver"],"eyeHex":["#BFD8EA"],"height":"TBD","makeup":["Subtle cool-toned makeup"],"weight":"TBD","hairHex":["#E8EAF0","#F4F5F7"],"skinHex":["#F2E8E5"],"eyeColor":["Silver-blue"],"grooming":"Immaculate and ethereal","skinTone":["Fair porcelain"],"wardrobe":"Flowing ceremonial gowns\nAir-themed divine garments","hairColor":["Silver-white"],"hairStyle":"Extremely long flowing silver-white hair","accessories":"Silver headpiece\nCrystal ornaments\nSilver jewelry","faceDetails":["Elegant facial structure","High cheekbones","Delicate features"],"hairTexture":["Silky","Flowing"],"colorPalette":"Cloud white #F4F5F7\nSilver #C7CCD6\nFrost blue #BFD8EA\nSky blue #AFCDE3\nMoonlight pearl #E7E5ED","dominantHand":"TBD","outfitColors":"White\nSilver\nFrost blue","alternateForm":["Primordial Air Dragon"],"clothingStyle":"Ethereal fantasy regalia built around flowing layers, silver ornamentation, and lightweight materials that constantly react to surrounding air currents.","appearanceNotes":"Atherous should always appear exceptionally beautiful, ethereal, and nearly weightless. Her hair and clothing should appear affected by invisible currents even while she stands still. Her established visual identity is white, silver, frost blue, and luminous atmospheric effects.","outfitMaterials":["Flowing fabric","Translucent fabric","Silver ornamentation","Crystal accents"],"postureMovement":["Graceful","Weightless","Fluid"],"signatureOutfit":"A flowing white-and-silver fantasy gown with crystalline detailing, layered translucent fabrics, and long wind-swept elements. The silhouette remains elegant and otherworldly while fitting the fantasy identity of the Umbra World.","distinguishingFeatures":["Silver-white hair","Silver-blue eyes","Ethereal beauty","Wind-swept silhouette","White atmospheric aura"]},"created_at":"2026-09-25T06:47:38.069587+00:00","updated_at":"2026-09-25T07:08:38.778584+00:00","is_complete":true,"origin_lore":{"fears":["TBD"],"goals":["Uphold Veritas Volans"],"beliefs":["Nothing should be bound","Change is necessary","Air carries truth"],"culture":["Veyloran"],"lineage":"Primordial embodiment of Air","storyArc":"TBD","backstory":"Atherous is one of the primordial elemental beings of the Umbra World and embodies air itself rather than merely governing it. Her existence encompasses the atmosphere and its movement, allowing her presence to extend wherever air exists. Her primordial truth, Veritas Volans, represents freedom, motion, transition, and eternal change.","childhood":"TBD","lifestyle":["Exists throughout her atmospheric domain","Moves freely through Veylora"],"storyRole":"Atherous serves as the primordial embodiment of Air and sovereign presence of Veylora. Through her, the Umbra World''s wind, atmosphere, sound, vibration, vacuum, and atmospheric motion are connected to a single primordial source.","birthplace":"TBD","psychology":["Values freedom","Rejects stagnation","Embraces change"],"motivations":["Preserve freedom","Maintain atmospheric balance"],"personality":["Elusive","Free-spirited","Graceful","Calm","Independent"],"voiceSpeech":["Soft-spoken","Ethereal","Controlled"],"likesDislikes":["Values freedom","Values movement","Dislikes confinement"],"majorLifeEvents":"Became mother of Ezra with Ignis\nBecame mother of Gaius with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/c48e35c9-e98d-414c-afb7-ae85f99eb649/portrait/1790319732526-aetheros-character-portrait.png","relationships":{"allies":"Ignis — Father of Ezra\nTerrax — Father of Gaius","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Ezra — Son with Ignis; Lightning Dragon\nGaius — Son with Terrax; Sand Dragon","siblings":"","worldConnections":"Veylora — Primordial domain\nIgnis — Ezra''s father\nTerrax — Gaius''s father\nEzra — Lightning Dragon son\nGaius — Sand Dragon son","relationshipNotes":"Ezra is the son of Atherous and Ignis and lives primarily with Atherous while retaining a sovereign connection to his father''s domain. Gaius is the son of Atherous and Terrax and lives primarily with Terrax while retaining a sovereign connection to his mother''s domain."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"fd4462c1-d940-4eb8-8105-5ff2b323bc99","workflow_status":"draft","family_record_id":"b32427ed-0baf-457b-8c84-b0266dd31c76","faction_record_id":"efcdcdc6-0a8e-4713-8e49-fce93c606887"}','2026-09-25T07:10:27.830474+00:00');
