INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('d3678ac4-3846-4d1b-a18f-7b1a7745fa1e','studio_world_records','3d095ec9-656f-4065-acb9-e1b3fecf35bc','Family is something one actively maintains.
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('d3efe521-96ee-4cf6-88c5-c0af0bfde29a','studio_characters','f1a92df4-a271-4f90-beb5-662c725b2661','Mvula','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"f1a92df4-a271-4f90-beb5-662c725b2661","name":"Mvula","media":{"tbdFields":"Birth date\nExact age at death\nPronunciation\nName meaning\nHeight\nDominant hand\nParents\nSiblings\nChildhood\nExact appearance before death","canonLocks":"Male spirit\nFormer Stone Mountains scout\nOriginates from Kwaye-Zulu\nDied in a mountain crevice\nDenied final rites\nBecame a Ghede-Baka\nForcibly bound by Xolani\nTethered to Xolani''s Dead Eye\nCharcoal shadow manifestation\nWhite spirit-light eyes\nElongated spectral limbs\nFears being forgotten\nProtects Xolani reluctantly","galleryUrl":"","mediaNotes":"Use Mvula''s established portrait and full-body artwork as visual continuity references. Future artwork should preserve his charcoal-and-ash palette, spectral white eyes, gaunt silhouette, elongated fingers, smoky manifestation, and visual connection to Xolani''s Dead Eye.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Needed\nAlternate / True Form — Needed\nFull-Body Front — Done\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Needed\nEye Reference — Needed\nOutfit Breakdown — Needed\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Mvula must remain visually connected to the established Xolani design without resembling Xolani himself. Preserve his emaciated charcoal spirit body, ash-grey fractures, white spirit-light eyes, elongated limbs, smoke-like edges, and remnants of practical Stone Mountains scout clothing. His design should communicate that he was once human before becoming a corrupted restless spirit.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Mvula","race":"Restless Spirit","alias":"","gender":"Male","titles":"The Forgotten Scout\nThe Shadow of the Crevice\nThe Hunger Behind the Dead Eye","subrace":"Ghede-Baka","summary":"Mvula was once a scout of the Stone Mountains who died alone in a mountain crevice without receiving his final rites. Forgotten by the living, his abandoned spirit became a corrupted Ghede-Baka. During the Great Drought, Xolani forcibly bound Mvula through the Binding Cadence, creating a parasitic spiritual connection that ultimately tethered Mvula to Xolani''s Dead Eye.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Former scout","affiliation":"Xolani","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Spirit-bound to Xolani","elementalHeritage":""},"abilities":{"weapons":"Spectral influence","strengths":"Spirit perception\nPsychological warfare\nSensory manipulation\nSpectral movement\nDefensive instinct\nIntimidation","weaknesses":"Sacred salt\nFlorida Water\nConsecrated ground\nRitual cleansing","combatStyle":["Psychological warfare","Spiritual disruption","Fear induction","Sensory attacks","Defensive intervention"],"limitations":["Bound to Xolani","Cannot freely leave the bond","Xolani''s survival affects him","Manifestation depends on spiritual influence"],"powerSource":["Restless spirit energy","Dead Eye bond","Grey Space","Spiritual connection to Xolani"],"abilityNotes":"Mvula''s Choking Miasma creates crushing grief and hopelessness around Xolani. His Echoing Scream causes the target''s spirit to recoil from the body. Through Eye-Lock and the Direct Feed, he can expose a target to the horrifying Grey Space perceived through Xolani''s Dead Eye.","combatProfile":"Mvula fights indirectly through Xolani and the surrounding spirit space. He overwhelms enemies with despair, spiritual screams, visions, and sensory distortion while manifesting spectral limbs to influence combat. Although he frequently sabotages Xolani, his survival is tied to his host, causing him to intervene when Xolani faces lethal danger.","weaponDetails":"Mvula does not rely on a conventional physical weapon. He attacks through spiritual pressure, sensory manipulation, spectral manifestations, and his connection to Xolani''s Dead Eye and Asalato.","transformations":"Partial manifestation\nFull spirit manifestation","primaryAbilities":"Choking Miasma\nEchoing Scream\nEye-Lock\nSpectral Manifestation","secondaryAbilities":"Sensory manipulation\nSpectral guidance\nMotor interference\nDeath visions\nSpirit perception","signatureTechniques":"Direct Feed\nSpectral Intervention\nRhythm Sabotage","transformationDetails":"Mvula usually exists as a shadow clinging to Xolani''s back or within the Dead Eye. When his influence intensifies, more of his emaciated charcoal form emerges through smoke and ash. His elongated arms can manifest around Xolani and mimic or interfere with his movements."},"is_public":false,"appearance":{"build":["Emaciated","Elongated","Gaunt"],"nails":["Dark elongated nails"],"eyeHex":["#E9E8DF"],"height":"TBD","makeup":"","weight":"Weightless spirit","hairHex":["#11100F"],"skinHex":["#171615","#494642"],"eyeColor":["White spirit-light"],"grooming":"Spirit manifestation","skinTone":["Charcoal black","Ash grey"],"wardrobe":"Tattered scout clothing\nWeathered wraps\nShredded outer layers","hairColor":["Charcoal black"],"hairStyle":"Flowing shadow and drifting ash","accessories":"","faceDetails":["Hollow facial structure","Sunken cheeks","Gaunt jawline","Shadowed features"],"hairTexture":["Smoke-like","Shadow-like"],"colorPalette":"Charcoal black\nAsh grey\nBone white\nSmoke grey\nMoonlit silver","dominantHand":"TBD","outfitColors":"#11100F\n#292725\n#55514C\n#B8B5AD","alternateForm":["Partial shadow manifestation","Full spirit manifestation"],"clothingStyle":"Ruined Stone Mountains scout clothing fused into his spectral body. Clothing should appear ancient, practical, torn, and partially consumed by smoke.","appearanceNotes":"Mvula should remain recognizably humanoid while clearly supernatural. His silhouette is tall, thin, and unnerving, with charcoal smoke continuously peeling from his body. His elongated spectral arm frequently manifests over Xolani''s shoulder and mirrors Xolani''s Asalato movements.","outfitMaterials":["Tattered cloth","Weathered leather","Spectral smoke","Ash"],"postureMovement":["Predatory hovering","Unnatural stillness","Smoke-like movement","Clings behind Xolani"],"signatureOutfit":"Fragments of his former scout clothing remain within his manifestation as shredded, smoke-darkened layers that dissolve into ash and shadow. His silhouette should suggest the remains of a mountain scout rather than ornate ceremonial clothing.","distinguishingFeatures":["Charcoal smoke body","White spirit-light eyes","Elongated fingers","Emaciated arms","Ash-fractured form","Smoke-shrouded face","Unstable body edges"]},"created_at":"2026-09-25T07:04:10.977435+00:00","updated_at":"2026-09-25T07:04:10.977435+00:00","is_complete":true,"origin_lore":{"fears":["Being forgotten","The Void of the Forgotten","Xolani dying","Losing his final connection to life"],"goals":["Remain remembered","Preserve his existence","Make Xolani understand his suffering"],"beliefs":["The forgotten suffer twice","Spirits should not be enslaved","Memory preserves existence"],"culture":["Kwaye-Zulu","Stone Mountains"],"lineage":"Kwaye-Zulu","storyArc":"Mvula begins consumed by hatred toward the man who enslaved him. He torments Xolani through visions, sensory manipulation, and attempts to sabotage his rhythm. Xolani''s refusal to erase Mvula''s humanity slowly changes their bond, and Mvula begins protecting the person he once wanted to destroy because Xolani has become the only living witness to who Mvula was.","backstory":"Mvula was a scout from the Stone Mountains who was left to die in a mountain crevice during a tribal war. Denied final rites and eventually forgotten, his spirit remained trapped in bitterness and grief until he became a corrupted Ghede-Baka. During the Great Drought, Xolani found Mvula and forcibly imprisoned him through the Binding Cadence to power a ritual that brought Black Rain to Kwaye-Zulu. Mvula retaliated by spiritually overwriting Xolani''s left eye, becoming permanently tethered to the Dead Eye.","childhood":"TBD","lifestyle":["Exists through Xolani''s Dead Eye","Observes the spirit world","Whispers to Xolani","Interferes with Xolani''s senses","Protects his host when threatened"],"storyRole":"Mvula is both Xolani''s tormentor and reluctant guardian. He embodies the consequences of Xolani''s forbidden ritual while giving a voice to the forgotten dead. His constant presence turns Xolani''s spiritual abilities into both a weapon and an ongoing punishment.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Terrified of being forgotten","Resents Xolani","Carries abandonment trauma","Emotionally dependent on Xolani","Hides concern behind hostility"],"motivations":["Avoid being forgotten","Preserve his existence","Punish Xolani","Protect his remaining connection","Have his life remembered"],"personality":["Bitter","Vindictive","Observant","Hostile","Sarcastic","Manipulative","Fearful","Protective","Lonely"],"voiceSpeech":["Distorted male whisper","Ancient tone","Bitter delivery","Sardonic speech","Low spectral voice"],"likesDislikes":["Loved the smell of rain","Notices mountain flowers","Hates being forgotten","Hates spiritual enslavement","Resents forced binding"],"majorLifeEvents":"Serves as a Stone Mountains scout\nAbandoned during tribal war\nDies alone in mountain crevice\nDenied final rites\nBecomes a Ghede-Baka\nEncountered by Xolani\nForcibly bound by Binding Cadence\nPowers the Black Rain ritual\nCreates Xolani''s Dead Eye\nBecomes tethered to Xolani\nBegins reluctantly protecting Xolani"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"Xolani — Host, former captor, and reluctant companion","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"Xolani\nKwaye-Zulu\nStone Mountains\nGrey Space\nDead Eye\nAltar of the Unburied","relationshipNotes":"Mvula initially views Xolani as his jailer after being forcibly bound during the Great Drought. He tortures Xolani through visions, whispers, sensory overlap, and rhythm sabotage, yet protects him whenever death threatens them both. Xolani''s determination to remember Mvula as a man rather than a monster gradually transforms their relationship from pure hatred into reluctant mutual recognition."},"spoiler_level":"private","race_record_id":"4b626524-5522-485d-b40f-6490debf9f06","realm_record_id":"c6c8934d-b274-44f7-a1a6-a6f8f959654b","workflow_status":"draft","family_record_id":"7fe566b0-b4c5-4bef-8c77-0ab21b2a3ff4","faction_record_id":"e2b28b7d-4073-4cf3-b937-7090a913102c"}','2026-09-25T07:30:52.506724+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('b9ec0e7b-21b9-419a-801a-6ed0626f6aa2','studio_characters','838c6109-b23b-4fb2-aba6-af377de4497c','Ife','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"838c6109-b23b-4fb2-aba6-af377de4497c","name":"Ife","media":{"tbdFields":"The following details have not been permanently locked and may be changed as her story develops.\n\nIdentity / Timeline\n\nExact chronological age: TBD\n\nBirth date: TBD\n\nBirth year: TBD\n\nExact calendar system: TBD\n\nExact historical placement within the 500–1300 AD-inspired timeline: TBD\n\nPhysical Measurements\n\nWeight: TBD\n\nExact body measurements: TBD\n\nHer general athletic/curvaceous body type is established, but exact numerical measurements are unnecessary unless required for 3D production.\n\nRelationships\n\nRomantic Partner: TBD\n\nLove Interest: TBD\n\nChildren: None currently established\n\nFuture Descendants: TBD\n\nNamed Best Friend: TBD\n\nNamed Personal Friends: TBD\n\nPersonal Arch-Enemy: TBD\n\nAdditional Rivals: TBD\n\nStudents / Apprentices: TBD\n\nStory\n\nExact circumstances of Ife''s birth: Expandable\n\nDetailed childhood chronology: Expandable\n\nExact response to Rahim''s disappearance: Expandable\n\nRole in searching for Rahim: TBD\n\nFirst meeting with Ash: Not yet established\n\nInitial reaction to discovering Ash is her brother: TBD\n\nLong-term relationship with Ash: TBD\n\nMajor personal antagonist: TBD\n\nUltimate character arc resolution: Direction established, exact events TBD\n\nFuture Dragon evolution / awakening: Reserved for future development\n\nVisual Details\n\nExact height: Currently designed around 5''8\" / 173 cm but may be adjusted before final 3D model lock.\n\nExact braid count: Flexible\n\nExact number of beads: Flexible\n\nExact jewelry arrangement: Flexible\n\nMinor outfit ornamentation: Flexible\n\nMakeup intensity: Flexible by scene\n\nNail design: Flexible\n\nCeremonial clothing: Expandable\n\nSunken Dominion wardrobe: Expandable\n\nIgnis Peaks casual wardrobe: Expandable\n\nCombat wardrobe: Expandable\n\nPowers\n\nMaximum Steam temperature: TBD\n\nMaximum pressure output: TBD\n\nMaximum Bubble Prison size: TBD\n\nMaximum number of simultaneously controlled bubbles: TBD\n\nMaximum Dragon size: TBD\n\nExact stamina limits: TBD\n\nUltimate technique: TBD\n\nPotential awakened transformation: TBD\n\nThese should remain open until the wider power scale of Umbral Genesis is finalized.","canonLocks":"The following characteristics are locked canon for Ife and should remain consistent across writing, artwork, VRoid models, Blender models, animation, promotional material, and Umbra Connect.\n\nIdentity\n\nName: Ife\n\nPronunciation: EE-feh\n\nPrimary Title: The Pink Steam Dragon\n\nGender: Female\n\nPronouns: She / Her\n\nSpecies: Half-Primordial Dragon / Elemental Dragon\n\nElement: Steam\n\nElemental Equation:\nFire + Water → Steam\n\nParentage\n\nFather: Ignis — Primordial Fire\n\nMother: Leviathans — Primordial Water\n\nThis parentage should never change.\n\nSibling Relationships\n\nRahim — Full Brother\nIgnis + Leviathans\nBlood Dragon\nCurrently missing.\n\nRuchika — Maternal Half-Brother\nLeviathans + Terrax\nBone Dragon\nCreator of Ife''s Bone Dragon Whip.\n\nEzra — Paternal Half-Brother\nIgnis + Aetheros\nSapphire / Lightning Dragon.\n\nAshóNodia “Ash” — Paternal Half-Brother\nIgnis + Hecate\nAsh Dragon.\n\nCritical Story Lock:\nIfe currently does not know Ash exists.\n\nResidence\n\nPrimary residence:\n\nMoltenmaw Caverns — Ignis Peaks\n\nIfe primarily lives with Ignis.\n\nThe Sunna\n\nThe Sunna is one of Ife''s favorite places.\n\nShe can safely sleep beneath its molten surface.\n\nHer unconscious Steam magic causes the lava to boil and churn.\n\nHer Bubble Sorcery can encapsulate molten lava inside floating magical bubbles.\n\nHuman Appearance\n\nIfe is a dark-skinned woman of mixed African and Asian heritage.\n\nHer complexion remains deep warm reddish-mahogany brown.\n\nHer skin should never be significantly lightened between visual adaptations.\n\nPrimary Skin: #6B3B32\n\nShe has:\n\nType 4C natural hair\nExtremely long black braids\nPartially raised braided crown/bun\nPink beads and gemstones\nBronze/copper hair ornaments\nCosmic pink eyes\nAthletic, curvaceous build\nWarm metallic jewelry\nPink-centered wardrobe\nEye Design\n\nHer eyes are Cosmic Pink.\n\nThey contain:\n\nRose\nMagenta\nViolet\nPearl\nBubble-like iridescence\nStar-like highlights\n\nThey should never become ordinary flat pink eyes.\n\nPrimary Iris: #E75C9A\n\nSignature Color\n\nPink\n\nMore specifically:\n\nRose / Steam Pink / Bubble Pink\n\nPink belongs visually to Ife, not simply to Fire or Water.\n\nSignature Metals\n\nBronze\nCopper\nWarm Gold\n\nBright silver should not replace these as her dominant jewelry metals.\n\nSignature Weapon\n\nThe Bone Dragon Whip\n\nCreated by:\n\nRuchika\n\nThe weapon is:\n\nDragon-bone based\nSegmented\nFlexible\nHeat-resistant\nSteam conductive\nLiving/magical\nSelf-repairing\nSpecifically attuned to Ife\n\nThe creator should never be changed to Ignis, Leviathans, or another character.\n\nCore Magic\n\nIfe''s personal magic must remain centered around:\n\nSteam\n\nPressure\n\nCondensation\n\nBubble Sorcery\n\nShe should not gradually become a generic Fire-and-Water mage.\n\nFire and Water are her elemental ancestry.\n\nSteam is Ife''s element.\n\nAnger Tell\n\nWhen Ife becomes extremely angry or loses emotional control:\n\nSuperheated steam begins escaping from her nose and ears.\n\nThis is a signature visual character trait.\n\nTrue Form\n\nIfe''s true form is:\n\nThe Pink Steam Dragon\n\nCore visual traits include:\n\nDeep rose-pink scales\nPink/crimson scale variations\nCosmic pink eyes\nTranslucent underlayers\nIridescent bubble-film wing membranes\nObsidian-edged markings\nInternal volcanic glow\nLong tail\nElegant horns\nConstant supernatural steam\nBubble manifestations\n\nHer Dragon form should remain recognizably connected to her human palette.\n\nPersonality Core\n\nIfe is fundamentally:\n\nA Protector.\n\nShe is warm, observant, responsible, structured, reserved, dependable, and family-oriented.\n\nHer temper is powerful but normally controlled.\n\nHer protective personality should never be mistaken for passivity.\n\nCore Character Theme\n\nIfe represents:\n\nBalance between opposing forces.\n\nFire does not defeat Water.\n\nWater does not extinguish Fire.\n\nTogether they create something new.\n\nSteam.","galleryUrl":"","mediaNotes":"Primary Visual Style\n\nAnime Fantasy / High-Fantasy Character Design\n\nIfe should maintain a recognizable anime foundation while using detailed materials, realistic lighting, elaborate clothing, and high-quality fantasy rendering.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/portrait/1790288374064-ife-character-portrait.png","visualAssets":"Official Character Portrait\nCompleted — human-form portrait establishing Ife’s face, complexion, eyes, hair, jewelry, makeup, and overall visual identity.\n\n☑ Human Form Production Sheet\nCompleted — comprehensive visual reference showing her human appearance, outfit construction, facial details, hair, accessories, palette, and other identifying features.\n\n☑ Human Form 4-View Turnaround\nCompleted — front, left side, back, and right side references intended for VRoid/Blender modeling.\n\n☑ Human Form Face Close-Up\nCompleted.\n\n☑ Eye Detail Reference\nCompleted — cosmic pink, violet, and iridescent bubble-like iris.\n\n☑ Hair Reference\nCompleted — Type 4C hair arranged into extremely long decorated braids with a partially raised braided crown/bun.\n\n☑ Makeup Reference\nCompleted — heated rose, plum, berry, and pearl-pink makeup palette.\n\n☑ Skin Color Reference\nCompleted.\n\n☑ Official HEX Palette\nCompleted.\n\n☑ Hands / Nail Reference\nCompleted.\n\n☑ Jewelry / Accessories Reference\nCompleted.\n\n☑ Signature Outfit Reference\nCompleted.\n\n☑ Outfit Breakdown\nCompleted — individual clothing components available for modeling/texturing reference.\n\n☑ Alternate Outfit Concepts\nCompleted at concept level.\n\n☑ True Dragon Form Reference\nCompleted.\n\n☑ Dragon Production Sheet\nCompleted — includes multiple angles, head details, wing membranes, scale textures, elemental effects, and size comparison.\n\n☑ Dragon Head Reference\nCompleted.\n\n☑ Dragon Eye Reference\nCompleted.\n\n☑ Dragon Wing Reference\nCompleted.\n\n☑ Dragon Scale / Material Reference\nCompleted.\n\n☑ Bone Dragon Whip Reference\nCompleted.\n\n☑ Bone Dragon Whip Detail Sheet\nCompleted — includes handle, bone segmentation, extended configuration, coiled configuration, internal construction, and self-repair visualization.\n\n☑ Elemental Magic Reference\nCompleted — Steam, Bubble Sorcery, Lava Encapsulation, Guardian Bubble, Pressure attacks, and Scalding Garden visuals established.\n\n☑ Expression Sheet\nCompleted — neutral, soft, serious, happy, angry/steam, sad, teasing, and surprised expressions represented across production references.\n\n☐ Clean Blender A-Pose reference\n☐ Clean Blender T-Pose reference\n☐ Human body reference without jewelry obscuring anatomy\n☐ Hair-only 360° modeling sheet\n☐ Face orthographic — front/profile/3⁄4\n☐ Clothing texture sheet\n☐ Jewelry texture/material sheet\n☐ Eye texture map\n☐ Makeup texture map\n☐ Skin texture reference\n☐ Steam VFX sheet\n☐ Bubble VFX sheet\n☐ Dragon orthographic turnaround\n☐ Dragon wing fully extended orthographic reference\n☐ Dragon mouth/interior reference\n☐ Dragon claw/foot reference\n☐ Bone Dragon Whip orthographic modeling sheet\n☐ Combat pose sheet\n☐ Height comparison with Ignis, Leviathans, Rahim, Ruchika, Ezra, and Ash","productionNotes":"When recreating Ife in VRoid, prioritize:\n\nFace shape\nSkin tone\nCosmic pink eyes\nMakeup\n4C-inspired braided hairstyle\nBody proportions\nSignature pink clothing\nBronze/copper accessories\n\nAvoid lightening her complexion because of VRoid''s default shading or texture presets.\n\nHer skin should remain centered around:\n\n#6B3B32\n\nwith warm reddish highlights rather than pale beige highlights.\n\nBlender\n\nUse the clean human turnaround as the primary modeling reference.\n\nModel major components separately:\n\nBody Mesh\n\nHair / Braids\n\nHair Jewelry\n\nFace Jewelry\n\nNecklaces\n\nArm Jewelry\n\nWaist Jewelry\n\nSignature Clothing\n\nSheer Fabric Panels\n\nBone Dragon Whip\n\nThis allows accessories and clothing to be toggled independently for animation and alternate outfits.\n\nMaterial Notes\nSkin\n\nWarm deep-brown material with subtle moisture/specular response.\n\nIfe should look naturally hydrated rather than artificially glossy.\n\nDuring Steam magic, skin roughness can decrease slightly to simulate condensation.\n\nHair\n\nVery dark near-black material with subtle warm-brown reflections.\n\nAvoid excessive shine.\n\nClothing\n\nMix:\n\nSilk\nSheer magical fabric\nWoven textile\nEmbroidery\nMetallic trim\nMetals\n\nBronze and copper should show visible warmth and moderate age rather than looking like perfectly polished modern jewelry.\n\nGems\n\nPink gemstones should support:\n\nTransparency\nInternal glow\nRefraction\nPink/violet highlights\nBubble Magic\n\nTransparent material with:\n\nThin-film iridescence\nPink dominance\nViolet secondary reflections\nSmall cyan/blue highlights","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/reference/1790288270869-ife-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/alternate/1790288278147-ife-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD — no exact canonical age established","era":"500–1300 AD-inspired fantasy period","name":"Ife","race":"Half-Primordial Dragon / Elemental Dragon","alias":"The Steam Dragon; Protector of the Scalding Gardens","gender":"Female","titles":"The Pink Steam Dragon, Daughter of Fire and Water, Daughter of Ignis, Daughter of Leviathans, Protector of the Scalding Gardens, The Steam-Born Guardian","subrace":"Steam Dragon / Fire-Water Primordial Hybrid","summary":"Ife, known as the Pink Steam Dragon, is the daughter of Ignis, the Primordial embodiment of Fire, and Leviathans, the Primordial embodiment of Water. Born from two naturally opposing elemental forces, Ife represents the point at which Fire and Water reach equilibrium: Steam.\n\nIn human form, Ife is a dark-skinned young woman distinguished by her cosmic pink eyes, long decorated braids, copper-and-bronze jewelry, and flowing steam-woven clothing. Her normally composed appearance reflects her reserved and dependable personality, while subtle heat, moisture, and pink steam continuously hint at the immense elemental pressure contained within her body.\n\nIfe is naturally protective, responsible, observant, and strongly attached to her family. She rarely seeks conflict for its own sake, but threatening someone under her protection can trigger an explosive change in temperament. As her anger rises, the elemental pressure within her body increases until visible superheated steam begins escaping from her nose and ears.\n\nHer magic combines superheated steam and supernatural bubble manipulation. She can produce dense steam clouds, create durable bubble barriers, imprison enemies inside pressurized bubbles, manipulate extreme heat and pressure, and encapsulate even molten lava within magically reinforced spheres.\n\nHer signature weapon is the Bone Dragon Whip, crafted for her by her maternal half-brother Ruchika, the Bone Dragon. Modeled from Ruchika''s own tail-bone structure, the weapon is flexible, heat-resistant, magically self-repairing, and specifically attuned to Ife. She can channel steam through its living bone structure, transforming an already dangerous segmented whip into a scalding extension of her elemental power.\n\nIn her true dragon form, Ife becomes an enormous deep rose-pink Steam Dragon whose body combines draconic armor with translucent, bubble-like structures. Iridescent membranes shimmer across her wings while obsidian-edged markings glow with internal volcanic heat. Superheated pink steam perpetually surrounds her body, partially obscuring her silhouette.\n\nDespite being born from forces capable of reshaping entire realms, Ife is fundamentally a guardian. Fire gave her heat. Water gave her fluidity. But the balance between them created something belonging entirely to her.\n\nSteam is her breath. Bubbles are her prison. Lava is her playground.","heritage":"Mixed African and Asian heritage.","homeland":"Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.","pronouns":"She / Her","birthDate":"TBD","nicknames":"Pink Steam","occupation":"Elemental Guardian / Protector / Dragon Warrior","affiliation":"Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"“Ife” is a Yoruba name associated with love. This meaning suits her protective nature particularly well: despite possessing destructive elemental power, love for her family and those under her protection is one of her strongest motivations.","nationality":"Primordial Dragonkin of the Ignis Peaks","spoilerLevel":"Minor / Major depending on entry.","pronunciation":"EE-feh","currentResidence":"Moltenmaw Caverns, Ignis Peaks","elementalHeritage":"Fire + Water → Steam"},"abilities":{"weapons":"Primary Weapon\n\nThe Bone Dragon Whip\n\nSecondary Equipment\n\nBronze and copper jewelry\n\nPink elemental gemstones\n\nHeat-resistant clothing\n\nUtility belt\n\nProtective arm cuffs\n\nMagically reinforced accessories\n\nIfe generally carries very little conventional equipment because her elemental abilities provide most of what she requires.","strengths":"Exceptional Battlefield Control\n\nIfe can manipulate where opponents move and how safely they can approach her.\n\nDefensive Versatility\n\nShe can protect herself, individuals, or entire groups.\n\nEnvironmental Adaptability\n\nHeat, humidity, volcanic environments, and water-heavy environments generally favor her.\n\nThermal Resistance\n\nMany conventional heat-based attacks have dramatically reduced effectiveness against her.\n\nPressure Manipulation\n\nAllows tremendous force without requiring direct physical contact.\n\nWeapon Synergy\n\nThe Bone Dragon Whip functions almost like another part of her elemental body.\n\nHybrid Element\n\nSteam behaves differently from either Fire or Water alone, making her abilities difficult to counter through simplistic elemental logic.\n\nProtective Instinct\n\nIfe becomes extraordinarily focused when another person''s safety depends on her.","weaknesses":"Extreme Cold\n\nSevere cold can interfere with Ife''s ability to maintain high-temperature steam.\n\nIt does not automatically remove her powers, but forces her to expend substantially more energy maintaining temperature.\n\nExtremely Dry / Moisture-Depleted Environments\n\nIfe generates supernatural moisture internally, so she is never completely powerless in dry environments.\n\nHowever, producing massive quantities of steam without surrounding moisture requires greater personal energy.\n\nOverpressure\n\nIfe''s body functions like a supernatural pressure system.\n\nGenerating too much steam without properly venting it can become physically uncomfortable and eventually dangerous.\n\nVisible warning signs include:\n\nSteam escaping from her ears\nSteam escaping from her nose\nIncreased body temperature\nBrightening eyes\nUncontrolled condensation\nSpontaneous bubble formation\nProtective Exploitation\n\nIfe''s greatest psychological strength can also become a weakness.\n\nShe will frequently prioritize protecting another person over taking the tactically optimal action.\n\nAn intelligent enemy could attempt to exploit this.\n\nEmotional Pressure\n\nAnger increases her elemental output but decreases precision if allowed to escalate too far.\n\nMore power does not always mean better control.","combatStyle":"Defensive Zoner / Battlefield Controller / Mid-Range Whip Fighter","limitations":"Steam Requires Balance\n\nIfe''s greatest techniques require maintaining the correct relationship between heat and moisture.\n\nToo much heat without sufficient moisture produces unstable output.\n\nToo much moisture without sufficient heat reduces steam intensity.\n\nHer greatest mastery comes from maintaining equilibrium.\n\nBubble Durability Is Not Infinite\n\nHer bubbles are extraordinarily strong, but they can be broken by sufficient force.\n\nLarger bubbles require more energy to maintain.\n\nProtecting multiple people simultaneously increases that cost further.\n\nPressure Has Consequences\n\nCompressed steam stores enormous energy.\n\nIf one of Ife''s pressure bubbles is destroyed unexpectedly, the resulting release can endanger allies as well as enemies.\n\nShe must therefore remain aware of where every high-pressure construct is positioned.\n\nLarge-Scale Techniques Require Concentration\n\nTechniques such as Scalding Garden require Ife to track many independent constructs simultaneously.\n\nThe more bubbles she controls, the greater the mental load.\n\nDragon Form Increases Consumption\n\nHer Dragon form can produce dramatically greater elemental output, but sustaining maximum power consumes far more energy than fighting in human form.\n\nBone Dragon Whip Dependency\n\nIfe does not require the whip to use her magic.\n\nHowever, losing access to it removes one of the primary tools through which she controls mid-range combat.\n\nShe remains dangerous without it, but her fighting style changes considerably.","powerSource":"Primordial Elemental Bloodline","abilityNotes":"Ife''s abilities should always follow the visual language of Steam + Pressure + Bubbles.\n\nShe should not gradually become a generic Water mage who throws ordinary water attacks or a Fire mage who simply launches flames.\n\nThose elements belong to her parents.\n\nSteam belongs to Ife.\n\nEven when she uses inherited elemental principles, they should transform through her unique nature.\n\nFire becomes heat.\n\nWater becomes moisture.\n\nHeat + moisture becomes steam.\n\nSteam becomes pressure.\n\nCondensation becomes bubbles.\n\nBubbles become containment.\n\nPressure turns containment into a weapon.\n\nThat chain should remain the central logic behind her entire power system.\n\nHer magic should also reflect her personality.\n\nShe is a protector, so many abilities have both defensive and offensive applications.\n\nA bubble can shield a child.\n\nThe same bubble can imprison an enemy.\n\nSteam can hide an ally''s escape.\n\nThe same steam can become lethally hot.\n\nHer whip can pull someone away from danger.\n\nThe same whip can bind an opponent and channel scalding steam directly against them.\n\nThat duality is fundamental to Ife:\n\nShe possesses powers capable of horrific destruction, but her first instinct is usually to place those powers between danger and the people she loves.","combatProfile":"Combat Role: Defender / Controller\n\nPreferred Range: Mid-range\n\nSecondary Range: Close-range\n\nLong Range: Moderate through pressure attacks and environmental manipulation\n\nDefense: Exceptional\n\nBattlefield Control: Exceptional\n\nMobility: High\n\nPhysical Strength: High\n\nElemental Output: Extremely High\n\nWeapon Skill: Expert\n\nDurability: Very High\n\nThermal Resistance: Extraordinary\n\nPrecision: High\n\nStealth: Moderate normally / High inside steam\n\nCombat Temperament: Controlled and protective\n\nIfe is at her most dangerous when defending another person.\n\nThreatening her personally may provoke resistance.\n\nThreatening someone behind her can provoke overwhelming retaliation.","weaponDetails":"The Bone Dragon Whip\n\nCreator: Ruchika, the Bone Dragon\n\nOwner: Ife\n\nAttunement: Ife only\n\nMaterial: Living magical bone modeled from Ruchika''s tail-bone structure\n\nWeapon Type: Segmented Dragon-Bone Whip\n\nThe Bone Dragon Whip consists of numerous articulated bone segments connected through living magical tendons.\n\nEach segment moves almost like a miniature vertebra.\n\nThis gives the weapon extraordinary flexibility while preserving the structural strength of Dragon bone.\n\nHeat Resistance\n\nThe whip can withstand Ife''s extreme temperatures without weakening.\n\nSteam Conduction\n\nChannels running through the weapon allow Ife to send steam through its internal structure.\n\nSelf-Repair\n\nIf broken, fractured segments attempt to reconnect.\n\nBone fragments pull toward one another and reform through Ruchika''s lingering Bone magic.\n\nElemental Attunement\n\nThe weapon recognizes Ife''s elemental signature.\n\nIt responds most effectively to her Steam magic and resists being properly controlled by another wielder.\n\nLiving Flexibility\n\nThe whip can subtly alter the positioning of individual segments during movement.\n\nThis makes its trajectory unusually difficult for opponents to predict.","transformations":"Human Form\n\nIfe''s default form.\n\nShe retains full access to most Steam and Bubble Sorcery while maintaining human proportions.\n\nThis form provides the greatest precision.\n\nSteam Surge\n\nA heightened elemental state triggered voluntarily or through intense emotion.\n\nVisible changes include:\n\nBrighter pink eyes\nIncreased skin sheen\nIridescent markings becoming visible\nSteam continuously leaving her body\nHair ornaments vibrating from pressure\nBubbles forming spontaneously\nHeat distortion surrounding her silhouette\n\nHer Steam output and pressure manipulation increase considerably.\n\nDragon Form\n\nThe Pink Steam Dragon\n\nIfe releases her human shape and assumes her full elemental Dragon body.\n\nHer physical strength, durability, elemental capacity, flight, and area-of-effect attacks increase dramatically.\n\nPressure-Crowned Dragon State\n\nA high-output Dragon state in which Ife allows enormous quantities of steam pressure to accumulate around her body.\n\nA rotating halo or crown of bubbles and vapor forms around her head, neck, wings, and spine.\n\nHer translucent wing membranes become intensely iridescent.\n\nPink steam becomes so dense around her that portions of her Dragon body periodically disappear from sight.\n\nThis is not a separate species or transformation.\n\nIt is Ife pushing her Dragon form toward its highest sustainable elemental output.","primaryAbilities":"Superheated Steam Generation\n\nIfe can generate enormous quantities of steam directly from her body.\n\nShe can release it through:\n\nHer mouth\nHer nose\nHer hands\nHer skin\nHer Dragon form\nHer Bone Dragon Whip\n\nThe temperature ranges from harmless warm mist to devastating supernatural steam capable of causing severe thermal damage.\n\nSteam Manipulation\n\nOnce steam exists around her, Ife can manipulate its:\n\nDirection\nDensity\nTemperature\nSpeed\nShape\nConcentration\nPressure\n\nShe can create thin mist, concentrated jets, dense clouds, spiraling currents, or massive steam formations.\n\nBubble Sorcery\n\nIfe creates supernatural bubbles using condensed Water magic reinforced by thermal pressure.\n\nThese bubbles can vary from marble-sized spheres to structures large enough to contain people, creatures, attacks, or environmental material.\n\nThey can be used offensively or defensively.\n\nHer bubbles can:\n\nTrap enemies\nProtect allies\nCarry objects\nContain steam\nContain extreme heat\nStore pressure\nRedirect attacks\nFloat\nMove under Ife''s control\nEncapsulate molten lava\n\nTheir surfaces possess an iridescent pink-violet-blue sheen resembling soap-bubble film.\n\nThermal Pressure Manipulation\n\nPressure is one of Ife''s most dangerous abilities.\n\nShe can compress steam within a restricted area before releasing it violently.\n\nThis allows her to transform something visually beautiful—such as a floating pink bubble—into an extremely dangerous pressure weapon.\n\nThe more tightly she compresses steam, the greater the force generated when containment is released.\n\nExtreme Thermal Resistance\n\nIfe possesses extraordinary resistance to:\n\nFire\nLava\nBoiling water\nSteam\nExtreme humidity\nVolcanic environments\nSudden temperature increases\n\nShe can physically rest beneath molten lava without injury.\n\nThe Sunna is effectively a bath to her.\n\nSteam Respiration\n\nIfe can comfortably breathe within extremely hot, humid, steam-filled environments that would incapacitate ordinary beings.\n\nHer Dragon physiology allows her respiratory system to function under extreme temperature and pressure conditions.\n\nElemental Condensation\n\nIfe can rapidly cool portions of her own steam, turning vapor into concentrated moisture.\n\nThis allows her to recycle portions of her elemental output rather than allowing all generated vapor to dissipate.","secondaryAbilities":"Steam Veil\n\nIfe surrounds herself with steam, obscuring her body and making it difficult for opponents to determine her exact position.\n\nHeat Shimmer\n\nExtreme temperature around her body can distort light, causing her silhouette to appear unstable or blurred.\n\nBubble Platforms\n\nIfe can create reinforced floating bubbles capable of temporarily supporting herself or another person.\n\nThese allow unusual aerial movement without requiring full Dragon transformation.\n\nSteam Propulsion\n\nConcentrated steam can be released behind or beneath her body to produce sudden bursts of movement.\n\nShe can use this for:\n\nDodging\nJump enhancement\nMidair correction\nRapid acceleration\nPressure Detection\n\nBecause Ife is extraordinarily sensitive to changes in air and vapor pressure, she can detect disturbances moving through nearby steam.\n\nInside a sufficiently dense steam field, this gives her an unusual form of environmental awareness.\n\nAn enemy moving through her mist disrupts the pressure around them.\n\nIfe can feel it.\n\nCondensation Tracking\n\nIfe can leave nearly invisible traces of magical moisture on objects or individuals.\n\nWithin a limited distance, she can sense her own elemental residue.\n\nLava Encapsulation\n\nOne of Ife''s most visually recognizable abilities.\n\nShe can surround molten lava with reinforced bubble membranes.\n\nThe resulting spheres appear as translucent pink bubbles containing glowing molten rock.\n\nThey can float peacefully around her—or become extremely dangerous battlefield weapons.","signatureTechniques":"Steam Lash\n\nIfe channels superheated steam through the internal marrow channels of the Bone Dragon Whip.\n\nEvery segment becomes surrounded by pressurized vapor.\n\nWhen the whip strikes, the target receives both the physical impact of the bone weapon and a concentrated thermal burst.\n\nPressure Spike\n\nIfe creates a small reinforced bubble containing highly compressed steam.\n\nShe then collapses or punctures one side of the membrane.\n\nThe stored pressure erupts through the opening as an extremely concentrated blast.\n\nIt functions almost like a magical pressure cannon.\n\nScalding Bind\n\nIfe wraps the Bone Dragon Whip around an opponent.\n\nOnce the target is restrained, steam flows through the weapon and surrounds the bound area.\n\nThe longer the opponent remains trapped, the greater the heat and pressure become.\n\nIfe can control the temperature, allowing this technique to function as either restraint or severe punishment.\n\nSteam Whip Cyclone\n\nIfe rotates the Bone Dragon Whip around herself at high speed while releasing steam through its segments.\n\nThe motion creates a rotating vortex of whip strikes, scalding vapor, and pressure.\n\nThis technique serves simultaneously as offense and defense.\n\nApproaching her while the cyclone is active becomes extremely dangerous.\n\nBubble Prison\n\nIfe traps an opponent inside a reinforced bubble.\n\nShe can then manipulate conditions within it.\n\nPossible effects include:\n\nIncreasing temperature\nFilling it with steam\nIncreasing internal pressure\nRestricting oxygen\nSuspending the target above the ground\nTransporting the prisoner\n\nIfe usually uses the technique for containment rather than execution.\n\nGuardian Bubble\n\nA large defensive bubble forms around an ally or group.\n\nUnlike Bubble Prison, the internal environment remains safe and breathable.\n\nThe membrane absorbs and redistributes incoming force.\n\nPinkout\n\nIfe rapidly floods an area with extremely dense pink steam.\n\nVisibility collapses almost completely.\n\nBecause Ife can detect pressure disturbances inside her own steam, she retains a major sensory advantage while opponents become disoriented.\n\nScalding Garden\n\nOne of Ife''s major battlefield-control techniques.\n\nIfe fills an area with dozens or hundreds of floating bubbles of different sizes.\n\nSome contain:\n\nSteam\nCompressed pressure\nCondensed water\nEmpty space\nMolten material\n\nAn opponent cannot easily determine which bubbles are harmless and which are dangerous.\n\nIfe moves through this field while manipulating the bubbles around allies and enemies.\n\nThe battlefield becomes her Scalding Garden.\n\nThis technique is the origin of the title:\n\nProtector of the Scalding Gardens.\n\nLava Bloom\n\nIfe encapsulates portions of molten lava inside multiple reinforced bubbles.\n\nThe glowing spheres rise around the battlefield like flowers opening around her.\n\nShe can launch them individually, use them as barriers, or deliberately rupture their membranes.\n\nDragon''s Breath — Scalding Veil\n\nIn Dragon form, Ife exhales an enormous torrent of superheated pink steam.\n\nUnlike conventional Dragon fire breath, the attack expands rapidly after release.\n\nThis allows it to engulf a much wider area.","transformationDetails":"Human → Dragon\n\nSteam begins pouring from Ife''s body.\n\nHer surroundings become increasingly obscured until her human silhouette is almost impossible to see.\n\nWithin the steam, her body expands.\n\nPink scales emerge first across her shoulders, spine, arms, and face.\n\nHer skeletal structure lengthens.\n\nHer fingers develop into claws.\n\nHer spine extends into a tail.\n\nHer wings unfold last.\n\nWhen they open, the surrounding steam is violently pushed outward.\n\nThe completed transformation reveals the Pink Steam Dragon within the dissipating cloud."},"is_public":true,"appearance":{"build":"Athletic, curvaceous, feminine build, Defined but feminine shoulders, Strong arms, Narrow-to-moderate waist, Full hips, Powerful thighs, Strong calves, Balanced hourglass proportions","nails":"Medium-to-long almond-shaped nails.\n\nBase: translucent dusty rose.\n\nPrimary Nail Pink: #C77B91\nDeep Rose Accent: #87485F\nPearl Highlight: #F2CAD5\n\nSome nails may feature extremely fine bronze detailing or tiny bubble motifs.\n\nThey should remain elegant enough for her visual design while still being practical enough to control her weapon.","eyeHex":"Main Iris Pink: #E75C9A Deep Iris: #8E285E Light Iris Pink: #FF8FC5 Galaxy Violet: #9C68D7 Magical Glow: #FFD0EA Outer Iris Ring: #6F204E Hot-Pink Ring: #FF72B6 Pupil: #291224","height":"5''8\" / approximately 173 cm","makeup":"Ife uses a heated rose and wet-iridescent makeup palette.\n\nBlush: Burnt Rose #9E5360\nBlush Highlight: #BC6E78\nContour: #4D2928\n\nUpper Eyeshadow: Deep Plum #6E294E\nMain Eyeshadow: Rose Mauve #A94D72\nInner Lid: Iridescent Pink #E989B6\nEye Highlight: Pearl Pink #FFD0E5\n\nEyeliner: Black-Plum #25151F\nLower Lash Shadow: Smoky Burgundy #713146\n\nLip Liner: Deep Berry-Brown #642D3D\nLip Base: Burnt Rose #9E4E60\nLip Center: Pink Rose #C96A82\nLip Highlight: Bubble Pearl #EDADC5\n\nHer eyeliner extends slightly beyond the outer corners of her eyes, subtly mimicking the sharp shape of a dragon’s eye.\n\nDuring elemental activity, an extremely faint iridescent pink shimmer may appear beneath her eyes and across her upper cheekbones.","weight":"TBD","hairHex":"Primary Hair: #171116 Warm Black: #24191D Brown Highlight: #49302F Pink Magical Reflection: #8B405F","skinHex":"Primary Skin: #6B3B32 Warm Midtone: #805044 Warm Highlight: #A96E5D Bright Highlight: #C58B78 Shadow: #45241F Deep Shadow: #2A1615","eyeColor":"Cosmic Pink / Iridescent Pink-Violet","grooming":"Meticulous but not excessively polished.\n\nIfe takes particularly good care of her hair, skin, jewelry, and clothing. Her accessories are maintained carefully because several carry familial or elemental significance.\n\nHer skin naturally maintains a moisturized appearance due to her Water/Steam physiology.","skinTone":"Deep, rich warm brown complexion with strong reddish-mahogany undertones.","wardrobe":"Ife owns several clothing categories beyond her signature outfit.\n\nIgnis Peaks Casual Wear\nA simplified wrapped top with loose trousers or a shorter layered skirt. Less jewelry and fewer flowing panels. Used while relaxing around Moltenmaw Caverns.\n\nSunna / Lava-Resting Attire\nExtremely minimal heatproof garments designed for resting within or around the Sunna. Most conventional clothing would be unnecessary while submerged in molten environments.\n\nCombat Attire\nA tighter, more secured version of her signature outfit. Flowing sections are shortened or magically controlled to prevent interference with the Bone Dragon Whip.\n\nCeremonial Attire\nLonger and significantly more elaborate. Features extensive bronze jewelry, pink gemstones, translucent bubble-film fabrics, and visual symbolism representing both Fire and Water.\n\nSunken Dominion Attire\nClothing influenced more heavily by her maternal heritage and Leviathans’ aquatic realm, emphasizing flowing silhouettes, iridescent materials, pearls, water motifs, and cooler pink-violet accents.","hairColor":"Natural Black","hairStyle":"Long, intricate braids arranged into a partially raised braided crown/bun with the remaining braids falling down her back.  The braids reach approximately to her lower back or upper thighs and are decorated selectively with:  Pink glass/crystal beads Bronze rings Copper cuffs Small bubble-shaped ornaments Fine metallic chains  Several thinner face-framing braids remain loose around her temples and cheeks.  The hairstyle should feel elaborate without becoming perfectly symmetrical.","accessories":"Ife wears numerous carefully selected metallic and gemstone accessories:\n\nLarge bronze/gold hoop earrings\nPink gemstone earrings\nForehead jewelry\nFine head chains\nBraided hair rings\nPink hair beads\nBronze braid cuffs\nLayered necklaces\nChoker\nUpper-arm cuffs\nBracelets\nWrist cuffs\nWaist chains\nDecorative belt\nHip chains\nAnklets\nPink bubble-shaped gemstones\n\nMost jewelry uses bronze, copper, and warm gold rather than bright yellow gold.\n\nCircular designs symbolize bubbles, water droplets, pressure chambers, and the union of Fire and Water.","faceDetails":"Ife has a softly angular oval face with:\n\nHigh cheekbones\nDefined jawline\nFull lips\nStraight-to-softly broad nose\nAlmond-shaped eyes\nThick natural eyebrows\nLong dark eyelashes\nSlightly upturned outer eye corners\n\nHer resting expression is usually calm, observant, and somewhat reserved.\n\nHer eyes carry most of her emotional expression.\n\nWhen angry, her expression changes dramatically: brows lower, pupils intensify, jaw tightens, and steam begins escaping around her face.","hairTexture":"Type 4C","colorPalette":"Deep Mahogany — #6B3B32\nWarm Brown — #805044\nSkin Highlight — #A96E5D\n\nHair\nDragon Black — #171116\nWarm Black — #24191D\n\nSignature Pink\nSteam Rose — #C77B91\n\nMagic Pink\nCosmic Pink — #E75C9A\n\nLight Pink\nBubble Blush — #E5A7B8\n\nPearl Pink\nSteam Pearl — #F2CAD5\n\nDeep Rose\nPressure Rose — #87485F\n\nViolet\nBubble Violet — #9C68D7\n\nIridescent Blue Accent\nBubble Blue — #82C9DF\n\nBronze\nDragon Bronze — #9B633B\n\nCopper\nMolten Copper — #B96E46\n\nGold\nSteam Gold — #D9A568\n\nObsidian\nVolcanic Black — #21191C\n\nHer dominant visual hierarchy should be:\n\nDeep Brown + Pink + Bronze\n\nwith\n\nViolet + Iridescent Blue + Gold","dominantHand":"Dominant Hand Right-handed","outfitColors":"Main Fabric\nDusty Steam Pink — #C77B91\n\nSecondary Fabric\nLight Rose — #E5A7B8\n\nTranslucent Fabric\nPearl Pink — #F2CAD5\n\nFabric Shadows\nDeep Rose — #87485F\n\nLight Neutral Accent\nWarm Cream — #E8D3C0\n\nBronze Hardware\n#9B633B\n\nCopper Hardware\n#B96E46\n\nGold Highlights\n#D9A568\n\nPink Gemstones\n#D9568D\n\nGemstone Highlights\n#FFB4DB\n\nIridescent Reflection\n#B894E8 / #82C9DF","alternateForm":"Pink Steam Dragon\n\nIfe’s true form is an enormous serpentine-winged dragon covered primarily in deep rose-pink scales.\n\nHer dragon body features:\n\nDeep rose and crimson-pink armored scales\nTranslucent scale underlayers\nObsidian-edged markings\nInternal orange-red volcanic glow\nIridescent bubble-film wing membranes\nLong flexible tail\nElegant elongated horns\nSharp swept-back facial spines\nCosmic pink eyes\nConstant supernatural steam aura\n\nHer wing membranes are particularly distinctive. Rather than appearing completely opaque, they resemble extremely durable soap-bubble film, producing pink, violet, blue, and pearlescent reflections as light passes across them.","clothingStyle":"Early-medieval fantasy clothing influenced by African/Sahelian silhouettes combined with supernatural Steam Dragon materials.\n\nIfe favors flowing garments that allow unrestricted movement. Her clothing balances elegance with practicality rather than functioning as heavy armor.\n\nHer signature aesthetic combines:\nDraped fabric\nLayered skirts\nSplit panels\nWrapped fabric\nDecorative belts\nMetallic body jewelry\nArm cuffs\nLight protective pieces\nSemi-translucent magical textiles\n\nHer clothing frequently incorporates bubble and circular motifs.","appearanceNotes":"Ife should always visually communicate the meeting point between Fire and Water.\n\nNothing about her design should make her appear exclusively fire-aligned or exclusively water-aligned.\n\nHer warm skin, bronze metals, volcanic highlights, and occasional orange-red glow represent Ignis and Fire.\n\nHer flowing fabrics, iridescence, bubble motifs, translucent materials, moisture, and fluid movement represent Leviathans and Water.\n\nPink belongs specifically to Ife.\n\nIt is the visual bridge between those inherited forces and should remain her dominant supernatural color.\n\nEven when completely still, Ife should look subtly unusual. Light may catch moisture on her skin. A braid ornament may appear slightly fogged. A tiny bubble may briefly form and disappear near her hand. Heat may distort the air immediately around her.\n\nThese effects should remain understated while she is calm.\n\nWhen her emotions or power increase, the same details escalate dramatically—pink steam thickens around her body, her cosmic eyes brighten, bubbles manifest in the surrounding air, her skin develops stronger iridescent highlights, and extreme heat begins distorting her silhouette.\n\nHer human form should always retain the impression that an enormous elemental dragon is being contained inside a deceptively calm body.","outfitMaterials":"Ife’s clothing is primarily made from steam-woven alchemical silk, a magically engineered lightweight textile capable of surviving the extreme conditions of the Ignis Peaks.\n\nThe material is:\n\nFire-resistant\nHeat-resistant\nMoisture-resistant\nLightweight\nHighly flexible\nBreathable\nSlightly reflective\nCapable of interacting with Ife’s steam magic\n\nSome outer panels contain translucent magical fibers that resemble wet silk or extremely thin bubble film.\n\nMetallic components are primarily bronze and copper treated to survive volcanic temperatures.\n\nPink gemstones incorporated into the outfit help conduct and stabilize portions of her elemental energy.","postureMovement":"Ife naturally stands upright with relaxed shoulders and a composed posture.\n\nHer normal movements are smooth, economical, and deliberate. She rarely wastes energy through unnecessary gestures.\n\nIn combat, however, her movement becomes much more circular and flowing. She rotates through her hips and shoulders to control the Bone Dragon Whip, allowing its segmented structure to orbit around her body before striking.\n\nHer fighting silhouette should therefore resemble a mixture of:\n\nflowing water + rising steam + the snapping violence of a whip.","signatureOutfit":"Ife’s signature outfit consists of a fitted, wrapped upper garment combined with flowing asymmetrical skirt panels and semi-transparent steam-woven fabric.\n\nThe upper garment crosses around the chest and torso while leaving enough freedom for her shoulders and arms to control her whip.\n\nA decorated metallic belt anchors several layered pieces of fabric around her hips.\n\nLong translucent pink panels descend from her waist and move dramatically whenever she walks, fights, or releases steam.\n\nBronze arm cuffs, bracelets, waist jewelry, anklets, and gemstone ornaments complete the outfit.\n\nThe overall appearance should communicate:\n\nSteam Dragon Princess + Warrior + Guardian\n\nwithout relying on conventional plate armor.","distinguishingFeatures":"Ife can immediately be recognized by several traits:\n\nCosmic pink irises with bubble-like iridescence.\n\nDeep warm-brown skin.\n\nExtremely long decorated black braids.\n\nPink, bronze, copper, and gold visual palette.\n\nPersistent subtle moisture/heat shimmer around her skin.\n\nPink steam manifesting around her body when using magic.\n\nSteam escaping from her nose and ears when severely angry.\n\nBubble-like magical particles forming around her during heightened elemental activity.\n\nHer Bone Dragon Whip.\n\nIn certain lighting, extremely faint pink iridescent patterns can become visible beneath portions of her skin, resembling branching steam-pressure channels. These become more noticeable when she channels large amounts of elemental power."},"created_at":"2026-09-24T05:50:30.442929+00:00","updated_at":"2026-09-25T00:58:12.758892+00:00","is_complete":true,"origin_lore":{"fears":"Ife''s deepest fear is:\n\nBeing unable to protect someone she loves.\n\nRahim''s disappearance directly challenges her identity as a protector.\n\nShe also struggles with over-responsibility.\n\nIfe can convince herself that because she could have helped someone, she therefore should have prevented whatever happened to them.\n\nThis creates a dangerous internal question:\n\nWhere does responsibility end?\n\nShe cannot protect everyone.\n\nAccepting that is much harder for her than fighting a Dragon.\n\nAnother internal conflict comes from anger.\n\nIfe is normally controlled, but once her emotions breach that control, the immense pressure contained within her becomes physically dangerous.\n\nPart of her emotional discipline therefore comes from necessity.","goals":"Protect Her Family\n\nHer most consistent personal goal.\n\nMaster Her Element\n\nIfe wants complete command over temperature, steam density, bubble durability, and pressure.\n\nUnderstand Her Place Between Two Realms\n\nShe belongs to both Ignis and Leviathans'' elemental worlds while possessing an element belonging entirely to herself.\n\nFind Answers About Rahim\n\nHer brother''s disappearance remains unresolved.\n\nWhether she admits it openly or not, she wants to know what happened to him.\n\nBecome Strong Enough That Protection Is a Choice\n\nIfe does not want to protect others because she fears everything around them.\n\nShe wants enough strength that she can choose peace without being helpless.","beliefs":"Ife believes:\n\nStrength exists to protect something.\n\nPower without purpose means very little to her.\n\nShe respects warriors and powerful beings but is less impressed by strength used purely for intimidation.\n\nShe also believes opposing forces do not automatically need to destroy one another.\n\nHer own existence proves otherwise.\n\nFire and Water created her.\n\nContradiction created balance.\n\nThat principle influences how she views people as well as elements.","culture":"Ife possesses a mixed African and Asian heritage, inherited through her paternal and maternal bloodlines.\n\nHer upbringing is heavily influenced by the culture of the Ignis Peaks, where strength, endurance, competition, and direct displays of elemental power are commonplace.\n\nIgnis''s philosophy particularly shaped her understanding of strength.\n\nWithin his family, combat is not automatically associated with hatred.\n\nCompetition can be affection.\n\nSparring can be bonding.\n\nBeing challenged can be a sign of respect.\n\nHowever, Ife''s maternal connection to Leviathans introduced another philosophy:\n\nAdaptation.\n\nWater survives because it changes.\n\nFire survives because it consumes.\n\nSteam survives because it can do both.\n\nIfe''s worldview developed between those philosophies.","lineage":"Primordial Elemental Lineage  Paternal Element: Fire  Maternal Element: Water  Personal Element: Steam  Ife represents a successful equilibrium between opposing Primordial forces.  Her existence demonstrates that Primordial elements do not necessarily produce a simple mixture when combined through descendants.  Instead, their children can develop entirely new elemental expressions.  For Ife:  Fire + Water → Steam  Steam therefore belongs specifically to her elemental identity.  She did not inherit half of Ignis''s fire abilities and half of Leviathans'' water abilities.  Their elemental principles fused and became something new.","storyArc":"Ife''s overarching character arc centers on the difference between:\n\nProtecting someone\n\nand\n\nbelieving you are responsible for everything that happens to them.\n\nAt the beginning of her deeper story, Ife defines much of her value through usefulness.\n\nShe protects.\n\nShe stabilizes.\n\nShe fixes.\n\nShe contains.\n\nShe endures.\n\nRahim''s disappearance creates something she cannot simply fix.\n\nThat forces her to confront the limits of protection.\n\nHer eventual discovery of Ash can deepen this conflict dramatically.\n\nLearning that she had a younger brother living through danger and isolation without her knowledge could immediately trigger Ife''s instinct to compensate:\n\nI should have been there.\n\nBut she couldn''t have been.\n\nShe didn''t know.\n\nThat distinction matters.\n\nHer growth therefore does not require Ife to stop being protective.\n\nProtection is one of her greatest qualities.\n\nInstead, she must learn that:\n\nLove does not require absolute control over another person''s fate.\n\nBy the later stages of her arc, Ife can remain the fierce guardian she has always been while finally allowing her siblings, allies, and family to protect her as well.\n\nShe stops seeing herself merely as the barrier standing between her loved ones and the world.\n\nShe becomes part of the family standing together behind that barrier.\n\nAnd that development perfectly reflects her element.\n\nSteam cannot exist through Fire alone.\n\nIt cannot exist through Water alone.\n\nIfe has always been strongest when opposing forces are allowed to support one another.","backstory":"Ife was born from a contradiction.\n\nIgnis was Fire.\n\nLeviathans was Water.\n\nNeither merely controlled their respective elements. They were primordial embodiments of them.\n\nBy ordinary elemental logic, their powers should have opposed one another endlessly.\n\nTheir daughter proved otherwise.\n\nThe infant born from their union did not emerge divided between Fire and Water.\n\nShe produced steam.\n\nFrom her earliest years, Ife existed comfortably within environments that should have belonged exclusively to one parent or the other. Heat could not consume her. Moisture could not extinguish her elemental core.\n\nHer body transformed conflict into equilibrium.\n\nShe spent much of her upbringing in the Ignis Peaks under the influence of her father. Ignis valued strength, competition, courage, and the thrill of testing oneself against powerful opponents.\n\nHis children were not protected from those expectations.\n\nThey participated in them.\n\nIfe learned to fight because her father expected his children to understand their own strength.\n\nBut she never developed Ignis''s fascination with combat for combat''s sake.\n\nShe became a defender.\n\nWhere another fighter might see an enemy and think about destroying them, Ife naturally considers what stands behind her.\n\nA sibling.\n\nA friend.\n\nA home.\n\nSomeone weaker.\n\nSomething worth preserving.\n\nThat instinct eventually shaped her unusual fighting style.\n\nSteam allowed her to obscure.\n\nBubbles allowed her to contain.\n\nPressure allowed her to immobilize.\n\nHeat ensured that containment could become devastating whenever necessary.\n\nThen Ruchika gave her the weapon that completed the style.\n\nThe Bone Dragon Whip gave Ife reach.\n\nShe could surround enemies rather than charging directly toward them. She could pull threats away from allies, bind opponents, create defensive circles, and channel superheated steam directly through the weapon.\n\nHer powers and personality became reflections of one another.\n\nContain first. Protect first. Destroy only when necessary.\n\nYet Ife''s dedication to family also created her greatest vulnerability.\n\nRahim disappeared.\n\nThere was no enemy for her to bind.\n\nNo attack she could block.\n\nNo battlefield where she could simply stand between her brother and danger.\n\nFor someone whose identity revolves around protecting others, losing someone she loves without being able to stop it is profoundly difficult.\n\nAnd somewhere beyond her awareness exists another complication.\n\nAshóNodia.\n\nAnother son of Ignis.\n\nAnother Dragon.\n\nAnother brother.\n\nIfe does not know him.\n\nNot yet.","childhood":"Ife''s childhood was anything but physically ordinary.\n\nShe grew up in Moltenmaw Caverns, surrounded by volcanic chambers, magma rivers, extreme heat, Dragonkin, and beings capable of surviving conditions lethal to ordinary mortals.\n\nTo Ife, lava was never frightening.\n\nIt was home.\n\nOne of the places she became most attached to was the Sunna, the enormous lava pool used by Ignis for relaxation.\n\nIfe discovered very young that she could descend beneath its molten surface without injury.\n\nEventually, she began sleeping there.\n\nHer unconscious elemental reactions transformed the Sunna whenever she rested.\n\nSteam caused sections of the lava to bubble and churn.\n\nHer bubble magic would spontaneously surround pieces of molten rock, creating floating translucent spheres containing glowing lava.\n\nWhat would be a horrifying volcanic phenomenon to an ordinary person became one of Ife''s most peaceful childhood environments.\n\nLearning Control\n\nHer greatest childhood difficulty was not producing steam.\n\nIt was containing pressure.\n\nStrong emotions caused her internal temperature and elemental pressure to rise.\n\nAnger was particularly problematic.\n\nBefore Ife learned emotional control, irritated outbursts could fill rooms with steam, obscure entire chambers, or cause bubbles to manifest uncontrollably.\n\nEventually her family learned one particularly obvious warning sign:\n\nWhen steam begins pouring from Ife''s ears and nose, someone has pushed her considerably beyond her normal patience.","lifestyle":"Despite her extraordinary heritage, Ife enjoys surprisingly peaceful routines.\n\nShe spends considerable time within the Moltenmaw Caverns.\n\nThe Sunna is one of her favorite places.\n\nShe may disappear beneath the lava for hours simply to sleep.\n\nHer ambient magic turns the pool into something resembling an enormous volcanic jacuzzi.\n\nFloating bubbles containing molten lava often surround her.\n\nShe also:\n\nMaintains her extremely long braids.\n\nCleans and inspects the Bone Dragon Whip.\n\nOrganizes her jewelry.\n\nPractices controlled steam manipulation.\n\nCreates bubbles absentmindedly.\n\nTrains with family.\n\nVisits areas connected to her mother''s domain.\n\nEnjoys periods of solitude after spending extensive time around louder personalities.\n\nShe is one of those people who genuinely appreciates having a routine.","storyRole":"Elemental Guardian / Dragon Heir / Family Anchor\n\nIfe occupies an important position within the Primordial family because she connects several major elemental bloodlines.\n\nThrough Ignis, she is connected to Fire.\n\nThrough Leviathans, she is connected to Water.\n\nThrough Rahim, she is connected to the mystery surrounding the missing Blood Dragon.\n\nThrough Ruchika, she is connected to Terrax''s branch of the family.\n\nThrough Ezra, she is connected to Aetheros'' branch.\n\nAnd through Ash—without knowing it yet—she is connected to one of the family''s most significant hidden bloodlines.\n\nThis places Ife naturally near the center of several family conflicts even though she is not someone who actively seeks political or personal power.","birthplace":"Moltenmaw Caverns, Ignis Peaks   Ife was born within the domain of her father, Ignis, the Primordial embodiment of Fire.  Her birth was extraordinary because she was conceived from two Primordials whose natural elements fundamentally oppose one another: Fire and Water. Rather than one element destroying or suppressing the other, the two reached equilibrium within Ife.  That equilibrium became Steam.  Although the Ignis Peaks are considered her birthplace and primary homeland, Ife possesses an equally legitimate ancestral connection to her mother''s domain, the Sunken Dominion, which encompasses the waters of the world.  She therefore belongs naturally to two elemental realms without being completely defined by either.","psychology":"Ife''s psychological center is built around stability.\n\nShe is the equilibrium between two enormous opposing forces, and she subconsciously recreates that role in her relationships.\n\nShe becomes the person who stabilizes situations.\n\nThe mediator.\n\nThe protector.\n\nThe one who remembers practical things while everyone else is reacting emotionally.\n\nBut that creates a hidden weakness.\n\nPeople who constantly function as another person''s stability can begin believing they are not allowed to become unstable themselves.\n\nIfe has difficulty admitting when she needs protection.\n\nShe can offer support much more easily than she can request it.\n\nHer long-term emotional development should challenge that belief.\n\nBeing protected does not make the protector weak.","motivations":"Ife''s strongest motivation is protection.\n\nShe wants the people she loves to remain safe, even when those people are perfectly capable of defending themselves.\n\nFamily is particularly important to her.\n\nShe also seeks balance.\n\nAs the living intersection between two opposing Primordial forces, she instinctively dislikes situations where one extreme completely overwhelms another.","personality":"Primary Archetype: The Defender\n\nIfe is:\n\nWarm\nReserved\nObservant\nProtective\nDependable\nPatient\nPractical\nFamily-oriented\nResponsible\nQuietly affectionate\nExtremely stubborn when protecting someone\n\nShe rarely needs to dominate a conversation.\n\nInstead, she watches.\n\nShe notices who has eaten.\n\nWho is injured.\n\nWho has become unusually quiet.\n\nWho disappeared from the room.\n\nWho is pretending that something doesn''t hurt.\n\nHer affection frequently manifests through actions rather than speeches.\n\nHowever, her patience has limits.\n\nOnce those limits are crossed, Ife possesses an unexpectedly explosive temper.\n\nHer family knows the rule:\n\nIf steam starts coming out of her ears, stop talking.","voiceSpeech":"Ife speaks in a warm, controlled, medium-low feminine voice.\n\nHer normal speech is measured and direct.\n\nShe does not ramble unnecessarily and rarely raises her voice to establish authority.\n\nHer humor tends to be dry and understated.\n\nAround family, her voice becomes noticeably warmer and occasionally teasing.\n\nWhen irritated, her sentences become shorter.\n\nWhen genuinely angry, the opposite of what people might expect happens:\n\nIfe becomes quieter.\n\nHer voice lowers.\n\nHer words become extremely deliberate.\n\nThen the steam starts.\n\nShe does not need to scream for people to realize they are in danger.","likesDislikes":"Likes\nThe Sunna\nExtreme warmth\nHot springs\nSteam\nRain hitting warm stone\nQuiet mornings\nFamily gatherings\nOrder and routine\nBeautiful jewelry\nBronze and copper craftsmanship\nPink gemstones\nBraiding and hair decoration\nBubbles\nSwimming\nSleeping somewhere ridiculously hot\nTraining with people she trusts\nTaking care of others\nPeace after conflict\n\nDislikes\n\nNeedless cruelty\nThreats toward her family\nBetrayal\nRecklessness that endangers other people\nBeing unable to help\nUnnecessary chaos\nPeople touching her belongings without permission\nSomeone mishandling the Bone Dragon Whip\nBeing pressured to discuss emotions before she is ready\nWatching powerful people bully weaker ones\n\nPreferences\n\nFavorite Color: Pink — particularly deep rose and iridescent pink.\n\nPreferred Metals: Bronze and copper.\n\nPreferred Environment: Warm, humid, volcanic environments.\n\nPreferred Combat Distance: Mid-range transitioning into close-range.\n\nPreferred Weapon: Bone Dragon Whip.\n\nPreferred Resting Place: Beneath the Sunna.","majorLifeEvents":"Birth of the Pink Steam Dragon\n\nThe union of Fire and Water produces a new elemental Dragon lineage: Steam.\n\nChildhood in Moltenmaw\n\nIfe grows up within the volcanic environment of the Ignis Peaks and develops extraordinary thermal resistance.\n\nDiscovery of the Sunna\n\nShe begins using Ignis''s enormous lava pool as a personal resting place and eventually develops her famous habit of sleeping beneath its surface.\n\nMastery of Bubble Sorcery\n\nIfe discovers that her steam can interact with magically reinforced bubbles, allowing her to manipulate pressure, heat, containment, and protection.\n\nTraining Under Ignis\n\nIfe participates in Ignis''s brutal family sparring traditions and learns that being defensive does not mean being physically weak.\n\nThe Bone Dragon Whip\n\nRuchika crafts a living, self-repairing bone whip specifically for his sister.\n\nIt becomes Ife''s signature weapon.\n\nRahim''s Disappearance\n\nHer full brother disappears under mysterious circumstances.\n\nHis absence leaves an unresolved fracture within Ife''s otherwise family-centered worldview.\n\nThe Unknown Brother\n\nAsh exists somewhere beyond Ife''s knowledge.\n\nShe has yet to discover that Ignis has another son—or that the mysterious Ash Dragon is her younger brother."},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/portrait/1790288374064-ife-character-portrait.png","relationships":{"allies":"Her Siblings\n\nDespite their disagreements and complicated family history, Ife''s siblings represent some of her strongest natural allies.\n\nIgnis Peaks\n\nIfe has strong connections among the Dragonkin, elemental inhabitants, and loyal followers living within her father''s realm.\n\nBecause she resides there, many inhabitants recognize her not merely as Ignis''s daughter but as one of the realm''s active protectors.\n\nSunken Dominion\n\nThrough Leviathans, Ife also possesses familial and elemental ties to the inhabitants of the world''s aquatic territories.\n\nShe therefore occupies an unusual position:\n\nShe can walk comfortably among beings associated with both Fire and Water despite those elements normally existing in opposition.\n\nNamed Personal Friends\n\nTBD\n\nSpecific non-family friendships have not yet been established in canon.","rivals":"Ezra — Friendly / Sibling Rival\n\nEzra is currently Ife''s clearest natural rival.\n\nTheir rivalry centers on:\n\nSpeed versus control.\n\nLightning versus Steam.\n\nFlashiness versus patience.\n\nAggression versus containment.\n\nNeither needs to genuinely dislike the other for their battles to become intense.\n\nBeing children of Ignis also means neither expects their sibling to treat them delicately during training.\n\nAdditional Rivals\n\nTBD\n\nNo major hostile rival has yet been permanently established.","enemies":"No specific personal arch-enemy currently established.\n\nIfe naturally opposes individuals or factions threatening:\n\nHer family\nIgnis Peaks\nThe Sunken Dominion\nInnocent people under her protection\nHer siblings\nThose incapable of defending themselves\n\nHowever, these should not automatically be classified as personal enemies.\n\nA true Ife antagonist should ideally challenge her philosophy of protection, not simply be another powerful fighter.\n\nNamed Enemies: TBD","mentors":"Ignis — Combat Influence\n\nIgnis serves as one of Ife''s most important combat influences.\n\nHis family tournaments and relentless sparring taught her:\n\nDurability\nCourage\nPressure tolerance\nReading powerful opponents\nFighting while exhausted\nRefusing to panic against overwhelming strength\n\nHe did not necessarily teach Ife every technique she knows.\n\nRather, he created the environment in which weakness had to become competence.\n\nLeviathans — Elemental Influence\n\nLeviathans represents the other half of Ife''s elemental education.\n\nHer maternal influence taught Ife principles associated with:\n\nFlow\nAdaptability\nFluid movement\nPatience\nEnvironmental awareness\nChanging form rather than resisting everything directly\n\nIfe''s fighting philosophy ultimately combines lessons from both parents.\n\nRuchika — Weapon Influence\n\nRuchika''s contribution is primarily tied to Ife''s Bone Dragon Whip.\n\nHis understanding of Bone magic and the construction of her weapon allowed Ife to develop an entirely new style around Steam conduction and segmented-whip combat.\n\nStudents\n\nNone currently established.\n\nIfe does not currently have a canonical apprentice or student.\n\nThis remains available for future development.","parents":"Ignis — Father\n\nRelationship: Biological Father\nElement: Primordial Fire\nStatus: Active relationship\nRealm: Ignis Peaks\n\nIgnis is Ife''s father and one of the strongest influences on her upbringing.\n\nIfe primarily lives within Moltenmaw Caverns in the Ignis Peaks, placing her physically closer to Ignis throughout much of her everyday life.\n\nTheir personalities are very different.\n\nIgnis is fascinated by strength, competition, powerful opponents, and the thrill of testing himself against beings capable of challenging him.\n\nIfe is much more defensive and reserved.\n\nShe does not seek battle simply because someone strong exists.\n\nNevertheless, she understands her father''s philosophy better than outsiders might expect.\n\nIgnis''s brutal family sparring sessions taught Ife how to remain composed while facing opponents considerably stronger than herself. He does not dramatically hold back simply because his children are fighting him.\n\nFor Ignis, challenging his children is part of loving them.\n\nIfe grew up understanding that.\n\nShe may complain about her father''s ridiculous enthusiasm for another family tournament, but she will still participate.\n\nThe Sunna, Ignis''s enormous lava pool, has also become one of Ife''s favorite resting places. She regularly sleeps beneath its molten surface, occasionally turning her father''s peaceful lava bath into a bubbling volcanic jacuzzi through her unconscious Steam magic.\n\nTheir relationship can be summarized as:\n\nFire taught Steam how to withstand pressure.\n\nLeviathans — Mother\n\nRelationship: Biological Mother\nElement: Primordial Water\nStatus: Active relationship\nRealm: Sunken Dominion / The Waters of the World\n\nLeviathans is Ife''s mother and the source of the Water half of her elemental existence.\n\nAlthough Ife primarily resides with Ignis, she maintains a legitimate familial and elemental connection to her mother''s realm.\n\nWhere Ignis influenced Ife''s understanding of strength, Leviathans influenced her understanding of adaptation.\n\nWater does not always confront an obstacle directly.\n\nIt flows around it.\n\nWaits.\n\nChanges shape.\n\nFinds another path.\n\nThat philosophy naturally complements Ife''s personality far more closely than Ignis''s love of direct confrontation.\n\nIfe''s fluid movements, patience, defensive instincts, and adaptability all reflect aspects of her maternal heritage.\n\nHer relationship with Leviathans also prevents Ife from viewing herself solely as a daughter of the Ignis Peaks.\n\nShe belongs to Fire.\n\nShe belongs to Water.\n\nAnd ultimately, she belongs to neither completely.\n\nShe is Steam.","partner":"None currently established.\n\nIfe does not currently have a canonical romantic partner or love interest.\n\nThis portion of her character remains open rather than assigning her a relationship simply to fill the category.\n\nStatus: TBD.","children":"None currently established.\n\nIfe has no canonical children or descendants at this point in the story.\n\nStatus: TBD / Open for future story development.","siblings":"Rahim — Full Brother\n\nRelationship: Full biological brother\nShared Parents: Ignis + Leviathans\nDragon Element: Blood\nTitle: The Blood Dragon\nStatus: Missing\n\nRahim is one of the most emotionally important relationships in Ife''s life.\n\nThey share both parents, making him her full sibling within a family otherwise composed largely of half-sibling elemental branches.\n\nTheir personalities differ dramatically.\n\nRahim''s Blood Dragon nature is chaotic, aggressive, and dangerous.\n\nIfe is structured, protective, and controlled.\n\nWhere Rahim can become consumed by bloodlust, Ife naturally attempts to contain dangerous situations.\n\nThis does not make them opposites who hate one another.\n\nThey are siblings whose elemental expressions took radically different paths from the exact same parents.\n\nRahim is what happens when Fire and Water become life, hunger, and blood.\n\nIfe is what happens when Fire and Water achieve equilibrium.\n\nRahim''s disappearance deeply affects her.\n\nFor someone who defines herself through protecting family, having her own brother disappear without being able to prevent it represents one of Ife''s greatest emotional wounds.\n\nShe has not stopped caring about what happened to him.\n\nRuchika — Maternal Half-Brother\n\nRelationship: Older maternal half-brother\nShared Parent: Leviathans\nOther Parent: Terrax\nDragon Element: Bone\nTitle: The Bone Dragon\n\nRuchika and Ife share a particularly tangible sibling bond.\n\nRuchika created Ife''s Bone Dragon Whip specifically for her.\n\nThe weapon is modeled after his own tail-bone structure and carries his Bone magic within it.\n\nFor Ife, this means she effectively carries something representing her brother into every major battle.\n\nThe weapon''s self-repairing nature reinforces that symbolism.\n\nIt breaks.\n\nIt returns together.\n\nIt survives.\n\nTheir relationship carries a strong protective quality, although both express protection differently.\n\nRuchika gave his sister a weapon capable of protecting herself when he cannot physically be beside her.\n\nIfe treats the Bone Dragon Whip accordingly.\n\nSomeone carelessly touching or disrespecting it is one of the fastest ways to irritate her.\n\nEzra — Paternal Half-Brother\n\nRelationship: Paternal half-brother\nShared Parent: Ignis\nOther Parent: Aetheros\nDragon Element: Lightning\nTitle: The Sapphire Dragon\n\nEzra brings out a more competitive side of Ife.\n\nHe is energetic, flashy, prideful, fast, and naturally confident in his own abilities.\n\nIfe is considerably quieter.\n\nThis makes their sibling dynamic entertaining.\n\nEzra may announce exactly how impressive his newest technique is.\n\nIfe may simply look at him and ask whether he is finished.\n\nTheir elemental abilities also create interesting sparring matches.\n\nLightning favors speed and sudden overwhelming attacks.\n\nSteam favors obscuration, containment, and battlefield control.\n\nEzra can be extremely difficult for Ife to catch.\n\nIfe can make the battlefield increasingly miserable for Ezra to navigate.\n\nTheir rivalry is primarily familial and competitive rather than hostile.\n\nRegardless of how much they irritate one another, an outside threat against one sibling immediately changes the other''s behavior.\n\nAshóNodia “Ash” — Paternal Half-Brother\n\nRelationship: Younger paternal half-brother\nShared Parent: Ignis\nOther Parent: Hecate\nDragon Element: Ash\nTitle: The Ash Dragon\nCurrent Relationship Status: Unknown to Ife\n\nThis is currently Ife''s most important hidden sibling relationship.\n\nAsh is her brother.\n\nIfe does not know he exists.\n\nShe therefore has no established personal relationship with him yet.\n\nThat absence is intentional and important.\n\nIf Ife eventually discovers the truth, Ash presents a difficult emotional situation for her.\n\nHer first instinct would likely be protective.\n\nHer second could be guilt.\n\nNot because she actually failed him—but because Ife has a tendency to feel responsible for people she loves.\n\nLearning that a younger brother existed and experienced major hardships without her knowing could provoke the immediate thought:\n\n“Where was I?”\n\nThe answer is simple.\n\nShe did not know.\n\nAccepting that she cannot protect someone from circumstances she never knew existed could become an important part of her development.\n\nTheir eventual relationship should therefore be allowed to develop naturally rather than immediately becoming perfect simply because they share blood.","worldConnections":"Ignis Peaks\n\nConnection: Primary home\n\nIfe lives within Moltenmaw Caverns and is deeply connected to the inhabitants and culture of her father''s elemental domain.\n\nMoltenmaw Caverns\n\nConnection: Residence\n\nHer primary home within the Ignis Peaks.\n\nThe Sunna\n\nConnection: Personal sanctuary\n\nThe massive lava pool belonging to Ignis has become one of Ife''s favorite resting places.\n\nShe frequently sleeps beneath its surface.\n\nSunken Dominion\n\nConnection: Maternal ancestral realm\n\nThrough Leviathans, Ife possesses bloodline and elemental ties to the waters of the world and their inhabitants.\n\nTerrax\n\nConnection: Extended family\n\nRuchika''s father, Terrax, connects Ife indirectly to the Earth Primordial branch of the family.\n\nAetheros\n\nConnection: Extended family\n\nEzra''s mother, Aetheros, connects Ife indirectly to the Air Primordial branch.\n\nThe Wider Primordial Family\n\nIfe occupies an unusually central position within the elemental family tree.\n\nHer immediate relationships connect her to:\n\nFire — Ignis\n\nWater — Leviathans\n\nEarth — through Ruchika and Terrax\n\nAir — through Ezra and Aetheros\n\nBlood — Rahim\n\nBone — Ruchika\n\nLightning — Ezra\n\nAsh — AshóNodia\n\nThis makes Ife one of the strongest relational bridges between the different Primordial Dragon branches.","relationshipNotes":"Ife''s relationships are fundamentally shaped by one trait:\n\nShe protects people.\n\nBut she does not express affection identically with everyone.\n\nWith Ignis\n\nLove often appears through combat, teasing, endurance, and simply spending time in the same space.\n\nWith Leviathans\n\nThe relationship is quieter and more fluid, reflecting patience, understanding, and Ife''s connection to the other half of her elemental identity.\n\nWith Rahim\n\nProtection becomes worry.\n\nHis disappearance represents something Ife cannot simply solve with strength.\n\nWith Ruchika\n\nProtection becomes trust.\n\nThe Bone Dragon Whip physically represents that bond.\n\nWith Ezra\n\nAffection frequently disguises itself as irritation and competition.\n\nThey can annoy each other tremendously while remaining fiercely loyal siblings.\n\nWith Ash\n\nThere is currently only an unknown blood connection.\n\nThe relationship itself has not begun yet.\n\nThat distinction is important.\n\nBlood may make Ash her brother.\n\nIt does not automatically create trust, familiarity, or emotional intimacy.\n\nThose things must develop after they meet.\n\nIfe''s Relationship Pattern\n\nIfe tends to become the guardian within relationships.\n\nShe remembers people''s needs.\n\nShe notices danger.\n\nShe intervenes.\n\nShe places herself between threats and people she loves.\n\nBut this creates one recurring problem:\n\nIfe is much better at protecting people than allowing people to protect her.\n\nHer strongest relationships will eventually challenge that habit.\n\nThe people closest to Ife should not merely become individuals standing behind her protection.\n\nThey should become the people willing to step forward and stand beside her.\n\nThat distinction is essential to her emotional development.\n\nIfe begins with:\n\n“Stay behind me.”\n\nHer healthiest relationships eventually teach her:\n\n“Stand beside me.”"},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}','2026-09-25T07:31:23.006566+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('9ad50fd3-4d69-4141-97d5-d06fe20f2249','studio_characters','b2d998c0-1754-4a6a-af91-281d65ded816','Shuǐmǔ Lánhuá','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"b2d998c0-1754-4a6a-af91-281d65ded816","name":"Shuǐmǔ Lánhuá","media":{"tbdFields":"Birth date\nBirthplace\nApparent age\nHeight\nWeight\nDominant hand\nNationality\nExact weaknesses\nExact power limitations\nFormal signature techniques\nPartner status\nFull story arc\nExact sovereignty structure of her children","canonLocks":"Name: Shuǐmǔ Lánhuá\nHuman title: Lady Lánhuá\nDivine title: Shuǐmǔ Tiān Hòu\nFemale\nAsian heritage\nPrimordial\nLiving embodiment of Water\nRules the Sunken Domain\nSunken Domain encompasses the world''s waters\nSunken Domain is not within Aethelgard\nMother of Rahim\nMother of Ife\nMother of Ruchika\nIgnis is father of Rahim and Ife\nTerrax is father of Ruchika\nIfe is the Steam Dragon\nRuchika is the Bone Dragon\nRahim is the Blood Dragon\nRahim is currently lost\nIfe lives with her father\nRuchika lives with his father\nIfe and Ruchika visit their mother\nTrue form is an Eastern-style aquatic leviathan","galleryUrl":"","mediaNotes":"Maintain exact visual continuity between her established portrait, human-form production sheet, dragon form, and dragon production sheet. Future artwork should preserve her face, black hair, ocean-blue eyes, imperial aquatic aesthetic, signature palette, and Eastern-style leviathan design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nDragon Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nLeft View — Done\nRight View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nExpression Sheet — Needed\nCombat Reference — Needed","productionNotes":"Use the established production sheet as the primary visual reference for Lánhuá. Her human design should remain elegant, ancient, and imperial with long black hair, ocean-blue eyes, ornate aquatic hairpieces, and layered blue ceremonial robes. Her dragon form must remain a colossal Eastern-style aquatic leviathan with an elongated serpentine body, iridescent blue-teal scales, luminous aquatic mane, and water-and-mist manifestations.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/reference/1790319612245-shu-m-l-nhu-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/alternate/1790319622886-shu-m-l-nhu-alternate-true-form.png"},"status":"draft","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Unknown","era":"Ancient","name":"Shuǐmǔ Lánhuá","race":"Primordial","alias":"Lady Lánhuá","gender":"Female","titles":"Shuǐmǔ Tiān Hòu\nHeavenly Empress, Mother of All Waters\nThe Splendid Orchid\nMother of All Waters","subrace":"Living Embodiment of Water","summary":"Shuǐmǔ Lánhuá is the ancient Primordial and living embodiment of Water itself. She does not merely command water; oceans, seas, ice, rain, mist, currents, and other natural forms of water are expressions of her primordial existence. Known among mortals as Lady Lánhuá, she rules the Sunken Domain, which encompasses the world''s waters rather than existing within Aethelgard. She is the mother of Rahim, Ife, and Ruchika.","heritage":"Asian","homeland":"Sunken Domain","pronouns":"She/Her","birthDate":"TBD","nicknames":"","occupation":"Primordial Sovereign of Water","affiliation":"Sunken Domain","apparentAge":"TBD","canonStatus":"Canon","nameMeaning":"The Splendid Orchid, Mother of Waters","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"Sunken Domain","elementalHeritage":"Primordial Water"},"abilities":{"weapons":"","strengths":"Elemental fluidity\nExtreme water pressure\nEnvironmental control\nAquatic dominion\nAncient primordial power","weaknesses":"TBD","combatStyle":["Fluid","Defensive","Environmental","Pressure-based","Large-scale elemental control"],"limitations":["TBD"],"powerSource":["Primordial Water","Living embodiment of Water"],"abilityNotes":"Her authority over water comes from being its primordial embodiment, not from conventional learned water magic. Exact limits and interactions with other Primordials remain TBD.\n\nDo not classify Lánhuá as a Dragon Primal who merely rules water. She is a Primordial and the living embodiment of Water itself.","combatProfile":"Lánhuá fights as an elemental force rather than a conventional warrior. She changes water between liquid, ice, mist, and highly compressed states while manipulating currents, pressure, and surrounding moisture. Her movements remain controlled and graceful until extreme anger causes her power to become devastatingly violent.","weaponDetails":"","transformations":"Human Form\nAbyssal Leviathan Form","primaryAbilities":"Absolute water manipulation\nPhase manipulation\nHydrostatic pressure manipulation\nIce manipulation\nMist manipulation\nRain manipulation\nCurrent manipulation\nAbyssal command","secondaryAbilities":"Water compression\nTemperature manipulation\nAquatic telepathy\nSea-life command\nAtmospheric moisture manipulation","signatureTechniques":"TBD","transformationDetails":"Lánhuá can manifest as a colossal Eastern-style aquatic dragon or sea serpent. Her elongated body carries iridescent midnight-blue, teal, and seafoam scales with a flowing bioluminescent mane. Rather than conventional leathery wings, her established dragon design can manifest immense wings formed from compressed water, mist, and atmospheric moisture."},"is_public":true,"appearance":{"build":["Slender","Graceful","Regal"],"nails":["TBD"],"eyeHex":["TBD"],"height":"TBD","makeup":["Subtle","Elegant"],"weight":"TBD","hairHex":["#090D18"],"skinHex":["TBD"],"eyeColor":["Ocean blue"],"grooming":"Immaculate and imperial.","skinTone":["Fair"],"wardrobe":"Layered ceremonial robes\nImperial water-themed gowns\nFlowing silk garments","hairColor":["Black"],"hairStyle":"Very long black hair styled with ornate water-themed hairpieces.","accessories":"Ice orchid hair ornaments\nOrnate hairpins\nWater-drop earrings\nDragon-scale necklace\nWater orb pendant\nJade ornaments","faceDetails":["Elegant features","Regal expression","Refined facial structure"],"hairTexture":["Straight","Silky"],"colorPalette":"Midnight blue #071A33\nDeep teal #07566B\nSeafoam #67C8C2\nTurquoise #46CFE0\nSilver #C8D5DF\nPearl white #EEF3F4","dominantHand":"TBD","outfitColors":"Midnight blue\nDeep teal\nTurquoise\nSilver\nPearl white","alternateForm":["Abyssal Leviathan","Eastern-style sea dragon"],"clothingStyle":"Regal 500–1300 AD-inspired Asian fantasy clothing with flowing silhouettes, layered silks, wave motifs, and refined ornamentation.","appearanceNotes":"Her human design should feel ancient, serene, elegant, and unmistakably connected to the ocean. Her clothing and hair should appear to move with subtle underwater fluidity even on land. Maintain the established midnight-blue, teal, turquoise, silver, and pearl palette across all artwork.","outfitMaterials":["Silk","Translucent silk","Fine embroidery"],"postureMovement":["Poised","Fluid","Controlled"],"signatureOutfit":"Flowing multi-layered imperial robes inspired by 500–1300 AD Asian dress, combining midnight blue, deep teal, silver, and translucent water-like layers. Fine wave and orchid motifs decorate the fabric.","distinguishingFeatures":["Ocean-blue eyes","Very long black hair","Water-themed hair ornaments","Regal presence"]},"created_at":"2026-09-25T06:48:09.359491+00:00","updated_at":"2026-09-25T07:09:49.555672+00:00","is_complete":false,"origin_lore":{"fears":["TBD"],"goals":["Protect the Sunken Domain","Preserve aquatic life","Safeguard her family"],"beliefs":["Water sustains life","Water must remain balanced"],"culture":["Ancient aquatic court","Asian-inspired imperial aesthetic"],"lineage":"Primordial embodiment of Water.","storyArc":"Her larger story arc remains TBD. Rahim''s disappearance creates an unresolved thread within her family, while Ife and Ruchika maintain connections to her domain despite residing with their fathers.","backstory":"Lánhuá is one of the ancient Primordials and the living embodiment of Water. Her sovereignty is not limited to a single ocean or continent; the Sunken Domain encompasses the waters of the world. Her unions with Ignis produced Rahim and Ife, while her union with Terrax produced Ruchika. Although Ife and Ruchika reside with their fathers, they remain connected to their mother''s domain and visit her. Rahim is currently lost, and his absence remains unresolved.","childhood":"TBD","lifestyle":["Rules the Sunken Domain","Oversees the waters of the world","Receives visits from her children"],"storyRole":"Lánhuá serves as the primordial embodiment of Water and sovereign of the Sunken Domain. Her existence connects the oceans, aquatic civilizations, and several elemental bloodlines through her children Rahim, Ife, and Ruchika.","birthplace":"TBD","psychology":["Emotionally restrained","Deeply maternal","Patient observer","Terrifying when enraged"],"motivations":["Protect her children","Preserve the waters","Maintain natural balance"],"personality":["Patient","Calm","Soft-spoken","Graceful","Observant","Maternal","Protective","Formidable"],"voiceSpeech":["Soft-spoken","Measured","Regal","Controlled"],"likesDislikes":["TBD"],"majorLifeEvents":"Union with Ignis\nBirth of Rahim\nBirth of Ife\nUnion with Terrax\nBirth of Ruchika\nRahim disappeared\nIfe resides with Ignis\nRuchika resides with Terrax"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b2d998c0-1754-4a6a-af91-281d65ded816/portrait/1790319597422-shu-m-l-nhu-character-portrait.png","relationships":{"allies":"TBD","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"Rahim — Son; Blood Dragon; child with Ignis; currently lost\nIfe — Daughter; Steam Dragon; child with Ignis; resides with her father and visits Lánhuá\nRuchika — Son; Bone Dragon; child with Terrax; resides with his father and visits Lánhuá","siblings":"","worldConnections":"Ignis — Father of Rahim and Ife\nTerrax — Father of Ruchika\nSunken Domain — Her primordial realm\nWorld waters — Her elemental existence","relationshipNotes":"Lánhuá is the mother of Rahim, Ife, and Ruchika. Rahim and Ife are her children with Ignis, while Ruchika is her child with Terrax. Ife and Ruchika live with their fathers but retain a connection and form of sovereignty within their mother''s waters and continue to visit her. Rahim remains lost; his established disappearance and story should not be overwritten."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"065f06b5-4812-4543-9430-02830d72ae0b","workflow_status":"draft","family_record_id":"3e083a30-190f-4d2e-a61c-605c24c21769","faction_record_id":"9eabcca3-b901-4fdb-92da-03d6ab2a98c5"}','2026-09-25T07:47:57.655277+00:00');
